function AnamnesisScreen({ onNav }) {
  const [paso, setPaso] = useState(1);
  const [lightbox, setLightbox] = useState(null);
  const totalPasos = 4;
  const [form, setForm] = useState({
    nombre: "", edad: "", sexo: "", ocupacion: "", actividadLaboral: "",
    instagram: "", whatsapp: "",
    peso: "", estatura: "", porcGrasa: "", objetivo: "",
    haEntrenado: "", queEntrenamiento: "", diasSemana: "", horarioEntreno: "", horarioEntrenoHasta: "",
    enfermedadLesion: "", cualEnfermedad: "", medicamento: "", cualMedicamento: "",
    sustanciaFarmacologica: "", sustanciaCuales: "", sustanciaTiempo: "", sustanciaHaceCuanto: "",
    consumeSuplemento: "", cualSuplemento: "",
    alimentacionDiferente: "", alergia: "", cualAlergia: "",
    noLeGustan: "", favoritos: "",
    horaLevanta: "", horaDuerme: "", comidasDia: "", resumenComida: "",
  });

  const set = (k, v) => setForm(prev => ({ ...prev, [k]: v }));

  const [fotosArchivos, setFotosArchivos] = useState({ fotoFrente: null, fotoEspalda: null, fotoPerfDer: null, fotoPerfIzq: null });
  const [enviandoAnamnesis, setEnviandoAnamnesis] = useState(false);

  const comprimirFoto = (file) => {
    return new Promise((resolve) => {
      const canvas = document.createElement("canvas");
      const ctx = canvas.getContext("2d");
      const img = new Image();
      img.onload = () => {
        const MAX = 800;
        let w = img.width, h = img.height;
        if (w > h && w > MAX) { h = h * MAX / w; w = MAX; }
        else if (h > MAX) { w = w * MAX / h; h = MAX; }
        canvas.width = w; canvas.height = h;
        ctx.drawImage(img, 0, 0, w, h);
        canvas.toBlob(resolve, "image/jpeg", 0.7);
      };
      img.src = URL.createObjectURL(file);
    });
  };

  const handleFoto = async (key, file) => {
    if (!file) return;
    set(key, file.name);
    const compressed = await comprimirFoto(file);
    setFotosArchivos(prev => ({ ...prev, [key]: compressed }));
  };

  const subirFoto = async (userId, key, blob) => {
    if (!blob) return null;
    const path = `${userId}/anamnesis/${key}.jpg`;
    const { error } = await supabase.storage
      .from("fotos-alumnos")
      .upload(path, blob, { contentType: "image/jpeg", upsert: true });
    if (error) return null;
    return `https://srlucwsakjuivogvunzx.supabase.co/storage/v1/object/public/fotos-alumnos/${path}`;
  };

  const inputStyle = {
    background: theme.surface, border: `1px solid ${theme.border}`,
    borderRadius: 10, padding: "11px 14px", color: theme.text,
    fontSize: 13, width: "100%", outline: "none", boxSizing: "border-box", marginTop: 6
  };
  const labelStyle = { fontSize: 12, color: theme.muted, fontWeight: 600, marginTop: 12, display: "block" };
  const selectStyle = { ...inputStyle, appearance: "none" };

  const opciones = (arr) => arr.map(o => <option key={o} value={o}>{o}</option>);

  return (
    <div style={{ height: "100%", display: "flex", flexDirection: "column" }}>
      {/* Header */}
      <div style={{ padding: "16px 16px 12px", background: theme.surface, borderBottom: `1px solid ${theme.border}` }}>
        <div style={{ fontSize: 11, color: theme.muted, marginBottom: 4 }}>PASO {paso} DE {totalPasos}</div>
        <div style={{ fontSize: 17, fontWeight: 800, color: theme.text }}>
          {paso === 1 && "Datos Personales"}
          {paso === 2 && "Físico y Objetivo"}
          {paso === 3 && "Entrenamiento y Salud"}
          {paso === 4 && "Alimentación y Hábitos"}
        </div>
        {/* Barra de progreso */}
        <div style={{ background: theme.border, borderRadius: 4, height: 4, marginTop: 10 }}>
          <div style={{ width: `${(paso / totalPasos) * 100}%`, height: "100%", background: theme.accent, borderRadius: 4, transition: "width 0.3s" }} />
        </div>
      </div>

      {/* Contenido por paso */}
      <div style={{ flex: 1, overflowY: "auto", padding: "16px 16px 20px" }}>

        {/* PASO 1 — Datos personales */}
        {paso === 1 && (
          <div>
            <span style={labelStyle}>Nombre completo *</span>
            <input style={inputStyle} placeholder="Tu nombre completo" value={form.nombre} onChange={e => set("nombre", e.target.value)} />

            <span style={labelStyle}>Edad *</span>
            <input style={inputStyle} placeholder="Ej: 28" type="number" value={form.edad} onChange={e => set("edad", e.target.value)} />

            <span style={labelStyle}>Sexo *</span>
            <select style={selectStyle} value={form.sexo} onChange={e => set("sexo", e.target.value)}>
              <option value="">Selecciona...</option>
              {opciones(["Masculino", "Femenino", "Otro"])}
            </select>

            <span style={labelStyle}>Ocupación *</span>
            <input style={inputStyle} placeholder="Ej: Ingeniero, Estudiante, Vendedor..." value={form.ocupacion} onChange={e => set("ocupacion", e.target.value)} />

            <span style={labelStyle}>Describe tu actividad laboral diaria</span>
            <textarea style={{ ...inputStyle, minHeight: 70, resize: "none" }}
              placeholder="Ej: Trabajo sentado frente a un computador 8 horas, poca actividad física..."
              value={form.actividadLaboral} onChange={e => set("actividadLaboral", e.target.value)} />

            <span style={labelStyle}>WhatsApp</span>
            <input style={inputStyle} placeholder="+56 9 XXXX XXXX" value={form.whatsapp} onChange={e => set("whatsapp", e.target.value)} />

            <span style={labelStyle}>Instagram (opcional)</span>
            <input style={inputStyle} placeholder="@usuario" value={form.instagram} onChange={e => set("instagram", e.target.value)} />
          </div>
        )}

        {/* PASO 2 — Físico y objetivo */}
        {paso === 2 && (
          <div>
            <span style={labelStyle}>Peso actual (kg) *</span>
            <input style={inputStyle} placeholder="Ej: 80" type="number" value={form.peso} onChange={e => set("peso", e.target.value)} />

            <span style={labelStyle}>Estatura (cm) *</span>
            <input style={inputStyle} placeholder="Ej: 175" type="number" value={form.estatura} onChange={e => set("estatura", e.target.value)} />

            <span style={labelStyle}>Porcentaje de grasa estimado (%)</span>
            <input style={inputStyle} placeholder="Ej: 20" type="number" value={form.porcGrasa} onChange={e => set("porcGrasa", e.target.value)} />
            <div style={{ marginTop: 8, marginBottom: 4, background: "rgba(167,139,250,0.08)", borderRadius: 10, padding: 10 }}>
              <div style={{ fontSize: 11, color: "#B0C4DE", fontWeight: 700, marginBottom: 6 }}>📊 Referencia % grasa corporal</div>
              <div style={{ fontSize: 10, color: "#888", marginBottom: 6 }}>Compárate con la imagen y estima tu porcentaje</div>
              <img src={GRASA_IMG} alt="Referencia % grasa" onClick={() => setLightbox(GRASA_IMG)} style={{ width: "100%", borderRadius: 6, cursor: "pointer", display: "block" }} />
            </div>
            <div style={{ fontSize: 11, color: theme.muted, marginTop: 4 }}>Si no lo sabes, deja en blanco</div>

            <span style={labelStyle}>¿Cuál es tu objetivo principal? *</span>
            <select style={selectStyle} value={form.objetivo} onChange={e => set("objetivo", e.target.value)}>
              <option value="">Selecciona...</option>
              {opciones(["Bajar grasa", "Ganar masa muscular", "Recomposición corporal", "Mejorar rendimiento deportivo", "Mantener peso y mejorar salud"])}
            </select>
          </div>
        )}

        {/* PASO 3 — Entrenamiento y salud */}
        {paso === 3 && (
          <div>
            <span style={labelStyle}>¿Ha entrenado en gimnasio o realiza algún deporte? *</span>
            <select style={selectStyle} value={form.haEntrenado} onChange={e => set("haEntrenado", e.target.value)}>
              <option value="">Selecciona...</option>
              {opciones(["Sí", "No"])}
            </select>

            {form.haEntrenado === "Sí" && (
              <>
                <span style={labelStyle}>Especifique qué entrenamiento o deporte</span>
                <input style={inputStyle} placeholder="Ej: Gym 3 veces por semana, fútbol..." value={form.queEntrenamiento} onChange={e => set("queEntrenamiento", e.target.value)} />
              </>
            )}

            <span style={labelStyle}>¿Cuántas veces a la semana pretendes entrenar? *</span>
            <select style={selectStyle} value={form.diasSemana} onChange={e => set("diasSemana", e.target.value)}>
              <option value="">Selecciona...</option>
              {opciones(["1 día", "2 días", "3 días", "4 días", "5 días", "6 días"])}
            </select>

            <span style={labelStyle}>¿En qué horario pretendes entrenar? *</span>
            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <input type="time" style={{ ...inputStyle, flex: 1 }} value={form.horarioEntreno} onChange={e => set("horarioEntreno", e.target.value)} />
              <span style={{ color: theme.muted, fontSize: 12 }}>y</span>
              <input type="time" style={{ ...inputStyle, flex: 1 }} value={form.horarioEntrenoHasta} onChange={e => set("horarioEntrenoHasta", e.target.value)} />
            </div>

            <span style={labelStyle}>¿Tiene alguna enfermedad o lesión? *</span>
            <select style={selectStyle} value={form.enfermedadLesion} onChange={e => set("enfermedadLesion", e.target.value)}>
              <option value="">Selecciona...</option>
              {opciones(["Sí", "No"])}
            </select>

            {form.enfermedadLesion === "Sí" && (
              <>
                <span style={labelStyle}>Especifique qué enfermedad o lesión</span>
                <input style={inputStyle} placeholder="Ej: Dolor lumbar, rodilla operada..." value={form.cualEnfermedad} onChange={e => set("cualEnfermedad", e.target.value)} />
              </>
            )}

            <span style={labelStyle}>¿Toma algún medicamento actualmente?</span>
            <select style={selectStyle} value={form.medicamento} onChange={e => set("medicamento", e.target.value)}>
              <option value="">Selecciona...</option>
              {opciones(["Sí", "No"])}
            </select>

            {form.medicamento === "Sí" && (
              <>
                <span style={labelStyle}>Especifique qué medicamento</span>
                <input style={inputStyle} placeholder="Ej: Metformina, Levotiroxina..." value={form.cualMedicamento} onChange={e => set("cualMedicamento", e.target.value)} />
              </>
            )}

            <span style={labelStyle}>¿Consume o ha consumido sustancias farmacológicas para aumentar masa muscular o rendimiento? (esteroides, etc.)</span>
            <select style={selectStyle} value={form.sustanciaFarmacologica} onChange={e => set("sustanciaFarmacologica", e.target.value)}>
              <option value="">Selecciona...</option>
              {opciones(["Sí", "No", "Prefiero no responder"])}
            </select>

            {form.sustanciaFarmacologica === "Sí" && (
              <>
                <span style={labelStyle}>Especifique qué sustancias</span>
                <input style={inputStyle} placeholder="Ej: Testosterona, Oxandrolona..." value={form.sustanciaCuales} onChange={e => set("sustanciaCuales", e.target.value)} />

                <span style={labelStyle}>¿Por cuánto tiempo las consumió/consume?</span>
                <input style={inputStyle} placeholder="Ej: 8 semanas, 3 meses..." value={form.sustanciaTiempo} onChange={e => set("sustanciaTiempo", e.target.value)} />

                <span style={labelStyle}>¿Hace cuánto tiempo fue eso?</span>
                <input style={inputStyle} placeholder="Ej: Hace 1 año, actualmente..." value={form.sustanciaHaceCuanto} onChange={e => set("sustanciaHaceCuanto", e.target.value)} />
              </>
            )}

            <span style={labelStyle}>¿Consume algún suplemento alimenticio o deportivo actualmente?</span>
            <select style={selectStyle} value={form.consumeSuplemento} onChange={e => set("consumeSuplemento", e.target.value)}>
              <option value="">Selecciona...</option>
              {opciones(["Sí", "No"])}
            </select>

            {form.consumeSuplemento === "Sí" && (
              <>
                <span style={labelStyle}>Especifique cuál</span>
                <input style={inputStyle} placeholder="Ej: Creatina, proteína, pre-entreno..." value={form.cualSuplemento} onChange={e => set("cualSuplemento", e.target.value)} />
              </>
            )}
          </div>
        )}

        {/* PASO 4 — Alimentación */}
        {paso === 4 && (
          <div>
            <span style={labelStyle}>¿Lleva algún tipo de alimentación especial?</span>
            <input style={inputStyle} placeholder="Ej: Vegetariano, Keto, Sin gluten..." value={form.alimentacionDiferente} onChange={e => set("alimentacionDiferente", e.target.value)} />

            <span style={labelStyle}>¿Es alérgico a algún alimento, suplemento o medicamento?</span>
            <select style={selectStyle} value={form.alergia} onChange={e => set("alergia", e.target.value)}>
              <option value="">Selecciona...</option>
              {opciones(["Sí", "No"])}
            </select>

            {form.alergia === "Sí" && (
              <>
                <span style={labelStyle}>Especifique a qué</span>
                <input style={inputStyle} placeholder="Ej: Mariscos, lactosa, aspirina..." value={form.cualAlergia} onChange={e => set("cualAlergia", e.target.value)} />
              </>
            )}

            <span style={labelStyle}>¿Qué alimentos no le gustan?</span>
            <input style={inputStyle} placeholder="Ej: Brócoli, hígado, pescado..." value={form.noLeGustan} onChange={e => set("noLeGustan", e.target.value)} />

            <span style={labelStyle}>¿Cuáles son sus alimentos favoritos?</span>
            <input style={inputStyle} placeholder="Ej: Pollo, arroz, frutas..." value={form.favoritos} onChange={e => set("favoritos", e.target.value)} />

            <span style={labelStyle}>¿A qué hora se levanta?</span>
            <input type="time" style={inputStyle} value={form.horaLevanta} onChange={e => set("horaLevanta", e.target.value)} />

            <span style={labelStyle}>¿A qué hora se duerme?</span>
            <input type="time" style={inputStyle} value={form.horaDuerme} onChange={e => set("horaDuerme", e.target.value)} />

            <span style={labelStyle}>¿Cuántas comidas y/o colaciones haces al día?</span>
            <select style={selectStyle} value={form.comidasDia} onChange={e => set("comidasDia", e.target.value)}>
              <option value="">Selecciona...</option>
              {opciones(["1", "2", "3", "4", "5", "6", "Más de 6"])}
            </select>

            <span style={labelStyle}>Resumen de lo que comes en un día típico</span>
            <div style={{ background: theme.surface, border: `1px solid ${theme.border}`, borderRadius: 10, overflow: "hidden", marginTop: 6 }}>
              {[
                { key: "desayuno", label: "🌅 Desayuno", placeholder: "Ej: 2 huevos, avena, café..." },
                { key: "snack", label: "🍎 Snack", placeholder: "Ej: Fruta, yogur, nueces..." },
                { key: "almuerzo", label: "🍽️ Almuerzo", placeholder: "Ej: Arroz, pollo, ensalada..." },
                { key: "once", label: "☕ Once", placeholder: "Ej: Pan, queso, té..." },
                { key: "cena", label: "🌙 Cena", placeholder: "Ej: Carne, papas, verduras..." },
              ].map((c, i) => (
                <div key={c.key} style={{ borderBottom: i < 4 ? `1px solid ${theme.border}` : "none" }}>
                  <div style={{ fontSize: 11, fontWeight: 700, color: theme.muted, padding: "8px 12px 2px", background: theme.card }}>{c.label}</div>
                  <input
                    style={{ background: "transparent", border: "none", padding: "6px 12px 10px", color: theme.text, fontSize: 12, width: "100%", outline: "none", boxSizing: "border-box" }}
                    placeholder={c.placeholder}
                    value={form[c.key] || ""}
                    onChange={e => set(c.key, e.target.value)}
                  />
                </div>
              ))}
            </div>

            <span style={labelStyle}>📸 Fotos corporales iniciales</span>
            <div style={{ fontSize: 11, color: theme.muted, marginBottom: 8, marginTop: 4 }}>Se guardarán para comparar tu progreso cada 4 semanas</div>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
              {[
                { key: "fotoFrente", label: "Frente", emoji: "👤" },
                { key: "fotoEspalda", label: "Espalda", emoji: "🔙" },
                { key: "fotoPerfDer", label: "Perfil derecho", emoji: "➡️" },
                { key: "fotoPerfIzq", label: "Perfil izquierdo", emoji: "⬅️" },
              ].map(f => (
                <label key={f.key} style={{
                  background: form[f.key] ? `${theme.success}18` : theme.surface,
                  border: `1px dashed ${form[f.key] ? theme.success : theme.border}`,
                  borderRadius: 10, padding: "14px 8px",
                  display: "flex", flexDirection: "column", alignItems: "center",
                  justifyContent: "center", gap: 6, cursor: "pointer", textAlign: "center"
                }}>
                  <span style={{ fontSize: 24 }}>{form[f.key] ? "✅" : f.emoji}</span>
                  <span style={{ fontSize: 11, color: form[f.key] ? theme.success : theme.muted, fontWeight: 600 }}>
                    {form[f.key] ? "Foto cargada" : f.label}
                  </span>
                  <input type="file" accept="image/*" style={{ display: "none" }}
                    onChange={e => handleFoto(f.key, e.target.files[0])} />
                </label>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Botones navegación */}
      <div style={{ padding: "12px 16px", background: theme.surface, borderTop: `1px solid ${theme.border}`, display: "flex", gap: 10 }}>
        {paso > 1 && (
          <button onClick={() => setPaso(paso - 1)} style={{
            flex: 1, background: "transparent", border: `1px solid ${theme.border}`,
            borderRadius: 10, padding: "12px", color: theme.muted,
            fontSize: 14, fontWeight: 700, cursor: "pointer"
          }}>← Anterior</button>
        )}
        {paso < totalPasos ? (
          <button onClick={() => setPaso(paso + 1)} style={{
            flex: 2, background: theme.accent, border: "none",
            borderRadius: 10, padding: "12px", color: "#fff",
            fontSize: 14, fontWeight: 700, cursor: "pointer"
          }}>Siguiente →</button>
        ) : (
          <button disabled={enviandoAnamnesis} onClick={async () => {
            if (enviandoAnamnesis) return;
            setEnviandoAnamnesis(true);
            try {
              const { data: { user } } = await supabase.auth.getUser();
              if (user) {
                const urlFrente = fotosArchivos.fotoFrente ? await subirFoto(user.id, "frente", fotosArchivos.fotoFrente) : null;
                const urlEspalda = fotosArchivos.fotoEspalda ? await subirFoto(user.id, "espalda", fotosArchivos.fotoEspalda) : null;
                const urlPerfDer = fotosArchivos.fotoPerfDer ? await subirFoto(user.id, "perfDer", fotosArchivos.fotoPerfDer) : null;
                const urlPerfIzq = fotosArchivos.fotoPerfIzq ? await subirFoto(user.id, "perfIzq", fotosArchivos.fotoPerfIzq) : null;
const { error } = await supabase.from("usuarios").upsert({                  id: user.id,
                  nombre: form.nombre,
                  email: user.email,
                  edad: parseInt(form.edad) || null,
                  sexo: form.sexo,
                  ocupacion: form.ocupacion,
                  actividad_laboral: form.actividadLaboral,
                  whatsapp: form.whatsapp,
                  instagram: form.instagram,
                  peso_actual: parseFloat(form.peso) || null,
                  estatura: parseFloat(form.estatura) || null,
                  porc_grasa: parseFloat(form.porcGrasa) || null,
                  objetivo: form.objetivo,
                  ha_entrenado: form.haEntrenado,
                  que_entrenamiento: form.queEntrenamiento,
                  dias_semana: form.diasSemana,
                  horario_entreno: form.horarioEntreno,
                  horario_entreno_hasta: form.horarioEntrenoHasta,
                  enfermedad_lesion: form.enfermedadLesion,
                  cual_enfermedad: form.cualEnfermedad,
                  medicamento: form.medicamento,
                  cual_medicamento: form.cualMedicamento,
                  sustancia_farmacologica: form.sustanciaFarmacologica,
                  sustancia_cuales: form.sustanciaCuales,
                  sustancia_tiempo: form.sustanciaTiempo,
                  sustancia_hace_cuanto: form.sustanciaHaceCuanto,
                  consume_suplemento: form.consumeSuplemento,
                  cual_suplemento: form.cualSuplemento,
                  alimentacion_diferente: form.alimentacionDiferente,
                  alergia: form.alergia,
                  cual_alergia: form.cualAlergia,
                  no_le_gustan: form.noLeGustan,
                  favoritos: form.favoritos,
                  hora_levanta: form.horaLevanta,
                  hora_duerme: form.horaDuerme,
                  comidas_dia: form.comidasDia,
                  resumen_desayuno: form.desayuno,
                  resumen_snack: form.snack,
                  resumen_almuerzo: form.almuerzo,
                  resumen_once: form.once,
                  resumen_cena: form.cena,
                  foto_frente: urlFrente,
                  foto_espalda: urlEspalda,
                  foto_perf_der: urlPerfDer,
                  foto_perf_izq: urlPerfIzq,
                }, { onConflict: "id" });
                if (error) { console.error("Error guardando anamnesis:", error.message, error); alert("Error al guardar: " + error.message); setEnviandoAnamnesis(false); return; }
              }
            } catch(e) {
              console.error("Error:", e);
              alert("Error inesperado: " + e.message);
              setEnviandoAnamnesis(false);
              return;
            }
            setEnviandoAnamnesis(false);
            onNav("alumno_home");
          }} style={{
            flex: 2, background: theme.success, border: "none",
            borderRadius: 10, padding: "12px", color: "#fff",
            fontSize: 14, fontWeight: 800, cursor: "pointer"
          }}>{enviandoAnamnesis ? "Guardando..." : "✓ Enviar y comenzar"}</button>
        )}
      </div>
      <ImageLightbox src={lightbox} onClose={() => setLightbox(null)} />
    </div>
  );
}

function AlumnoHome({ onNav }) {
  const [pagoReportado, setPagoReportado] = useState(false);
  const [nombre, setNombre] = useState("Alumno");
const [rutina, setRutina] = useState(null);
const [tieneRutinas, setTieneRutinas] = useState(false);
const [estadoPago, setEstadoPago] = useState(null);
  const [checkin, setCheckin] = useState(null);
  const [dieta, setDieta] = useState(null);
  const [semana, setSemana] = useState(null); const [mensajesNoLeidos, setMensajesNoLeidos] = useState(0); const pagoVencido = false;
  const [ultimoMensajeCoach, setUltimoMensajeCoach] = useState(null);
  const [suplementosPendientes, setSuplementosPendientes] = useState(0);
  const [pasosHoy, setPasosHoy] = useState("");
  const [guardandoPasos, setGuardandoPasos] = useState(false);
  const [pasosGuardado, setPasosGuardado] = useState(false);
  const [cardioRegistrosHoy, setCardioRegistrosHoy] = useState({});
  const [userIdHome, setUserIdHome] = useState(null);
  const diasRestantes = 2;

  const guardarPasosHome = async () => {
    if (!userIdHome) return;
    setGuardandoPasos(true);
    const { error } = await supabase.from("pasos_registros").upsert({ usuario_id: userIdHome, fecha: fechaOperativaStr(), pasos: pasosHoy ? parseInt(pasosHoy) : null }, { onConflict: "usuario_id,fecha" });
    setGuardandoPasos(false);
    if (error) { alert("No se pudieron guardar los pasos: " + error.message); return; }
    setPasosGuardado(true);
    setTimeout(() => setPasosGuardado(false), 2500);
  };

  useEffect(() => {
    const cargar = async () => {
      const { data: { user } } = await supabase.auth.getUser();
      if (user) {
        setUserIdHome(user.id);
        const { data: usuario } = await supabase.from("usuarios").select("nombre").eq("id", user.id).single();
        if (usuario?.nombre) setNombre(usuario.nombre.split(" ")[0]);

        const { data: rutinas } = await supabase
          .from("rutinas")
          .select("*, ejercicios(*)")
          .eq("usuario_id", user.id)
          .order("created_at", { ascending: false });
        if (rutinas && rutinas.length > 0) {
          setTieneRutinas(true);
          const nombreHoy = nombreDiaOperativo();
          const rutinaHoy = rutinas.find(r => r.dia === nombreHoy);
          setRutina(rutinaHoy || null);
          if (rutinaHoy && Array.isArray(rutinaHoy.cardio) && rutinaHoy.cardio.length > 0) {
            const hoyStrCardio = fechaOperativaStr();
            const { data: cardioReg } = await supabase.from("cardio_registros").select("cardio_index, duracion_real, completado, via_pasos").eq("usuario_id", user.id).eq("fecha", hoyStrCardio);
            const mapaCardio = {};
            (cardioReg || []).forEach(r => { mapaCardio[r.cardio_index] = { duracion_real: r.duracion_real, completado: r.completado, via_pasos: r.via_pasos }; });
            setCardioRegistrosHoy(mapaCardio);
          }
        }
        // Los pasos se registran todos los días, tenga o no rutina asignada hoy.
        {
          const hoyStrPasos = fechaOperativaStr();
          const { data: pasosReg } = await supabase.from("pasos_registros").select("pasos").eq("usuario_id", user.id).eq("fecha", hoyStrPasos).maybeSingle();
          setPasosHoy(pasosReg?.pasos != null ? String(pasosReg.pasos) : "");
        }
        const { data: checkins } = await supabase.from("checkins").select("peso").eq("usuario_id", user.id).order("fecha", { ascending: false }).limit(1);
        if (checkins && checkins.length > 0) setCheckin(checkins[0]);
        const { data: dietas } = await supabase.from("dietas").select("calorias, suplementos, dias").eq("usuario_id", user.id).order("created_at", { ascending: false });
        if (dietas && dietas.length > 0) {
          // Mismo criterio que usa NutricionScreen para elegir el plan: el que
          // esté asignado al día de hoy (campo "dias"); si ninguno calza con hoy,
          // se usa el más reciente como respaldo. Antes acá siempre se tomaba el
          // más reciente sin mirar "dias" — si el plan de hoy no era el último
          // creado, se revisaban los suplementos de un plan equivocado (por eso
          // el aviso no salía aunque sí hubiera suplementos cargados).
          const nombreHoyDieta = nombreDiaOperativo();
          const dietaHoy = dietas.find(d => Array.isArray(d.dias) && d.dias.includes(nombreHoyDieta)) || dietas[0];
          setDieta(dietaHoy);
          const suplementosPlan = Array.isArray(dietaHoy.suplementos) ? dietaHoy.suplementos : [];
          if (suplementosPlan.some(s => s.nombre)) {
            const hoyStr = fechaOperativaStr();
            const { data: suplRegs } = await supabase.from("suplemento_registros").select("suplemento_index, tomado").eq("usuario_id", user.id).eq("fecha", hoyStr);
            const marcados = new Set((suplRegs || []).filter(r => r.tomado).map(r => r.suplemento_index));
            setSuplementosPendientes(suplementosPlan.filter((s, i) => s.nombre && !marcados.has(i)).length);
          }
        }
        const { data: pagoData } = await supabase.from("pagos").select("*").eq("usuario_id", user.id).order("created_at", { ascending: false }).limit(1);
        if (pagoData && pagoData.length > 0) {
          const pago = pagoData[0];
          const hoy = new Date();
          const vence = new Date(pago.fecha_vencimiento);
          const diasRestantes = Math.ceil((vence - hoy) / (1000 * 60 * 60 * 24));
          if (pago.estado === "bloqueado") setEstadoPago({ tipo: "bloqueado", dias: 0 });
          else if (diasRestantes <= 3 && diasRestantes >= 0) setEstadoPago({ tipo: "por_vencer", dias: diasRestantes });
          else if (diasRestantes < 0) setEstadoPago({ tipo: "vencido", dias: Math.abs(diasRestantes) });
        }
        const { data: usr } = await supabase.from("usuarios").select("created_at").eq("id", user.id).single();
        if (usr?.created_at) { const inicio = new Date(usr.created_at); const dias = Math.floor((new Date() - inicio) / 86400000); setSemana(Math.floor(dias / 7) + 1); }
        const { data: noLeidos } = await supabase.from("mensajes").select("id").eq("usuario_id", user.id).eq("de", "coach").eq("leido", false);
        if (noLeidos) setMensajesNoLeidos(noLeidos.length);
        const { data: ultimoMsg } = await supabase.from("mensajes").select("texto, created_at").eq("usuario_id", user.id).eq("de", "coach").order("created_at", { ascending: false }).limit(1);
        if (ultimoMsg && ultimoMsg.length > 0) setUltimoMensajeCoach(ultimoMsg[0]);
      }
    };
    cargar();
  }, []);

  return (
    <div style={{ padding: "20px 16px 90px", overflowY: "auto", height: "100%", boxSizing: "border-box" }}>
      {estadoPago?.tipo === "bloqueado" && (
        <div style={{ background:`${theme.danger}15`, border:`1px solid ${theme.danger}55`, borderRadius:14, padding:"14px 16px", marginBottom:16 }}>
          <div style={{ fontSize:14, fontWeight:800, color:theme.danger, marginBottom:4 }}>🔒 Acceso bloqueado</div>
          <div style={{ fontSize:12, color:theme.muted }}>Tu plan está bloqueado por pago pendiente. Contacta a tu coach.</div>
        </div>
      )}
      {estadoPago?.tipo === "por_vencer" && (
        <div style={{ background:`${theme.warning}15`, border:`1px solid ${theme.warning}55`, borderRadius:14, padding:"14px 16px", marginBottom:16 }}>
          <div style={{ fontSize:14, fontWeight:800, color:theme.warning, marginBottom:4 }}>⚠️ Pago vence en {estadoPago.dias} días</div>
          <div style={{ fontSize:12, color:theme.muted, marginBottom:10 }}>Realiza tu transferencia y avísale a tu coach para mantener el acceso.</div>
          <button onClick={async () => {
            const { data:{ user } } = await supabase.auth.getUser();
            if (user) {
              const { data: p } = await supabase.from("pagos").select("id").eq("usuario_id", user.id).order("created_at", { ascending: false }).limit(1);
              if (p && p.length > 0) await supabase.from("pagos").update({ reportado_por_alumno: true }).eq("id", p[0].id);
              setEstadoPago({ ...estadoPago, reportado: true });
            }
          }} style={{ background: estadoPago.reportado ? `${theme.success}22` : theme.accent, border:"none", borderRadius:10, padding:"10px 16px", color:"#fff", fontWeight:700, fontSize:13, cursor:"pointer", width:"100%" }}>
            {estadoPago.reportado ? "✅ Aviso enviado al coach" : "✓ Ya realicé la transferencia"}
          </button>
        </div>
      )}
      {estadoPago?.tipo === "vencido" && (
        <div style={{ background:`${theme.danger}15`, border:`1px solid ${theme.danger}55`, borderRadius:14, padding:"14px 16px", marginBottom:16 }}>
          <div style={{ fontSize:14, fontWeight:800, color:theme.danger, marginBottom:4 }}>❌ Pago vencido hace {estadoPago.dias} días</div>
          <div style={{ fontSize:12, color:theme.muted }}>Contacta a tu coach para regularizar tu situación.</div>
        </div>
      )}
      {suplementosPendientes > 0 && (
        <div onClick={() => onNav("nutricion")} style={{ cursor:"pointer", background:`${theme.warning}15`, border:`1px solid ${theme.warning}55`, borderRadius:14, padding:"12px 16px", marginBottom:16, display:"flex", alignItems:"center", gap:10 }}>
          <span style={{ fontSize:18 }}>⏰</span>
          <div style={{ fontSize:12, color:theme.warning, fontWeight:700 }}>Te falta marcar {suplementosPendientes === 1 ? "un suplemento" : `${suplementosPendientes} suplementos`} de hoy. Toca para verlos.</div>
        </div>
      )}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
        <div>
          <div style={{ color: theme.muted, fontSize: 12, letterSpacing: 1 }}>BUENOS DÍAS</div>
          <div style={{ fontSize: 22, fontWeight: 800, color: theme.text }}>Hola, {nombre} 👋</div>
        </div>
        <div style={{ width: 40, height: 40, borderRadius: 20, background: `linear-gradient(135deg, ${theme.accentLight}, ${theme.accent})`, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 16, fontWeight: 700, color: "#fff", boxShadow: `0 0 16px ${theme.accent}66` }}>
          {nombre[0]?.toUpperCase() || "A"}
        </div>
      </div>

      {(() => {
        // Banco de frases motivacionales, mientras se arma uno más grande con las
        // que ya usa el coach en sus PDFs. Rota una distinta cada día (se van
        // repitiendo cíclicamente una vez se acaban).
        const FRASES_MOTIVACIONALES = [
          "Nuevo día, nueva oportunidad de mejorar. ¡Vamos con todo! 🔥",
          "La disciplina vence al desgano. Un entreno a la vez. 💪",
          "No busques motivación, busca disciplina. Los resultados llegan solos. 🚀",
          "Tu único rival es quien eras ayer. 🏆",
          "El esfuerzo de hoy es el resultado de mañana. 💥",
          "Pequeños progresos diarios generan grandes resultados. 📈",
          "Nadie dijo que sería fácil, pero vale la pena. 🔥",
          "Cada repetición te acerca a tu mejor versión. 💪",
          "El cuerpo logra lo que la mente cree. 🧠",
          "Consistencia por sobre perfección. Sigue sumando días. ✅",
        ];
        let texto = null, autor = "Coach Claudio";
        if (ultimoMensajeCoach) {
          texto = ultimoMensajeCoach.texto;
        } else if (semana === 1) {
          texto = "Bienvenido a Miquel Coach Performance 💪";
        } else {
          const diaIndice = Math.floor(fechaOperativa().getTime() / 86400000);
          texto = FRASES_MOTIVACIONALES[diaIndice % FRASES_MOTIVACIONALES.length];
          autor = null;
        }
        if (!texto) return null;
        return (
          <Card style={{ marginBottom: 14, padding: 14, background: `linear-gradient(135deg, ${theme.accent}22, transparent)`, border: `1px solid ${theme.accent}44`, boxShadow: `0 0 20px ${theme.accent}1a` }}>
            <div style={{ display: "flex", gap: 10, alignItems: "flex-start" }}>
              <div style={{ width: 30, height: 30, borderRadius: 15, background: `linear-gradient(135deg, ${theme.accentLight}, ${theme.accent})`, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 13, color: "#fff", flexShrink: 0, boxShadow: `0 0 12px ${theme.accent}55` }}>{autor ? "M" : "🎯"}</div>
              <div style={{ fontSize: 13, color: theme.text, lineHeight: 1.5 }}>"{texto}"</div>
            </div>
          </Card>
        );
      })()}

      {rutina ? (
        <Card style={{ marginBottom: 14, padding: 10, background: "linear-gradient(145deg,#141428,#1a1a3a)", border: `1px solid ${theme.accentLight}55`, boxShadow: `0 0 24px ${theme.accent}22, inset 0 1px 0 rgba(255,255,255,0.04)` }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8 }}>
            <span style={{ flexShrink: 0, background: `linear-gradient(135deg, ${theme.accentLight}, ${theme.accent})`, color: "#fff", fontSize: 10, fontWeight: 800, padding: "3px 9px", borderRadius: 6, letterSpacing: 1, boxShadow: `0 0 10px ${theme.accent}66` }}>HOY</span>
            <div style={{ flex: 1, minWidth: 0, fontSize: 15, fontWeight: 800, color: theme.text, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{rutina.nombre}</div>
            <span style={{ flexShrink: 0, fontSize: 10, color: theme.muted }}>{rutina.dia || ""}</span>
          </div>
          <button onClick={() => onNav("rutina")} style={{ width: "100%", background: `linear-gradient(135deg, ${theme.accentLight}, ${theme.accent})`, border: "none", borderRadius: 10, padding: "9px", color: "#fff", fontSize: 13, fontWeight: 800, cursor: "pointer", boxShadow: `0 0 18px ${theme.accent}66, 0 2px 8px rgba(0,0,0,0.3)`, letterSpacing: 0.3 }}>Comenzar Entrenamiento →</button>
        </Card>
      ) : (
        <Card style={{ marginBottom: 14, textAlign: "center", padding: 14 }}>
          <div style={{ fontSize: 18, marginBottom: 4 }}>{tieneRutinas ? "😌" : "💪"}</div>
          <div style={{ fontSize: 13, fontWeight: 700, color: theme.text, marginBottom: 2 }}>{tieneRutinas ? "Hoy no te toca entrenar" : "Sin rutina asignada"}</div>
          <div style={{ fontSize: 11, color: theme.muted, marginBottom: tieneRutinas ? 8 : 0 }}>{tieneRutinas ? "Día de descanso 🙌" : "Tu coach aún no ha creado tu plan"}</div>
          {tieneRutinas && (
            <Btn variant="ghost" onClick={() => onNav("rutina")}>¿No entrenaste el día que tocaba? Elige otra rutina</Btn>
          )}
        </Card>
      )}

      {(() => {
        // Los pasos se registran todos los días, tenga o no rutina asignada hoy.
        const meta = rutina?.meta_pasos || 0;
        const actuales = parseInt(pasosHoy) || 0;
        const pct = meta > 0 ? Math.min(100, Math.round((actuales / meta) * 100)) : 0;
        // Solo suma el equivalente en pasos cuando el alumno realmente hizo el
        // cardio (no cuando ya reemplazó la sesión por caminar los pasos --
        // esos pasos ya están contados directamente en su registro diario, y
        // sumarlos de nuevo acá los duplicaría).
        const cardioEquivalenteHoy = Array.isArray(rutina?.cardio)
          ? rutina.cardio.reduce((acc, c, i) => {
              const reg = cardioRegistrosHoy[i];
              if (reg?.completado && !reg.via_pasos) return acc + estimarPasosEquivalentes(reg.duracion_real ?? c.duracionMin);
              return acc;
            }, 0)
          : 0;
        return (
          <Card style={{ marginBottom: 14, padding: 10, background: "linear-gradient(160deg,#0c1230,#0a0f24)", border: `1px solid ${theme.accentLight}55`, boxShadow: `0 0 22px ${theme.accent}20, inset 0 1px 0 rgba(255,255,255,0.04)`, position:"relative", overflow:"hidden" }}>
            <div style={{ display:"flex", alignItems:"center", gap:8 }}>
              <div style={{ width:36, height:36, borderRadius:"50%", flexShrink:0, display:"flex", alignItems:"center", justifyContent:"center", overflow:"hidden", background:`radial-gradient(circle, ${theme.accent}33, transparent 70%)`, border:`2px solid ${theme.accentLight}`, boxShadow:`0 0 12px ${theme.accentLight}77, inset 0 0 8px ${theme.accent}44` }}>
                <img src={ICON_PASOS_ROBOT} alt="Pasos" style={{ width:"78%", height:"78%", objectFit:"contain", filter:`drop-shadow(0 0 3px ${theme.accentLight}aa)` }} />
              </div>
              <div style={{ flex:1, minWidth:0 }}>
                <div style={{ fontSize:9, color:theme.accentLight, fontWeight:800, letterSpacing:1, marginBottom:1 }}>PASOS DE HOY</div>
                <div style={{ fontSize:15, fontWeight:800, color:theme.text }}>
                  {actuales.toLocaleString("es-CL")}{meta > 0 ? <span style={{ fontSize:11, color:theme.muted, fontWeight:600 }}> / {meta.toLocaleString("es-CL")}</span> : null}
                </div>
              </div>
            </div>

            {meta > 0 && (
              <div style={{ marginTop:6, height:5, borderRadius:6, background:theme.surface, overflow:"hidden", border:`1px solid ${theme.border}` }}>
                <div style={{ width:`${pct}%`, height:"100%", borderRadius:6, background:`linear-gradient(90deg, ${theme.accent}, ${theme.accentLight})`, boxShadow:`0 0 10px ${theme.accentLight}aa`, transition:"width 0.3s" }} />
              </div>
            )}

            {cardioEquivalenteHoy > 0 && (
              <div style={{ fontSize:10, color:theme.muted, marginTop:6 }}>
                💡 Cardio de hoy ≈ <span style={{ color:theme.accentLight, fontWeight:700 }}>{cardioEquivalenteHoy.toLocaleString("es-CL")} pasos</span> extra (estimado)
              </div>
            )}

            <div style={{ display:"flex", gap:8, marginTop:6 }}>
              <input type="number" value={pasosHoy} onChange={e => setPasosHoy(e.target.value)} placeholder="Pasos que llevas hoy"
                style={{ flex:1, background:theme.surface, border:`1px solid ${theme.border}`, borderRadius:8, padding:"6px 11px", color:theme.text, fontSize:13, outline:"none" }} />
              <button onClick={guardarPasosHome} disabled={guardandoPasos}
                style={{ background:theme.accent, border:"none", borderRadius:8, padding:"6px 14px", color:"#fff", fontSize:12, fontWeight:700, cursor:"pointer", whiteSpace:"nowrap" }}>
                {guardandoPasos ? "Guardando..." : "Guardar"}
              </button>
            </div>
            {pasosGuardado && <div style={{ fontSize:10, color:theme.success, marginTop:4, fontWeight:700 }}>✓ Pasos guardados</div>}
          </Card>
        );
      })()}

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 8, marginBottom: 14 }}>
        {[
          { id: "rutina", icon: "dumbbell", label: "Entreno" },
          { id: "nutricion", icon: "fork_knife", label: "Dieta" },
          { id: "checkin", icon: "chart", label: "Check-in", fechaCorta: checkin ? (() => { const fecha = new Date(checkin.fecha || new Date()); fecha.setDate(fecha.getDate() + 28); return fecha.toLocaleDateString("es-CL", { day: "numeric", month: "short" }); })() : null },
          { id: "progreso", icon: "calendar_check", label: "Progreso" },
          { id: "pagos_alumno", icon: "card", label: "Pagos" },
          { id: "mensajes", icon: "chat", label: "Mensajes", badge: mensajesNoLeidos },
        ].map(m => (
          <Card key={m.id} onClick={() => onNav(m.id)} style={{ padding: "14px 6px", textAlign: "center", cursor: "pointer", border: `1px solid ${theme.border}`, position: "relative" }}>
            {m.badge > 0 && (
              <span style={{ position: "absolute", top: 6, right: 6, background: theme.danger, color: "#fff", borderRadius: 10, padding: "2px 6px", fontSize: 9, fontWeight: 700 }}>{m.badge}</span>
            )}
            {m.fechaCorta && (
              <span style={{ position: "absolute", top: 6, left: 6, background: `${theme.accent}22`, border: `1px solid ${theme.accent}44`, color: theme.accentLight, borderRadius: 6, padding: "1px 5px", fontSize: 8, fontWeight: 700, whiteSpace: "nowrap" }}>{m.fechaCorta}</span>
            )}
            <div style={{ display: "flex", justifyContent: "center", marginBottom: 6 }}>
              <IconBadge name={m.icon} size={38} />
            </div>
            <div style={{ fontSize: 11, fontWeight: 700, color: theme.text, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis", maxWidth: "100%" }}>{m.label}</div>
          </Card>
        ))}
      </div>

      <NavBar active="alumno_home" onNav={onNav} mensajesNoLeidos={mensajesNoLeidos} />
    </div>
  );
}

// --- Minijuego durante el descanso ---------------------------------------
// Se ofrece uno de 3 minijuegos, elegido al azar cada vez que se abre: Salta
// la Pesa (reflejos), Memoria (memoria visual, 4 etapas encadenadas) y
// Conecta (conectar puntos con el tablero 100% lleno, 6 etapas encadenadas).
// El descanso real sigue corriendo de fondo mientras el minijuego está
// abierto -- este modal es puramente una distracción opcional, no reemplaza
// ni pausa la cuenta regresiva (ver aviso de descanso cumplido más abajo).
function fmtTiempoJuego(ms) { return (ms / 1000).toFixed(1) + "s"; }
function lsGetJuego(k) { try { return localStorage.getItem(k); } catch (e) { return null; } }
function lsSetJuego(k, v) { try { localStorage.setItem(k, v); } catch (e) {} }
function heartsJuego(n, max = 3) { return "❤️".repeat(Math.max(0, n)) + "🖤".repeat(Math.max(0, max - n)); }
function shuffleJuego(arr) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

// ---------- Salta la Pesa: colisión real por superposición + récord guardado ----------
// La posición del corredor/obstáculos se anima con requestAnimationFrame escribiendo
// directamente sobre los nodos del DOM (vía refs) en vez de por estado de React en cada
// frame -- necesario para que se vea fluido a 60fps. El puntaje/récord/mensaje sí son
// estado de React porque cambian poco (una vez por pasada, no por frame).
function JuegoSalta() {
  const boxRef = useRef(null);
  const runnerRef = useRef(null);
  const obsRef = useRef(null);
  const obs2Ref = useRef(null);
  const initRef = useRef(() => {});
  const gRef = useRef({ pctPerSec: 0, avance: 0, gapPct: 0, saltando: false, perdido: false, lastTs: null, rafId: null, record: 0 });
  const [puntos, setPuntos] = useState(0);
  const [record, setRecord] = useState(0);
  const [perdido, setPerdido] = useState(false);
  const [flash, setFlash] = useState("");

  useEffect(() => {
    const BASE_PCT_PER_SEC = 42, CRECIMIENTO = 1.07, TOPE_MULT = 4.2;
    // separación entre los 2 obstáculos, definida en TIEMPO (ms) para que sea justa a
    // cualquier velocidad: o el hueco es chico (un solo salto cubre los 2) o es grande
    // (tiempo de sobra para saltar dos veces) -- se evita la franja intermedia injusta.
    const GAP_JUNTOS_MIN_MS = 120, GAP_JUNTOS_MAX_MS = 200;
    const GAP_SEPARADOS_MIN_MS = 920, GAP_SEPARADOS_MAX_MS = 1420;
    const ICONS2 = ["🧱", "🏃"];
    const g = gRef.current;

    function shrink(rect, factor) {
      const w = rect.width * factor, h = rect.height * factor;
      const cx = rect.left + rect.width / 2, cy = rect.top + rect.height / 2;
      return { left: cx - w / 2, right: cx + w / 2, top: cy - h / 2, bottom: cy + h / 2 };
    }
    function chocaCon(el) {
      const rRect = shrink(runnerRef.current.getBoundingClientRect(), 0.45);
      const oRect = shrink(el.getBoundingClientRect(), 0.5);
      return rRect.left < oRect.right && rRect.right > oRect.left && rRect.top < oRect.bottom && rRect.bottom > oRect.top;
    }
    function nuevaOla() {
      const juntos = Math.random() < 0.5;
      const gapMs = juntos
        ? GAP_JUNTOS_MIN_MS + Math.random() * (GAP_JUNTOS_MAX_MS - GAP_JUNTOS_MIN_MS)
        : GAP_SEPARADOS_MIN_MS + Math.random() * (GAP_SEPARADOS_MAX_MS - GAP_SEPARADOS_MIN_MS);
      g.gapPct = Math.max(4, (gapMs / 1000) * g.pctPerSec);
      if (obs2Ref.current) obs2Ref.current.textContent = ICONS2[Math.floor(Math.random() * ICONS2.length)];
    }
    function loop(ts) {
      if (g.perdido) return;
      if (g.lastTs === null) g.lastTs = ts;
      const dt = ts - g.lastTs; g.lastTs = ts;
      const bw = boxRef.current.clientWidth;
      g.avance += (g.pctPerSec * dt) / 1000;
      const pct1 = 100 - g.avance;
      const pct2 = 100 - g.avance + g.gapPct;
      if (g.avance >= 110 + g.gapPct) {
        g.avance = 0;
        setPuntos(p => {
          const np = p + 1;
          if (np > g.record) {
            g.record = np;
            setRecord(np);
            lsSetJuego("mc_salta_record", String(np));
            setFlash("¡Nuevo récord!");
          }
          return np;
        });
        if (g.pctPerSec < BASE_PCT_PER_SEC * TOPE_MULT) g.pctPerSec = Math.min(BASE_PCT_PER_SEC * TOPE_MULT, g.pctPerSec * CRECIMIENTO);
        nuevaOla();
      }
      if (obsRef.current) obsRef.current.style.left = (pct1 / 100 * bw) + "px";
      if (obs2Ref.current) obs2Ref.current.style.left = (pct2 / 100 * bw) + "px";
      if (chocaCon(obsRef.current) || chocaCon(obs2Ref.current)) {
        g.perdido = true;
        setPerdido(true);
        return;
      }
      g.rafId = requestAnimationFrame(loop);
    }
    function init() {
      g.pctPerSec = BASE_PCT_PER_SEC; g.avance = 0; g.saltando = false; g.perdido = false; g.lastTs = null;
      g.record = parseInt(lsGetJuego("mc_salta_record") || "0", 10);
      setRecord(g.record); setPuntos(0); setFlash(""); setPerdido(false);
      nuevaOla();
      if (runnerRef.current) runnerRef.current.style.bottom = "22px";
      cancelAnimationFrame(g.rafId);
      g.rafId = requestAnimationFrame(loop);
    }
    initRef.current = init;
    init();
    return () => cancelAnimationFrame(g.rafId);
  }, []);

  const saltar = () => {
    const g = gRef.current;
    if (g.saltando || g.perdido) return;
    g.saltando = true;
    if (runnerRef.current) runnerRef.current.style.bottom = "58px";
    setTimeout(() => {
      if (runnerRef.current) runnerRef.current.style.bottom = "22px";
      g.saltando = false;
    }, 620);
  };

  return (
    <div style={{ width: "100%", maxWidth: 280 }}>
      <div style={{ textAlign: "center", color: theme.text, fontSize: 12, fontWeight: 800, marginBottom: 2 }}>SALTA LA PESA</div>
      <div style={{ textAlign: "center", color: "#39FF88", fontSize: 9, fontWeight: 700, marginBottom: 6 }}>Toca para saltar los obstáculos</div>
      <div style={{ display: "flex", justifyContent: "center", gap: 20, marginBottom: 6 }}>
        <div style={{ textAlign: "center" }}>
          <div style={{ color: theme.muted, fontSize: 8, letterSpacing: 0.5 }}>PUNTOS</div>
          <div style={{ color: theme.gold, fontSize: 15, fontWeight: 800 }}>{puntos}</div>
        </div>
        <div style={{ textAlign: "center" }}>
          <div style={{ color: theme.muted, fontSize: 8, letterSpacing: 0.5 }}>RÉCORD</div>
          <div style={{ color: "#39FF88", fontSize: 15, fontWeight: 800 }}>{record}</div>
        </div>
      </div>
      <div style={{ textAlign: "center", fontSize: 10, fontWeight: 800, color: "#39FF88", height: 14, marginBottom: 2 }}>{flash}</div>
      <div ref={boxRef} onClick={() => { if (!perdido) saltar(); }}
        style={{ width: "100%", height: 150, borderRadius: 12, background: theme.surface, border: `1.5px solid ${theme.accentLight}55`, position: "relative", overflow: "hidden", cursor: perdido ? "default" : "pointer" }}>
        <div style={{ position: "absolute", top: 6, left: 0, right: 0, textAlign: "center", fontSize: 8, color: theme.muted }}>Toca para saltar</div>
        <div style={{ position: "absolute", bottom: 24, left: 0, right: 0, height: 1.5, background: theme.border }} />
        <div ref={runnerRef} style={{ position: "absolute", bottom: 22, left: 26, fontSize: 26, transition: "bottom 0.22s ease-out" }}>🏋️</div>
        <div ref={obsRef} style={{ position: "absolute", bottom: 24, fontSize: 22 }}>🧱</div>
        <div ref={obs2Ref} style={{ position: "absolute", bottom: 24, fontSize: 22 }}>🧱</div>
        {perdido && (
          <div onClick={e => { e.stopPropagation(); initRef.current(); }}
            style={{ position: "absolute", inset: 0, background: "rgba(5,5,10,0.85)", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 8 }}>
            <div style={{ color: theme.danger, fontWeight: 800, fontSize: 13 }}>¡Chocaste!</div>
            <div style={{ color: theme.text, fontSize: 11, border: `1px solid ${theme.border}`, borderRadius: 8, padding: "6px 12px" }}>Toca para reintentar</div>
          </div>
        )}
      </div>
      <div style={{ textAlign: "center", color: "#666", fontSize: 8.5, padding: "8px 12px 0" }}>Dos obstáculos por pasada -- a veces puedes saltar los dos juntos, a veces no</div>
    </div>
  );
}

// ---------- Memoria: 4 etapas encadenadas (12/16/20/24 cartas), vidas, tiempo total ----------
const MEMORIA_ICONS_ALL = ["💪", "🏋️", "🏃", "🎯", "🔥", "⏱️", "🥇", "🧘", "🚴", "🤸", "🏊", "🤾"];
const MEMORIA_ETAPAS = [
  { cards: 12, cols: 4, boxH: 170 },
  { cards: 16, cols: 4, boxH: 220 },
  { cards: 20, cols: 5, boxH: 210 },
  { cards: 24, cols: 6, boxH: 200 },
];
const MEMORIA_LIVES_START = 5;

function JuegoMemoria() {
  // El estado "real" del juego vive en este ref (igual que variables mutables) -- las
  // funciones lo leen/escriben de forma síncrona y recién después reflejan lo necesario
  // en estado de React (setXxxD) para volver a pintar. Evita condiciones de carrera con
  // closures viejos de setTimeout, que acá se usan harto (parpadeo de error, avance de etapa).
  const gRef = useRef({
    etapaIdx: 0, cardsData: [], revealed: [], matched: new Set(), lock: false,
    runStartTime: null, running: false, over: false, lives: MEMORIA_LIVES_START, runToken: 0, timerId: null,
  });
  const [etapaIdx, setEtapaIdxD] = useState(0);
  const [cardsView, setCardsView] = useState([]);
  const [lives, setLivesD] = useState(MEMORIA_LIVES_START);
  const [tiempoMs, setTiempoMsD] = useState(0);
  const [mejor, setMejorD] = useState(null);
  const [over, setOverD] = useState(false);
  const [exito, setExitoD] = useState(false);
  const [showWin, setShowWinD] = useState(false);
  const [winMsg, setWinMsg] = useState({ t: "", s: "" });
  const [goMsg, setGoMsg] = useState("");

  function tickTimer() {
    const g = gRef.current;
    if (g.running) setTiempoMsD(Date.now() - g.runStartTime);
  }

  function cargarEtapa() {
    const g = gRef.current;
    const et = MEMORIA_ETAPAS[g.etapaIdx];
    const pairsNeeded = et.cards / 2;
    const icons = MEMORIA_ICONS_ALL.slice(0, pairsNeeded);
    g.cardsData = shuffleJuego([...icons, ...icons]).map(icon => ({ icon, status: "hidden" }));
    g.revealed = []; g.matched = new Set(); g.lock = false;
    setEtapaIdxD(g.etapaIdx);
    setShowWinD(false);
    setCardsView(g.cardsData.slice());
  }

  function iniciarRun() {
    const g = gRef.current;
    g.runToken++;
    g.etapaIdx = 0; g.lives = MEMORIA_LIVES_START; g.runStartTime = null; g.running = false; g.over = false;
    clearInterval(g.timerId);
    setLivesD(g.lives);
    setTiempoMsD(0);
    setOverD(false);
    const best = lsGetJuego("mc_memoria_best");
    setMejorD(best ? parseFloat(best) : null);
    cargarEtapa();
  }

  useEffect(() => { iniciarRun(); return () => clearInterval(gRef.current.timerId); }, []);

  function finDeRun(exitoFlag) {
    const g = gRef.current;
    g.running = false; clearInterval(g.timerId); g.over = true;
    const elapsed = Date.now() - g.runStartTime;
    setTiempoMsD(elapsed);
    setOverD(true);
    setExitoD(exitoFlag);
    if (exitoFlag) {
      const bestRaw = lsGetJuego("mc_memoria_best");
      const best = bestRaw ? parseFloat(bestRaw) : null;
      let msg = `¡Completaste las ${MEMORIA_ETAPAS.length} etapas en ${fmtTiempoJuego(elapsed)}!`;
      if (best === null || elapsed < best) {
        lsSetJuego("mc_memoria_best", String(elapsed));
        setMejorD(elapsed);
        msg += " -- ¡nuevo mejor tiempo!";
      }
      setWinMsg({ t: "¡Recorrido completo!", s: msg });
    } else {
      setGoMsg(`Llegaste a la etapa ${g.etapaIdx + 1} de ${MEMORIA_ETAPAS.length}, en ${fmtTiempoJuego(elapsed)}.`);
    }
  }

  function avanzarEtapa() {
    const g = gRef.current;
    if (g.etapaIdx < MEMORIA_ETAPAS.length - 1) {
      setWinMsg({ t: "¡Etapa superada!", s: "Pasando a la siguiente…" });
      setShowWinD(true);
      const myToken = g.runToken;
      setTimeout(() => {
        if (myToken !== g.runToken) return; // se reinició mientras esperaba -- ignorar
        g.etapaIdx++;
        cargarEtapa();
      }, 900);
    } else {
      finDeRun(true);
    }
  }

  function tap(i) {
    const g = gRef.current;
    if (g.over || g.lock || g.matched.has(i) || g.revealed.includes(i)) return;
    if (!g.running) {
      g.running = true;
      g.runStartTime = Date.now();
      g.timerId = setInterval(tickTimer, 100);
    }
    g.cardsData[i] = { ...g.cardsData[i], status: "front" };
    setCardsView(g.cardsData.slice());
    g.revealed = [...g.revealed, i];
    if (g.revealed.length === 2) {
      g.lock = true;
      const [a, b] = g.revealed;
      if (g.cardsData[a].icon === g.cardsData[b].icon) {
        g.matched.add(a); g.matched.add(b);
        g.cardsData[a] = { ...g.cardsData[a], status: "matched" };
        g.cardsData[b] = { ...g.cardsData[b], status: "matched" };
        setCardsView(g.cardsData.slice());
        g.revealed = []; g.lock = false;
        if (g.matched.size === g.cardsData.length) avanzarEtapa();
      } else {
        g.cardsData[a] = { ...g.cardsData[a], status: "bad" };
        g.cardsData[b] = { ...g.cardsData[b], status: "bad" };
        setCardsView(g.cardsData.slice());
        const myToken = g.runToken;
        setTimeout(() => {
          if (myToken !== g.runToken) return; // se reinició mientras esperaba -- ignorar
          g.lives--;
          setLivesD(g.lives);
          g.cardsData[a] = { ...g.cardsData[a], status: "hidden" };
          g.cardsData[b] = { ...g.cardsData[b], status: "hidden" };
          setCardsView(g.cardsData.slice());
          g.revealed = []; g.lock = false;
          if (g.lives <= 0) finDeRun(false);
        }, 650);
      }
    }
  }

  const et = MEMORIA_ETAPAS[etapaIdx];

  return (
    <div style={{ width: "100%", maxWidth: 280 }}>
      <div style={{ textAlign: "center", color: theme.text, fontSize: 12, fontWeight: 800, marginBottom: 2 }}>MEMORIA · PARES DE GYM</div>
      <div style={{ textAlign: "center", color: "#39FF88", fontSize: 9, fontWeight: 700, marginBottom: 6 }}>Etapa {etapaIdx + 1} · {et.cards} cartas ({et.cards / 2} pares)</div>
      <div style={{ display: "flex", gap: 4, justifyContent: "center", flexWrap: "wrap", marginBottom: 8 }}>
        {MEMORIA_ETAPAS.map((e, i) => (
          <div key={i} style={{
            width: 20, height: 20, borderRadius: 6, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 8.5, fontWeight: 800,
            background: i === etapaIdx ? theme.accentLight : "#1A1A24",
            border: `1px solid ${i < etapaIdx ? theme.success : (i === etapaIdx ? theme.accentLight : theme.border)}`,
            color: i === etapaIdx ? "#fff" : (i < etapaIdx ? "#39FF88" : theme.muted),
          }}>{e.cards}</div>
        ))}
      </div>
      <div style={{ display: "flex", justifyContent: "center", gap: 16, marginBottom: 6, flexWrap: "wrap" }}>
        <div style={{ textAlign: "center" }}>
          <div style={{ color: theme.muted, fontSize: 8, letterSpacing: 0.5 }}>TIEMPO TOTAL</div>
          <div style={{ color: theme.gold, fontSize: 13, fontWeight: 800 }}>{fmtTiempoJuego(tiempoMs)}</div>
        </div>
        <div style={{ textAlign: "center" }}>
          <div style={{ color: theme.muted, fontSize: 8, letterSpacing: 0.5 }}>VIDAS</div>
          <div style={{ color: theme.danger, fontSize: 12, fontWeight: 800 }}>{heartsJuego(lives, MEMORIA_LIVES_START)}</div>
        </div>
        <div style={{ textAlign: "center" }}>
          <div style={{ color: theme.muted, fontSize: 8, letterSpacing: 0.5 }}>MEJOR</div>
          <div style={{ color: "#39FF88", fontSize: 13, fontWeight: 800 }}>{mejor !== null ? fmtTiempoJuego(mejor) : "—"}</div>
        </div>
      </div>
      <div style={{ width: "100%", height: et.boxH, borderRadius: 12, background: theme.surface, border: `1.5px solid ${theme.accentLight}55`, position: "relative", overflow: "hidden", padding: 8, boxSizing: "border-box" }}>
        <div style={{ display: "grid", gridTemplateColumns: `repeat(${et.cols}, 1fr)`, gap: 4, height: "100%" }}>
          {cardsView.map((c, i) => {
            let bg = "linear-gradient(135deg,#4361EE33,#0C239733)", border = `${theme.accentLight}55`;
            if (c.status === "front") { bg = "#1A1A24"; border = "#39FF8855"; }
            else if (c.status === "matched") { bg = `${theme.success}22`; border = theme.success; }
            else if (c.status === "bad") { bg = `${theme.danger}33`; border = theme.danger; }
            return (
              <div key={i} onClick={() => tap(i)}
                style={{ borderRadius: 6, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 15, cursor: c.status === "matched" ? "default" : "pointer", background: bg, border: `1px solid ${border}`, transition: "background 0.15s, border-color 0.15s" }}>
                {(c.status === "front" || c.status === "matched" || c.status === "bad") && <span>{c.icon}</span>}
              </div>
            );
          })}
        </div>
        {showWin && (
          <div style={{ position: "absolute", inset: 0, background: "rgba(5,5,10,0.9)", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 4, zIndex: 5, padding: 10, textAlign: "center" }}>
            <div style={{ color: "#39FF88", fontWeight: 800, fontSize: 13 }}>{winMsg.t}</div>
            <div style={{ color: theme.muted, fontSize: 10 }}>{winMsg.s}</div>
          </div>
        )}
        {over && (
          <div style={{ position: "absolute", inset: 0, background: "rgba(5,5,10,0.94)", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 6, zIndex: 8, padding: 14, textAlign: "center" }}>
            {exito ? (
              <>
                <div style={{ color: "#39FF88", fontWeight: 800, fontSize: 14 }}>{winMsg.t}</div>
                <div style={{ color: "#B0C4DE", fontSize: 11, lineHeight: 1.5 }}>{winMsg.s}</div>
              </>
            ) : (
              <>
                <div style={{ color: theme.danger, fontWeight: 800, fontSize: 14 }}>Sin vidas 💔</div>
                <div style={{ color: "#B0C4DE", fontSize: 11, lineHeight: 1.5 }}>{goMsg}</div>
                <div onClick={iniciarRun} style={{ marginTop: 8, border: `1px solid ${theme.accentLight}`, background: `${theme.accentLight}22`, color: "#8FA6FF", borderRadius: 8, padding: "8px 16px", fontSize: 11, fontWeight: 700, cursor: "pointer" }}>Empezar de nuevo</div>
              </>
            )}
          </div>
        )}
      </div>
      <div style={{ textAlign: "center", marginTop: 10 }}>
        <div onClick={iniciarRun} style={{ display: "inline-block", border: `1px solid ${theme.border}`, borderRadius: 8, padding: "6px 12px", color: "#B0C4DE", fontSize: 10, fontWeight: 700, background: "#1A1A24", cursor: "pointer" }}>Reiniciar todo</div>
      </div>
      <div style={{ textAlign: "center", color: "#666", fontSize: 8.5, padding: "8px 12px 0" }}>Cada par equivocado resta una vida -- al completar una etapa avanzas a la otra</div>
    </div>
  );
}

// ---------- Conecta: 6 etapas encadenadas, tablero 100% lleno desde la 1, vidas, tiempo total ----------
// El tablero nunca deja casilleros libres: se genera UN solo recorrido que cubre TODO el
// grid (regla de Warnsdorff -- en cada paso avanza al vecino libre con menos salidas
// propias, para cubrir el 100% del grid de forma confiable) y se reparte en tramos
// consecutivos, uno por color. Como no queda espacio libre, un camino mal pensado puede
// dejarte sin espacio para llegar al otro punto del mismo color.
const CONECTA_PALETTE = ["#4361EE", "#C9A84C", "#10B981", "#EF4444", "#22D3EE", "#A78BFA", "#F59E0B"];
const CONECTA_BOX = 230;
const CONECTA_LIVES_START = 3;
const CONECTA_ETAPAS = [
  { n: 8, colors: 7, label: "Difícil" },
  { n: 8, colors: 7, label: "Muy difícil" },
  { n: 9, colors: 7, label: "Muy difícil" },
  { n: 9, colors: 7, label: "Súper difícil" },
  { n: 10, colors: 7, label: "Súper difícil" },
  { n: 11, colors: 7, label: "Extrema" },
];
function conectaKey(r, c) { return r + "-" + c; }
function conectaNeighbors(r, c, n) {
  return [[r - 1, c], [r + 1, c], [r, c - 1], [r, c + 1]].filter(([rr, cc]) => rr >= 0 && rr < n && cc >= 0 && cc < n);
}
function conectaWarnsdorffFullPath(n) {
  let best = null;
  for (let attempt = 0; attempt < 90; attempt++) {
    const sr = Math.floor(Math.random() * n), sc = Math.floor(Math.random() * n);
    const visited = new Set([conectaKey(sr, sc)]);
    const path = [{ r: sr, c: sc }];
    let cur = { r: sr, c: sc };
    while (true) {
      const cands = conectaNeighbors(cur.r, cur.c, n).filter(([r, c]) => !visited.has(conectaKey(r, c)));
      if (cands.length === 0) break;
      const scored = cands.map(([r, c]) => ({
        r, c,
        deg: conectaNeighbors(r, c, n).filter(([rr, cc]) => !visited.has(conectaKey(rr, cc))).length,
        rnd: Math.random(),
      }));
      scored.sort((a, b) => (a.deg - b.deg) || (a.rnd - b.rnd));
      cur = { r: scored[0].r, c: scored[0].c };
      visited.add(conectaKey(cur.r, cur.c));
      path.push(cur);
    }
    if (!best || path.length > best.length) best = path;
    if (best.length === n * n) break;
  }
  return best;
}
function conectaSplitIntoColors(path, numColors) {
  const total = path.length;
  const lens = new Array(numColors).fill(Math.floor(total / numColors));
  let rem = total - lens.reduce((a, b) => a + b, 0);
  const order = shuffleJuego([...Array(numColors).keys()]);
  for (let i = 0; i < rem; i++) lens[order[i % numColors]]++;
  // variación suave entre tramos: nunca deja un tramo trivialmente corto (mínimo 3
  // casilleros) para que ningún color sea "obvio"
  const MIN_LEN = 3;
  const passes = Math.max(1, Math.round(numColors / 3));
  for (let p = 0; p < passes; p++) {
    const i = Math.floor(Math.random() * numColors), j = Math.floor(Math.random() * numColors);
    if (i === j) continue;
    const mv = 1 + Math.floor(Math.random() * 2);
    if (lens[i] - mv >= MIN_LEN) { lens[i] -= mv; lens[j] += mv; }
  }
  const segments = [];
  let idx = 0;
  for (const len of lens) { segments.push(path.slice(idx, idx + len)); idx += len; }
  return segments;
}
function conectaGenerateStage(n, numColors) {
  const full = conectaWarnsdorffFullPath(n);
  if (!full || full.length < numColors * 2) return null; // no debería pasar, guard defensivo
  const segments = conectaSplitIntoColors(full, numColors);
  return segments.map((seg, ci) => ({ key: "c" + ci, hex: CONECTA_PALETTE[ci % CONECTA_PALETTE.length], a: seg[0], b: seg[seg.length - 1] }));
}

function JuegoConecta() {
  const wrapRef = useRef(null);
  const gRef = useRef({
    etapaIdx: 0, N: CONECTA_ETAPAS[0].n, CELL: CONECTA_BOX / CONECTA_ETAPAS[0].n, colorDefs: [], paths: {}, occupied: {},
    solved: new Set(), dragging: null, dotCellColor: {}, runStartTime: null, running: false, over: false,
    lives: CONECTA_LIVES_START, runToken: 0, timerId: null,
  });
  const [etapaIdx, setEtapaIdxD] = useState(0);
  const [N, setND] = useState(CONECTA_ETAPAS[0].n);
  const [colorDefs, setColorDefsD] = useState([]);
  const [pathsView, setPathsViewD] = useState({});
  const [solvedView, setSolvedViewD] = useState([]);
  const [lives, setLivesD] = useState(CONECTA_LIVES_START);
  const [tiempoMs, setTiempoMsD] = useState(0);
  const [mejor, setMejorD] = useState(null);
  const [over, setOverD] = useState(false);
  const [exito, setExitoD] = useState(false);
  const [showWin, setShowWinD] = useState(false);
  const [winMsg, setWinMsg] = useState({ t: "", s: "" });
  const [goMsg, setGoMsg] = useState("");

  function tickTimer() {
    const g = gRef.current;
    if (g.running) setTiempoMsD(Date.now() - g.runStartTime);
  }
  function syncView() {
    const g = gRef.current;
    setColorDefsD(g.colorDefs.slice());
    setPathsViewD({ ...g.paths });
    setSolvedViewD(Array.from(g.solved));
  }
  function cargarEtapa() {
    const g = gRef.current;
    const et = CONECTA_ETAPAS[g.etapaIdx];
    g.N = et.n; g.CELL = CONECTA_BOX / g.N;
    g.colorDefs = conectaGenerateStage(g.N, et.colors) || conectaGenerateStage(g.N, Math.max(2, et.colors - 1));
    g.paths = {}; g.occupied = {}; g.solved = new Set(); g.dragging = null; g.dotCellColor = {};
    g.colorDefs.forEach(cl => {
      g.paths[cl.key] = [];
      g.occupied[conectaKey(cl.a.r, cl.a.c)] = cl.key;
      g.occupied[conectaKey(cl.b.r, cl.b.c)] = cl.key;
      g.dotCellColor[conectaKey(cl.a.r, cl.a.c)] = cl.key;
      g.dotCellColor[conectaKey(cl.b.r, cl.b.c)] = cl.key;
    });
    setEtapaIdxD(g.etapaIdx);
    setND(g.N);
    setShowWinD(false);
    syncView();
  }
  function iniciarRun() {
    const g = gRef.current;
    g.runToken++;
    g.etapaIdx = 0; g.lives = CONECTA_LIVES_START; g.runStartTime = null; g.running = false; g.over = false;
    clearInterval(g.timerId);
    setLivesD(g.lives);
    setTiempoMsD(0);
    setOverD(false);
    const best = lsGetJuego("mc_conecta_best");
    setMejorD(best ? parseFloat(best) : null);
    cargarEtapa();
  }
  useEffect(() => { iniciarRun(); return () => clearInterval(gRef.current.timerId); }, []);

  function finDeRun(exitoFlag) {
    const g = gRef.current;
    g.running = false; clearInterval(g.timerId); g.over = true;
    const elapsed = Date.now() - g.runStartTime;
    setTiempoMsD(elapsed);
    setOverD(true);
    setExitoD(exitoFlag);
    if (exitoFlag) {
      const bestRaw = lsGetJuego("mc_conecta_best");
      const best = bestRaw ? parseFloat(bestRaw) : null;
      let msg = `¡Completaste las ${CONECTA_ETAPAS.length} etapas en ${fmtTiempoJuego(elapsed)}!`;
      if (best === null || elapsed < best) {
        lsSetJuego("mc_conecta_best", String(elapsed));
        setMejorD(elapsed);
        msg += " -- ¡nuevo mejor tiempo!";
      }
      setWinMsg({ t: "¡Recorrido completo!", s: msg });
    } else {
      setGoMsg(`Llegaste a la etapa ${g.etapaIdx + 1} de ${CONECTA_ETAPAS.length}, en ${fmtTiempoJuego(elapsed)}.`);
    }
  }
  function avanzarEtapa() {
    const g = gRef.current;
    if (g.etapaIdx < CONECTA_ETAPAS.length - 1) {
      setWinMsg({ t: "¡Etapa superada!", s: "Pasando a la siguiente…" });
      setShowWinD(true);
      const myToken = g.runToken;
      setTimeout(() => {
        if (myToken !== g.runToken) return; // se reinició/reintentó mientras esperaba -- ignorar
        g.etapaIdx++;
        cargarEtapa();
      }, 900);
    } else {
      finDeRun(true);
    }
  }
  function clearColorPath(colorKey) {
    const g = gRef.current;
    g.paths[colorKey].forEach(cell => {
      const k = conectaKey(cell.r, cell.c);
      if (g.dotCellColor[k] !== colorKey) delete g.occupied[k];
    });
    g.paths[colorKey] = [];
    g.solved.delete(colorKey);
  }
  function cellFromClientXY(clientX, clientY) {
    const g = gRef.current;
    const rect = wrapRef.current.getBoundingClientRect();
    const x = clientX - rect.left, y = clientY - rect.top;
    let c = Math.floor(x / g.CELL), r = Math.floor(y / g.CELL);
    r = Math.max(0, Math.min(g.N - 1, r));
    c = Math.max(0, Math.min(g.N - 1, c));
    return { r, c };
  }
  function onDown(e) {
    const g = gRef.current;
    if (g.over) return;
    if (!g.running) { g.running = true; g.runStartTime = Date.now(); g.timerId = setInterval(tickTimer, 100); }
    const { r, c } = cellFromClientXY(e.clientX, e.clientY);
    const k = conectaKey(r, c);
    const dc = g.dotCellColor[k];
    if (!dc) return;
    if (g.solved.has(dc)) return; // ya conectado -- no se puede volver a tomar y deshacer
    clearColorPath(dc);
    g.paths[dc] = [{ r, c }];
    g.occupied[k] = dc;
    g.dragging = dc;
    try { e.currentTarget.setPointerCapture(e.pointerId); } catch (err) {}
    syncView();
  }
  // Aplica un único paso (a una celda ORTOGONALMENTE ADYACENTE a la última del camino actual).
  // Devuelve false si hay que detener el procesamiento (paso inválido, o color recién resuelto).
  function stepConectaCell(r, c) {
    const g = gRef.current;
    const p = g.paths[g.dragging];
    const last = p[p.length - 1];
    if (last.r === r && last.c === c) return true; // ya está ahí, seguir
    if (p.length >= 2 && p[p.length - 2].r === r && p[p.length - 2].c === c) {
      const removed = p.pop();
      const rk = conectaKey(removed.r, removed.c);
      if (g.dotCellColor[rk] !== g.dragging) delete g.occupied[rk];
      return true;
    }
    const dr = Math.abs(r - last.r), dc2 = Math.abs(c - last.c);
    if (dr + dc2 !== 1) return false; // no adyacente (no debería pasar tras interpolar)
    const k = conectaKey(r, c);
    const occ = g.occupied[k];
    if (occ && occ !== g.dragging) return false;
    p.push({ r, c });
    g.occupied[k] = g.dragging;
    const cl = g.colorDefs.find(x => x.key === g.dragging);
    const startCell = p[0];
    const reachedOther = (r === cl.a.r && c === cl.a.c && !(startCell.r === cl.a.r && startCell.c === cl.a.c)) ||
                          (r === cl.b.r && c === cl.b.c && !(startCell.r === cl.b.r && startCell.c === cl.b.c));
    if (reachedOther) {
      g.solved.add(g.dragging);
      g.dragging = null;
      return false; // color resuelto, detener el procesamiento de este movimiento
    }
    return true;
  }
  // Avanza (interpolando celda a celda si hace falta) desde la última celda del camino actual
  // hasta (r, c). Devuelve false si hay que dejar de procesar más eventos de este movimiento
  // (paso inválido, o el color se acaba de resolver).
  function moveConectaTo(r, c) {
    const g = gRef.current;
    const p = g.paths[g.dragging];
    const last = p[p.length - 1];
    if (last.r === r && last.c === c) return true;
    let curR = last.r, curC = last.c;
    let guard = 0;
    while ((curR !== r || curC !== c) && guard < 400) {
      guard++;
      const remR = r - curR, remC = c - curC;
      if (Math.abs(remR) >= Math.abs(remC) && remR !== 0) curR += remR > 0 ? 1 : -1;
      else if (remC !== 0) curC += remC > 0 ? 1 : -1;
      if (!stepConectaCell(curR, curC)) return false;
    }
    return true;
  }
  function onMove(e) {
    const g = gRef.current;
    if (!g.dragging || g.over) return;
    // En touch rápido el navegador puede "coalescer" varios eventos táctiles reales en un solo
    // pointermove. getCoalescedEvents() recupera esas muestras intermedias reales (la trayectoria
    // que el dedo realmente recorrió) para no perder celdas del trazo; si no está disponible,
    // moveConectaTo interpola geométricamente como respaldo. Esto es lo que permite marcar fluido,
    // sin que se "trabe" o rechace el trazo al mover el dedo rápido.
    const events = (typeof e.getCoalescedEvents === "function" && e.getCoalescedEvents().length)
      ? e.getCoalescedEvents() : [e];
    for (const ev of events) {
      if (!g.dragging) break; // el color ya se resolvió con un evento anterior de este mismo lote
      const { r, c } = cellFromClientXY(ev.clientX, ev.clientY);
      if (!moveConectaTo(r, c)) break;
    }
    if (!g.dragging && g.solved.size === g.colorDefs.length) { syncView(); avanzarEtapa(); return; }
    syncView();
  }
  function onUp() {
    const g = gRef.current;
    if (!g.dragging) return;
    const colorKey = g.dragging;
    const avanzo = g.paths[colorKey].length >= 2; // se despegó del punto de partida sin llegar al otro
    g.dragging = null;
    if (g.over) return;
    clearColorPath(colorKey); // suelta sin terminar = se borra ese camino, hay que reintentarlo
    if (avanzo) {
      g.lives--;
      setLivesD(g.lives);
      if (g.lives <= 0) { finDeRun(false); syncView(); return; }
    }
    syncView();
  }
  function reintentarEtapa() {
    const g = gRef.current;
    if (g.over) return;
    g.runToken++; // invalida cualquier transición de etapa pendiente
    g.lives--;
    setLivesD(g.lives);
    if (g.lives <= 0) { finDeRun(false); return; }
    cargarEtapa();
  }

  const et = CONECTA_ETAPAS[etapaIdx];
  const CELL = CONECTA_BOX / N;
  const PIPE = CELL * 0.46, DOT = CELL * 0.58;

  return (
    <div style={{ width: "100%", maxWidth: 280 }}>
      <div style={{ textAlign: "center", color: theme.text, fontSize: 12, fontWeight: 800, marginBottom: 2 }}>CONECTA · UNE LOS PARES</div>
      <div style={{ textAlign: "center", color: "#39FF88", fontSize: 9, fontWeight: 700, marginBottom: 6 }}>Etapa {etapaIdx + 1} de {CONECTA_ETAPAS.length} · {et.label} ({N}×{N}, {colorDefs.length} pares)</div>
      <div style={{ display: "flex", gap: 4, justifyContent: "center", flexWrap: "wrap", marginBottom: 8 }}>
        {CONECTA_ETAPAS.map((e, i) => (
          <div key={i} style={{
            width: 20, height: 20, borderRadius: 6, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 8.5, fontWeight: 800,
            background: i === etapaIdx ? theme.accentLight : "#1A1A24",
            border: `1px solid ${i < etapaIdx ? theme.success : (i === etapaIdx ? theme.accentLight : theme.border)}`,
            color: i === etapaIdx ? "#fff" : (i < etapaIdx ? "#39FF88" : theme.muted),
          }}>{i + 1}</div>
        ))}
      </div>
      <div style={{ display: "flex", justifyContent: "center", gap: 16, marginBottom: 6, flexWrap: "wrap" }}>
        <div style={{ textAlign: "center" }}>
          <div style={{ color: theme.muted, fontSize: 8, letterSpacing: 0.5 }}>TIEMPO TOTAL</div>
          <div style={{ color: theme.gold, fontSize: 13, fontWeight: 800 }}>{fmtTiempoJuego(tiempoMs)}</div>
        </div>
        <div style={{ textAlign: "center" }}>
          <div style={{ color: theme.muted, fontSize: 8, letterSpacing: 0.5 }}>VIDAS</div>
          <div style={{ color: theme.danger, fontSize: 12, fontWeight: 800 }}>{heartsJuego(lives, CONECTA_LIVES_START)}</div>
        </div>
        <div style={{ textAlign: "center" }}>
          <div style={{ color: theme.muted, fontSize: 8, letterSpacing: 0.5 }}>MEJOR</div>
          <div style={{ color: "#39FF88", fontSize: 13, fontWeight: 800 }}>{mejor !== null ? fmtTiempoJuego(mejor) : "—"}</div>
        </div>
      </div>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "center", padding: 8, borderRadius: 12, background: theme.surface, border: `1.5px solid ${theme.accentLight}55`, position: "relative" }}>
        <div ref={wrapRef}
          onPointerDown={onDown} onPointerMove={onMove} onPointerUp={onUp} onPointerCancel={onUp}
          style={{ position: "relative", width: CONECTA_BOX, height: CONECTA_BOX, touchAction: "none" }}>
          {Array.from({ length: N }).map((_, r) => Array.from({ length: N }).map((_, c) => (
            <div key={`bg-${r}-${c}`} style={{ position: "absolute", left: c * CELL, top: r * CELL, width: CELL, height: CELL, border: "1px solid #21212c", boxSizing: "border-box" }} />
          )))}
          {colorDefs.map(cl => {
            const p = pathsView[cl.key] || [];
            const segs = [];
            for (let i = 0; i < p.length - 1; i++) {
              const c1 = p[i], c2 = p[i + 1];
              if (c1.r === c2.r) {
                segs.push({ top: c1.r * CELL + (CELL - PIPE) / 2, left: Math.min(c1.c, c2.c) * CELL + CELL / 2, width: CELL, height: PIPE });
              } else {
                segs.push({ left: c1.c * CELL + (CELL - PIPE) / 2, top: Math.min(c1.r, c2.r) * CELL + CELL / 2, height: CELL, width: PIPE });
              }
            }
            const isSolved = solvedView.includes(cl.key);
            return (
              <Fragment key={cl.key}>
                {segs.map((s, i) => (
                  <div key={`s-${i}`} style={{ position: "absolute", zIndex: 2, background: cl.hex, top: s.top, left: s.left, width: s.width, height: s.height }} />
                ))}
                {p.map((cell, i) => (
                  <div key={`j-${i}`} style={{ position: "absolute", zIndex: 2, borderRadius: "50%", background: cl.hex, left: cell.c * CELL + (CELL - PIPE) / 2, top: cell.r * CELL + (CELL - PIPE) / 2, width: PIPE, height: PIPE }} />
                ))}
                {[cl.a, cl.b].map((d, i) => (
                  <div key={`d-${i}`} style={{
                    position: "absolute", zIndex: 3, borderRadius: "50%", background: cl.hex, boxShadow: "0 0 6px currentColor",
                    left: d.c * CELL + (CELL - DOT) / 2, top: d.r * CELL + (CELL - DOT) / 2, width: DOT, height: DOT,
                    display: "flex", alignItems: "center", justifyContent: "center", fontSize: Math.max(7, DOT * 0.4), fontWeight: 900, color: "#0A0A0F",
                  }}>{isSolved ? "✓" : ""}</div>
                ))}
              </Fragment>
            );
          })}
        </div>
        {showWin && (
          <div style={{ position: "absolute", inset: 0, background: "rgba(5,5,10,0.9)", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 4, zIndex: 5, padding: 10, textAlign: "center" }}>
            <div style={{ color: "#39FF88", fontWeight: 800, fontSize: 13 }}>{winMsg.t}</div>
            <div style={{ color: theme.muted, fontSize: 10 }}>{winMsg.s}</div>
          </div>
        )}
        {over && (
          <div style={{ position: "absolute", inset: 0, background: "rgba(5,5,10,0.94)", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 6, zIndex: 8, padding: 14, textAlign: "center" }}>
            {exito ? (
              <>
                <div style={{ color: "#39FF88", fontWeight: 800, fontSize: 14 }}>{winMsg.t}</div>
                <div style={{ color: "#B0C4DE", fontSize: 11, lineHeight: 1.5 }}>{winMsg.s}</div>
              </>
            ) : (
              <>
                <div style={{ color: theme.danger, fontWeight: 800, fontSize: 14 }}>Sin vidas 💔</div>
                <div style={{ color: "#B0C4DE", fontSize: 11, lineHeight: 1.5 }}>{goMsg}</div>
                <div onClick={iniciarRun} style={{ marginTop: 8, border: `1px solid ${theme.accentLight}`, background: `${theme.accentLight}22`, color: "#8FA6FF", borderRadius: 8, padding: "8px 16px", fontSize: 11, fontWeight: 700, cursor: "pointer" }}>Empezar de nuevo</div>
              </>
            )}
          </div>
        )}
      </div>
      <div style={{ textAlign: "center", marginTop: 10 }}>
        <div onClick={reintentarEtapa} style={{ display: "inline-block", border: `1px solid ${theme.border}`, borderRadius: 8, padding: "6px 12px", color: "#B0C4DE", fontSize: 10, fontWeight: 700, background: "#1A1A24", cursor: "pointer" }}>Me trabé, reintentar (-1 vida)</div>
      </div>
      <div style={{ textAlign: "center", color: "#666", fontSize: 8.5, padding: "8px 12px 0" }}>Tablero 100% lleno -- si sueltas un color a medio camino sin llegar al otro punto, pierdes una vida</div>
    </div>
  );
}

function MinijuegoModal({ tipo, onCerrar }) {
  return (
    <div onClick={onCerrar}
      style={{ position:"absolute", inset:0, background:"rgba(5,5,10,0.94)", zIndex:2600, display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", padding:20, cursor:"pointer" }}>
      <div onClick={e => e.stopPropagation()} style={{ width:"100%", maxWidth:320, cursor:"default", display:"flex", flexDirection:"column", alignItems:"center" }}>
        {tipo === "salta" && <JuegoSalta />}
        {tipo === "memoria" && <JuegoMemoria />}
        {tipo === "conecta" && <JuegoConecta />}
        <button onClick={onCerrar}
          style={{ marginTop:16, background:"transparent", border:`1px solid ${theme.border}`, borderRadius:10, padding:"10px 18px", color:theme.text, fontSize:12, fontWeight:700, cursor:"pointer" }}>
          Cerrar minijuego ✕
        </button>
      </div>
    </div>
  );
}

function RutinaScreen({ onNav }) {
  const [rutinas, setRutinas] = useState([]);
  const [rutinaActiva, setRutinaActiva] = useState(null);
  const [loading, setLoading] = useState(true);
  const [registros, setRegistros] = useState({});
  const [completado, setCompletado] = useState(false);
  const [verCalentamiento, setVerCalentamiento] = useState(false);
  const [verVueltaCalma, setVerVueltaCalma] = useState(false);
  const [mapaImagenes, setMapaImagenes] = useState({});
  const [mapaImagenesGrupoMuscular, setMapaImagenesGrupoMuscular] = useState({});
  const [userId, setUserId] = useState(null);
  const [cardioRegistros, setCardioRegistros] = useState({});
  const [verInfoRutina, setVerInfoRutina] = useState(false);
  const [minijuegoAbierto, setMinijuegoAbierto] = useState(false);
  const [tipoMinijuego, setTipoMinijuego] = useState(null); // se sortea al abrir, no en cada render
  const [edadAlumno, setEdadAlumno] = useState(null);
  const hoyStrRutina = fechaOperativaStr();

  useEffect(() => {
    if (!verInfoRutina) return;
    window.history.pushState({ infoRutina: true }, "");
    const onPop = () => setVerInfoRutina(false);
    window.addEventListener("popstate", onPop);
    return () => window.removeEventListener("popstate", onPop);
  }, [verInfoRutina]);
  const cerrarInfoRutina = () => window.history.back();

  useEffect(() => {
    if (!minijuegoAbierto) return;
    window.history.pushState({ minijuego: true }, "");
    const onPop = () => setMinijuegoAbierto(false);
    window.addEventListener("popstate", onPop);
    return () => window.removeEventListener("popstate", onPop);
  }, [minijuegoAbierto]);
  const cerrarMinijuego = () => window.history.back();

  useEffect(() => { cargarMapaImagenesEjercicios().then(setMapaImagenes); }, []);
  useEffect(() => { cargarMapaImagenesGrupoMuscular().then(setMapaImagenesGrupoMuscular); }, []);

  useEffect(() => {
    if (!userId) return;
    supabase.from("cardio_registros").select("cardio_index, duracion_real, distancia_real, completado, via_pasos").eq("usuario_id", userId).eq("fecha", hoyStrRutina)
      .then(({ data }) => {
        const mapa = {};
        (data || []).forEach(r => { mapa[r.cardio_index] = { duracion_real: r.duracion_real, distancia_real: r.distancia_real, completado: r.completado, via_pasos: r.via_pasos }; });
        setCardioRegistros(mapa);
      });
  }, [userId, hoyStrRutina]);

  // modo: "cardio" (hizo el cardio en sí), "pasos" (lo reemplazó por los pasos
  // equivalentes) o null (desmarcar). Son mutuamente excluyentes -- no tiene
  // sentido marcar ambos para la misma sesión de cardio del día.
  const marcarCardio = async (idx, item, modo) => {
    if (!userId) return;
    const yaEstaEnEseModo = modo && cardioRegistros[idx]?.completado && (cardioRegistros[idx]?.via_pasos ? "pasos" : "cardio") === modo;
    const actual = {
      ...(cardioRegistros[idx] || {}),
      completado: !yaEstaEnEseModo && !!modo,
      via_pasos: !yaEstaEnEseModo && modo === "pasos",
      duracion_real: cardioRegistros[idx]?.duracion_real ?? item.duracionMin,
    };
    setCardioRegistros(prev => ({ ...prev, [idx]: actual }));
    const { error } = await supabase.from("cardio_registros").upsert({
      usuario_id: userId, fecha: hoyStrRutina, cardio_index: idx, tipo: item.tipo,
      duracion_real: actual.duracion_real != null && actual.duracion_real !== "" ? parseFloat(actual.duracion_real) : null,
      distancia_real: actual.distancia_real != null && actual.distancia_real !== "" ? parseFloat(actual.distancia_real) : null,
      completado: !!actual.completado,
      via_pasos: !!actual.via_pasos,
    }, { onConflict: "usuario_id,fecha,cardio_index" });
    if (error) alert("No se pudo guardar el cardio: " + error.message);
  };
  const [bloqueado, setBloqueado] = useState(false);
  const [seriesHechas, setSeriesHechas] = useState({});
  const [diarioPaso, setDiarioPaso] = useState("form");
  const [intensidad, setIntensidad] = useState(7);
  const [horasSueno, setHorasSueno] = useState("8");
  const [calidadSueno, setCalidadSueno] = useState(7);
  const [guardandoDiario, setGuardandoDiario] = useState(false);

  // Flujo "Iniciar serie / Fin de serie" con cronómetro de descanso en el
  // botón fijo inferior. estadoSerie: 'idle' (apuntando a la próxima serie
  // pendiente) -> 'activa' (serie en curso, fila resaltada en azul) ->
  // 'descansando' (cuenta regresiva usando el descanso_desde/descanso_hasta
  // del ejercicio, en el mismo botón) -> vuelve a 'idle' al tocar el botón
  // en cualquier momento del descanso.
  const [estadoSerie, setEstadoSerie] = useState("idle");
  const [serieObjetivo, setSerieObjetivo] = useState(null); // { ejId, idx }
  const [segDescanso, setSegDescanso] = useState(0);
  const restIntervalRef = useRef(null);
  const limpiarIntervaloDescanso = () => {
    if (restIntervalRef.current) { clearInterval(restIntervalRef.current); restIntervalRef.current = null; }
  };
  useEffect(() => () => limpiarIntervaloDescanso(), []);

  useEffect(() => {
    setCompletado(false);
    setRegistros({});
    limpiarIntervaloDescanso();
    setEstadoSerie("idle");
    setSerieObjetivo(null);
    setSegDescanso(0);
  }, [rutinaActiva]);

  const [ultimasCargas, setUltimasCargas] = useState({});

  // Precarga el KG y las REPS de cada serie de aproximación con el valor
  // sugerido (reps objetivo del coach, kg calculado según el % y el último
  // peso efectivo registrado) para que el alumno no tenga que escribirlos
  // de cero -- aparecen ya cargados y puede editarlos si quiere, igual que
  // cualquier otro campo. _autoKg/_autoReps distinguen un valor autocompletado
  // de uno que el alumno ya tocó a mano, para no pisarlo cuando este efecto
  // se vuelve a correr (por ejemplo cuando termina de cargar el historial de
  // cargas, que llega después del primer render).
  useEffect(() => {
    if (!rutinaActiva) return;
    const ejerciciosRutina = rutinaActiva.ejercicios || [];
    setRegistros(prev => {
      let cambio = false;
      const next = { ...prev };
      ejerciciosRutina.forEach(ej => {
        const series = Array.isArray(ej.series) ? ej.series : [];
        series.forEach((s, idx) => {
          if ((s.tipo || "efectiva") !== "aproximacion") return;
          const key = `${ej.id}-${idx}`;
          const actual = next[key] || {};
          const refEfectiva = ultimasCargas[`${ej.id}-1`];
          const kgSugerido = (refEfectiva?.kg && s.pctDesde) ? redondearKg((parseFloat(s.pctDesde) / 100) * refEfectiva.kg) : null;
          const kgEditadoAMano = actual.kg && !actual._autoKg;
          const repsEditadoAMano = actual.reps && !actual._autoReps;
          const nuevoKg = kgEditadoAMano ? actual.kg : (kgSugerido != null ? String(kgSugerido) : (actual.kg || ""));
          const nuevoReps = repsEditadoAMano ? actual.reps : (s.reps != null ? String(s.reps) : (actual.reps || ""));
          if (nuevoKg !== actual.kg || nuevoReps !== actual.reps || (!kgEditadoAMano && !actual._autoKg && nuevoKg) || (!repsEditadoAMano && !actual._autoReps && nuevoReps)) {
            next[key] = { ...actual, kg: nuevoKg, reps: nuevoReps, _autoKg: !kgEditadoAMano, _autoReps: !repsEditadoAMano };
            cambio = true;
          }
        });
      });
      return cambio ? next : prev;
    });
  }, [rutinaActiva, ultimasCargas]);

  const cargarUltimasCargas = async (userId) => {
    const { data: historico } = await supabase
      .from("registros_entreno")
      .select("ejercicio_id, serie, kg, reps, fecha, creado_en")
      .eq("usuario_id", userId)
      .order("creado_en", { ascending: false });
    if (historico) {
      const ultimas = {};
      historico.forEach(r => {
        const key = `${r.ejercicio_id}-${r.serie}`;
        if (!(key in ultimas) && r.kg) ultimas[key] = { kg: r.kg, reps: r.reps, fecha: r.fecha };
      });
      setUltimasCargas(ultimas);
    }
  };

  useEffect(() => {
    const cargar = async () => {
      const { data: { user } } = await supabase.auth.getUser();
      if (user) {
        setUserId(user.id);
        const { data: usuarioEdad } = await supabase.from("usuarios").select("edad").eq("id", user.id).single();
        if (usuarioEdad?.edad) setEdadAlumno(usuarioEdad.edad);
        const { data: pagoData } = await supabase.from("pagos").select("estado").eq("usuario_id", user.id).order("created_at", { ascending: false }).limit(1);
        if (pagoData && pagoData.length > 0 && pagoData[0].estado === "bloqueado") {
          setBloqueado(true);
          setLoading(false);
          return;
        }
        const { data } = await supabase
          .from("rutinas")
          .select("*, ejercicios(*)")
          .eq("usuario_id", user.id)
          .order("created_at", { ascending: false });
        if (data && data.length > 0) {
          setRutinas(data);
          const nombreHoy = nombreDiaOperativo();
          const rutinaHoy = data.find(r => r.dia === nombreHoy);
          setRutinaActiva(rutinaHoy || data[0]);
        }

        await cargarUltimasCargas(user.id);
      }
      setLoading(false);
    };
    cargar();
  }, []);

  const setReg = (ejId, sIdx, campo, val) => {
    const key = `${ejId}-${sIdx}`;
    setRegistros(prev => {
      const patch = { [campo]: val };
      // El alumno tocó el campo a mano -- deja de considerarse autocompletado,
      // así el efecto de precarga de aproximación ya no lo vuelve a pisar.
      if (campo === "kg") patch._autoKg = false;
      if (campo === "reps") patch._autoReps = false;
      return { ...prev, [key]: { ...prev[key], ...patch } };
    });
  };

  const getRirColor = (rir) => rir === 0 ? "#EF4444" : rir === 1 ? "#F59E0B" : "#39FF88";
  const getRirLabel = (rir) => rir === 0 ? "Fallo" : rir === 1 ? "RIR 1" : "RIR 2";

  // Al cumplirse el descanso MÁXIMO, se pasa solo (sin necesidad de tocar el
  // botón) de "descansando" a "idle" mostrando ya el botón azul de "Iniciar
  // serie" -- el alumno igual puede tocar el botón en cualquier momento
  // antes de eso para cortar el descanso e iniciar la próxima serie ya
  // (ver rama "descansando" de handleBotonSerie más abajo).
  // Este hook va ANTES de los "return" condicionales de abajo (loading /
  // bloqueado / sin rutina) para no romper el orden de hooks entre renders
  // -- por eso calcula el descanso máximo de forma autónoma en vez de
  // reusar "ejercicios" / "descansoParaSerie", que se definen más abajo.
  useEffect(() => {
    if (estadoSerie !== "descansando") return;
    const ej = rutinaActiva?.ejercicios?.find(e => e.id === serieObjetivo?.ejId);
    const serie = ej?.series?.[serieObjetivo?.idx];
    const tipo = serie?.tipo || "efectiva";
    const max = tipo === "aproximacion" ? 90 : (ej?.descanso_hasta || Math.max(ej?.descanso_desde || 60, 90));
    if (segDescanso >= max) {
      limpiarIntervaloDescanso();
      setEstadoSerie("idle");
      setSerieObjetivo(null);
      setSegDescanso(0);
    }
  }, [estadoSerie, segDescanso, serieObjetivo, rutinaActiva]);

  // Si el descanso se cumple mientras el minijuego está abierto (tapando la pantalla),
  // el alumno no ve el botón pasar a "Iniciar serie" -- así que además vibra y se
  // muestra un aviso encima del minijuego (ver render más abajo). Este efecto solo
  // dispara la vibración (un evento puntual); el aviso en pantalla se calcula
  // directamente en el render a partir de minijuegoAbierto + estadoSerie.
  useEffect(() => {
    if (minijuegoAbierto && estadoSerie === "idle") {
      try { navigator.vibrate?.([200, 100, 200, 100, 200]); } catch (e) {}
    }
  }, [estadoSerie, minijuegoAbierto]);

  if (loading) return (
    <div style={{ padding: "20px 16px 90px", height: "100%", boxSizing: "border-box", display: "flex", alignItems: "center", justifyContent: "center" }}>
      <div style={{ color: theme.muted }}>Cargando rutina...</div>
    </div>
  );

  if (bloqueado) return (
    <div style={{ padding: "20px 16px 90px", overflowY: "auto", height: "100%", boxSizing: "border-box" }}>
      <span onClick={() => onNav("alumno_home")} style={{ fontSize: 16, cursor: "pointer", color: theme.text }}>← Inicio</span>
      <Card style={{ textAlign: "center", padding: 40, marginTop: 20, background: `${theme.danger}12`, border: `1px solid ${theme.danger}44` }}>
        <div style={{ fontSize: 32, marginBottom: 12 }}>🔒</div>
        <div style={{ fontSize: 16, fontWeight: 800, color: theme.danger, marginBottom: 8 }}>Acceso bloqueado</div>
        <div style={{ fontSize: 13, color: theme.muted, marginBottom: 16 }}>Tu acceso a la rutina está bloqueado por pago pendiente. Regulariza tu situación para volver a entrenar.</div>
        <Btn onClick={() => onNav("pagos_alumno")}>Ver mis pagos</Btn>
      </Card>
      <NavBar active="rutina" onNav={onNav} />
    </div>
  );

  if (!rutinaActiva) return (
    <div style={{ padding: "20px 16px 90px", height: "100%", boxSizing: "border-box" }}>
      <div style={{ marginBottom: 20 }}>
        <span onClick={() => onNav("alumno_home")} style={{ fontSize: 16, cursor: "pointer", color: theme.text, marginBottom: 6, display: "inline-block" }}>← Inicio</span>
        <div style={{ color: theme.muted, fontSize: 12, marginTop: 4 }}>ENTRENAMIENTO</div>
        <div style={{ fontSize: 22, fontWeight: 800, color: theme.text }}>Sin rutina 💪</div>
      </div>
      <Card style={{ textAlign: "center", padding: 40 }}>
        <div style={{ fontSize: 32, marginBottom: 12 }}>📋</div>
        <div style={{ fontSize: 15, fontWeight: 700, color: theme.text, marginBottom: 8 }}>Tu coach aún no ha asignado una rutina</div>
        <div style={{ fontSize: 13, color: theme.muted }}>Cuando tu coach cree tu plan de entrenamiento aparecerá aquí</div>
      </Card>
      <NavBar active="rutina" onNav={onNav} />
    </div>
  );

  const ejercicios = rutinaActiva.ejercicios?.sort((a, b) => a.orden - b.orden) || [];

  // Bloques: los ejercicios se agrupan en "superserie/biserie" cuando
  // comparten la misma letra de grupo (grupo_superserie) Y están uno debajo
  // del otro en la rutina. Uno sin grupo, o cuyo grupo no es consecutivo con
  // el anterior, queda como bloque individual (comportamiento de siempre).
  const bloques = [];
  for (let i = 0; i < ejercicios.length; i++) {
    const grupo = ejercicios[i].grupo_superserie || null;
    if (grupo && bloques.length > 0 && bloques[bloques.length - 1].grupo === grupo) {
      bloques[bloques.length - 1].ejs.push(ejercicios[i]);
    } else {
      bloques.push({ grupo, ejs: [ejercicios[i]] });
    }
  }

  // Próxima serie pendiente (primera, recorriendo los bloques en orden). Dentro
  // de un bloque agrupado (superserie/biserie) las series se intercalan por
  // ronda -- ronda r toma la serie[r] de cada ejercicio del grupo que aún la
  // tenga -- así el alumno hace un ejercicio tras otro sin descanso, y recién
  // descansa al cerrar la ronda completa (marcado con finRonda). Un bloque de
  // un solo ejercicio simplemente recorre sus series en orden, cada una
  // cerrando su propia ronda (así se preserva el descanso de siempre entre
  // series efectivas de un mismo ejercicio).
  const todasLasSeries = bloques.flatMap((bloque, bloqueIdx) => {
    if (!bloque.grupo || bloque.ejs.length < 2) {
      const ej = bloque.ejs[0];
      return (Array.isArray(ej.series) ? ej.series : []).map((s, idx) => ({ ej, s, idx, key: `${ej.id}-${idx}`, finRonda: true, bloqueIdx }));
    }
    const maxSeries = Math.max(...bloque.ejs.map(e => (Array.isArray(e.series) ? e.series.length : 0)));
    const items = [];
    for (let r = 0; r < maxSeries; r++) {
      const ejsConSerie = bloque.ejs.filter(e => Array.isArray(e.series) && e.series[r]);
      ejsConSerie.forEach((ej, pos) => {
        items.push({ ej, s: ej.series[r], idx: r, key: `${ej.id}-${r}`, finRonda: pos === ejsConSerie.length - 1, bloqueIdx });
      });
    }
    return items;
  });
  const siguientePendiente = todasLasSeries.find(x => !seriesHechas[x.key]);

  // Descanso a aplicar según el TIPO de la serie recién terminada: las de
  // aproximación siempre descansan 60-90s fijo (no hace falta tanto como en
  // una serie efectiva pesada); las efectivas usan el descanso_desde/
  // descanso_hasta que el coach definió para el ejercicio.
  const descansoParaSerie = (objetivo) => {
    if (!objetivo) return { min: 60, max: 90 };
    const ej = ejercicios.find(e => e.id === objetivo.ejId);
    const serie = ej?.series?.[objetivo.idx];
    const tipo = serie?.tipo || "efectiva";
    if (tipo === "aproximacion") return { min: 60, max: 90 };
    const min = ej?.descanso_desde || 60;
    const max = ej?.descanso_hasta || Math.max(min, 90);
    return { min, max };
  };
  const { min: descansoMinActivo, max: descansoMaxActivo } = descansoParaSerie(serieObjetivo);

  const handleBotonSerie = () => {
    if (estadoSerie === "idle") {
      if (!siguientePendiente) return;
      setSerieObjetivo({ ejId: siguientePendiente.ej.id, idx: siguientePendiente.idx });
      setEstadoSerie("activa");
    } else if (estadoSerie === "activa") {
      const key = serieObjetivo ? `${serieObjetivo.ejId}-${serieObjetivo.idx}` : null;
      const hechasActualizadas = key ? { ...seriesHechas, [key]: true } : seriesHechas;
      if (key) setSeriesHechas(hechasActualizadas);

      // El descanso solo tiene sentido si lo que sigue pertenece al MISMO
      // bloque que se acaba de terminar (mismo ejercicio suelto, o misma
      // superserie/biserie) Y esa serie cerraba su ronda (finRonda): para un
      // ejercicio suelto eso es cada serie -- así se preserva el descanso de
      // siempre entre series de un mismo ejercicio. Para una superserie/
      // biserie, pasar de un ejercicio al otro DENTRO de la misma ronda no
      // tiene finRonda, así que no se fuerza descanso -- recién se descansa
      // al cerrar la ronda completa. Si lo que sigue es de otro bloque, o ya
      // no queda nada pendiente, se vuelve directo a "idle" apuntando a lo
      // que sigue.
      const objetivoActual = key ? todasLasSeries.find(x => x.key === key) : null;
      const siguiente = todasLasSeries.find(x => !hechasActualizadas[x.key]);
      const debeDescansar = !!(siguiente && objetivoActual && siguiente.bloqueIdx === objetivoActual.bloqueIdx && objetivoActual.finRonda);

      if (debeDescansar) {
        const { max } = descansoParaSerie(serieObjetivo);
        setSegDescanso(0);
        setEstadoSerie("descansando");
        limpiarIntervaloDescanso();
        restIntervalRef.current = setInterval(() => {
          setSegDescanso(prev => {
            const next = prev + 1;
            if (next >= max) limpiarIntervaloDescanso();
            return next;
          });
        }, 1000);
      } else {
        limpiarIntervaloDescanso();
        setEstadoSerie("idle");
        setSerieObjetivo(null);
        setSegDescanso(0);
      }
    } else if (estadoSerie === "descansando") {
      // Tocar el botón en cualquier momento del descanso (esté en naranja o
      // ya en verde) cancela la cuenta regresiva y vuelve a apuntar a la
      // próxima serie pendiente.
      limpiarIntervaloDescanso();
      setEstadoSerie("idle");
      setSerieObjetivo(null);
      setSegDescanso(0);
    }
  };

  let textoBotonSerie, bgBotonSerie, sombraBotonSerie, bottomLabelSerie, bottomLabelColorSerie;
  let progresoDescansoPct = 0;
  if (estadoSerie === "activa") {
    textoBotonSerie = "⏸ Fin de serie";
    bgBotonSerie = "linear-gradient(135deg, #EF4444, #b91c1c)";
    sombraBotonSerie = "0 0 18px rgba(239,68,68,0.4)";
    bottomLabelSerie = "Serie en curso...";
    bottomLabelColorSerie = theme.muted;
  } else if (estadoSerie === "descansando") {
    // La barra se rellena de verde oscuro a verde flúor de forma continua
    // (sin reinicios ni tandas) a lo largo de todo el descanso, hasta
    // cumplir el descanso máximo, momento en el que pasa sola a "idle" (ver
    // useEffect arriba). El alumno puede tocar el botón en cualquier
    // momento para saltarse el resto del descanso e iniciar antes.
    progresoDescansoPct = Math.min(100, (segDescanso / Math.max(1, descansoMaxActivo)) * 100);
    bgBotonSerie = `linear-gradient(135deg, ${interpolarColor("#0B3D2E", "#39FF88", progresoDescansoPct / 100)}, #052e1c)`;
    sombraBotonSerie = `0 0 18px rgba(57,255,136,${0.15 + 0.25 * (progresoDescansoPct / 100)})`;
    textoBotonSerie = `⏱ Descansando... ${formatearDescanso(segDescanso)}`;
    bottomLabelSerie = `Meta: ${formatearDescanso(descansoMinActivo)}-${formatearDescanso(descansoMaxActivo)} antes de la próxima`;
    bottomLabelColorSerie = theme.muted;
  } else {
    textoBotonSerie = "▶ Iniciar serie";
    bgBotonSerie = `linear-gradient(135deg, ${theme.accentLight}, ${theme.accent})`;
    sombraBotonSerie = `0 0 18px ${theme.accent}66`;
    bottomLabelSerie = siguientePendiente ? `${siguientePendiente.ej.nombre} · ${siguientePendiente.s.reps} reps` : "";
    bottomLabelColorSerie = theme.muted;
  }
  const mostrarBarraSerie = !completado && (estadoSerie !== "idle" || !!siguientePendiente);

  // El botón de terminar entrenamiento no se muestra mientras queden series
  // o cardio pendientes -- antes aparecía siempre, lo que dejaba a la vista
  // al mismo tiempo que la barra de "Iniciar serie", como si el entreno ya
  // pudiera darse por terminado aunque todavía hubiera series sin marcar.
  const cardioPendiente = Array.isArray(rutinaActiva.cardio) && rutinaActiva.cardio.some((c, i) => !cardioRegistros[i]?.completado);
  const faltaParaTerminar = siguientePendiente ? "series" : cardioPendiente ? "cardio" : null;

  return (
    <div style={{ padding: `20px 16px ${mostrarBarraSerie ? 200 : 90}px`, overflowY: "auto", height: "100%", boxSizing: "border-box" }}>
      <div style={{ marginBottom: 16, display:"flex", alignItems:"center", gap:10 }}>
        <button onClick={() => onNav("alumno_home")} aria-label="Volver a Inicio"
          style={{ flexShrink:0, width:34, height:34, borderRadius:"50%", background:theme.surface, border:`1px solid ${theme.border}`, color:theme.text, fontSize:17, fontWeight:800, cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center" }}>←</button>
        <div style={{ flex:1, minWidth:0, textAlign:"center" }}>
          <div style={{ color: theme.muted, fontSize: 12, marginBottom: 2 }}>ENTRENAMIENTO · {rutinaActiva.dia?.toUpperCase() || ""}</div>
          <div style={{ fontSize: 20, fontWeight: 800, color: theme.text, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{rutinaActiva.nombre} 💪</div>
          {rutinaActiva.created_at && <div style={{ fontSize: 11, color: theme.muted, marginTop: 2 }}>Desde: {new Date(rutinaActiva.created_at).toLocaleDateString("es-CL", { day:"2-digit", month:"short", year:"numeric" })}</div>}
        </div>
        <button onClick={() => setVerInfoRutina(true)} aria-label="Info de la rutina"
          style={{ flexShrink:0, width:34, height:34, borderRadius:"50%", background:`${theme.accent}22`, border:`1px solid ${theme.accent}66`, color:theme.accentLight, fontSize:16, fontWeight:800, cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center" }}>ⓘ</button>
      </div>

      {verInfoRutina && (
        <div onClick={cerrarInfoRutina}
          style={{ position:"absolute", inset:0, background:"rgba(0,0,0,0.88)", zIndex:2500, display:"flex", alignItems:"center", justifyContent:"center", padding:24, cursor:"pointer" }}>
          <div onClick={e => e.stopPropagation()} style={{ background:theme.card, border:`1px solid ${theme.border}`, borderRadius:16, padding:20, maxWidth:420, maxHeight:"80vh", overflowY:"auto", cursor:"default" }}>
            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:14 }}>
              <div style={{ fontSize:15, fontWeight:800, color:theme.text }}>ℹ️ Sobre tu rutina</div>
              <button onClick={cerrarInfoRutina} style={{ width:30, height:30, borderRadius:"50%", background:theme.surface, border:`1px solid ${theme.border}`, color:theme.text, fontSize:14, cursor:"pointer" }}>✕</button>
            </div>
            {(() => {
              const infoTitBig = { fontSize:13, fontWeight:800, color:theme.accentLight, letterSpacing:0.4, marginBottom:8, display:"flex", alignItems:"center", gap:6, background:`${theme.accentLight}1f`, border:`1px solid ${theme.accentLight}59`, borderRadius:8, padding:"8px 10px" };
              const infoSec = { fontSize:12, color:theme.muted, marginBottom:16, lineHeight:1.6 };
              const infoTit = { color:theme.accentLight, fontWeight:700, marginBottom:4, fontSize:12.5 };
              const infoDiv = { height:1, background:theme.border, margin:"16px 0" };
              const infoSub = { margin:"8px 0 8px 4px", paddingLeft:10, borderLeft:`2px solid ${theme.border}` };
              const infoPct = { color:theme.gold, fontWeight:700 };
              const rirBadge = (bg, color) => ({ display:"inline-block", padding:"1px 7px", borderRadius:10, fontSize:10, fontWeight:800, background:bg, color });
              return (
                <>
                  <div style={infoTitBig}>🔥 CALENTAMIENTO GENERAL</div>
                  <div style={infoSec}>
                    Es la entrada en calor antes de ejecutar cualquier ejercicio con peso: se realiza movilidad articular y, según el día suele ocuparse banda elástica y/o algo de cardio suave. Lo realizamos para preparar tu cuerpo para la sesión y prevenir lesiones.
                  </div>

                  <div style={infoDiv} />

                  <div style={infoTitBig}>📋 CÓMO USAR TU RUTINA</div>
                  <div style={infoSec}>
                    Siempre el primer ejercicio de cada grupo muscular pasa por una fase de aproximación: se ejecuta el mismo movimiento pero a menor carga, en los % que indica tu coach, buscando la carga óptima para las series efectivas. Los ejercicios que siguen para ese mismo grupo muscular normalmente no la repiten, porque tu cuerpo ya está a temperatura para movimientos parecidos — a menos que cambies de grupo muscular o busques otra carga.
                    <div style={infoSub}>
                      <b style={{ color:theme.text }}>1. Series de aproximación</b><br/>
                      Debes subir el peso poco a poco, en % de tu carga efectiva, para acercarte a ella sin llegar cansado. No siempre son 3 — pueden ser más según el ejercicio y cuánto peso haya que subir. Ejemplo típico: aproximación 1 a <span style={infoPct}>~50–60%</span>, aproximación 2 a <span style={infoPct}>~70–80%</span>, aproximación 3 a <span style={infoPct}>~85–90%</span>, subiendo la carga y bajando las repeticiones en cada una. El kg que ves sugerido se calcula a partir del último peso efectivo que registraste la semana anterior — la primera vez que hagas la rutina no vas a tener carga sugerida y tienes que colocarla tú; después, puedes corregirla si no te calza.
                    </div>
                    <div style={infoSub}>
                      <b style={{ color:theme.text }}>2. Series efectivas</b><br/>
                      Las series que <b style={{ color:theme.text }}>sí cuentan</b> para tu progreso — el peso que buscas es el que te permite lograr las repeticiones y el RIR que definió tu coach. No siempre serán 8 repeticiones efectivas, eso varía según cada ejercicio y lo que tu coach determine. Aquí es donde registras tu peso usado, y puedes ir viendo semana a semana las cargas que ya usaste.
                    </div>
                    <div style={infoSub}>
                      <b style={{ color:theme.text }}>3. Tempo (cadencia)</b><br/>
                      Justo al lado del tiempo de descanso, abajo del nombre del ejercicio, vas a ver un cartel como <b style={{ color:theme.text }}>🆃 3-1-1</b>: son los segundos de bajada (fase negativa o excéntrica), pausa abajo (isométrica) y subida (fase positiva o concéntrica) en cada repetición. Te ayuda a controlar la velocidad del movimiento — ese ejemplo es bajar en 3 segundos, pausar 1 segundo abajo y subir en 1 segundo.
                    </div>
                  </div>

                  <div style={infoDiv} />

                  <div style={infoSec}>
                    <div style={infoTit}>RIR (repeticiones en reserva)</div>
                    Es cuántas repeticiones más, con buena técnica, sentías que podías hacer cuando terminaste la serie.
                    <br/><br/>
                    Por ejemplo: si te piden 8 repeticiones con RIR 2, haces esas 8 pero tu sensación es que podrías haber sacado 2 más — esas 2 quedaron "guardadas".
                    <table style={{ width:"100%", borderCollapse:"collapse", marginTop:8, fontSize:11 }}>
                      <tbody>
                        <tr>
                          <th style={{ padding:"6px 6px", textAlign:"center", borderBottom:`1px solid ${theme.border}`, color:theme.text, fontWeight:700, background:theme.surface }}>Reps pedidas</th>
                          <th style={{ padding:"6px 6px", textAlign:"center", borderBottom:`1px solid ${theme.border}`, color:theme.text, fontWeight:700, background:theme.surface }}>RIR objetivo</th>
                          <th style={{ padding:"6px 6px", textAlign:"center", borderBottom:`1px solid ${theme.border}`, color:theme.text, fontWeight:700, background:theme.surface }}>Lo que percibías que podías hacer</th>
                        </tr>
                        <tr>
                          <td style={{ padding:"6px 6px", textAlign:"center", borderBottom:`1px solid ${theme.border}`, color:theme.muted }}>8</td>
                          <td style={{ padding:"6px 6px", textAlign:"center", borderBottom:`1px solid ${theme.border}` }}><span style={rirBadge(`${theme.success}2e`, theme.success)}>RIR 3</span></td>
                          <td style={{ padding:"6px 6px", textAlign:"center", borderBottom:`1px solid ${theme.border}`, color:theme.text, fontWeight:700 }}>hasta 11</td>
                        </tr>
                        <tr>
                          <td style={{ padding:"6px 6px", textAlign:"center", borderBottom:`1px solid ${theme.border}`, color:theme.muted }}>8</td>
                          <td style={{ padding:"6px 6px", textAlign:"center", borderBottom:`1px solid ${theme.border}` }}><span style={rirBadge(`${theme.accentLight}2e`, theme.accentLight)}>RIR 2</span></td>
                          <td style={{ padding:"6px 6px", textAlign:"center", borderBottom:`1px solid ${theme.border}`, color:theme.text, fontWeight:700 }}>hasta 10</td>
                        </tr>
                        <tr>
                          <td style={{ padding:"6px 6px", textAlign:"center", borderBottom:`1px solid ${theme.border}`, color:theme.muted }}>8</td>
                          <td style={{ padding:"6px 6px", textAlign:"center", borderBottom:`1px solid ${theme.border}` }}><span style={rirBadge(`${theme.warning}2e`, theme.warning)}>RIR 1</span></td>
                          <td style={{ padding:"6px 6px", textAlign:"center", borderBottom:`1px solid ${theme.border}`, color:theme.text, fontWeight:700 }}>hasta 9</td>
                        </tr>
                        <tr>
                          <td style={{ padding:"6px 6px", textAlign:"center", color:theme.muted }}>8</td>
                          <td style={{ padding:"6px 6px", textAlign:"center" }}><span style={rirBadge(`${theme.danger}2e`, theme.danger)}>Fallo</span></td>
                          <td style={{ padding:"6px 6px", textAlign:"center", color:theme.text, fontWeight:700 }}>8 (no sale la 9)</td>
                        </tr>
                      </tbody>
                    </table>
                    <br/>
                    Si te sobró mucho margen (pedían RIR 2 y sientes que hubieras podido con 4-5 más), sube el peso la próxima vez. Si no llegaste a las repeticiones pedidas, bájalo.
                  </div>

                  <div style={infoDiv} />

                  <div style={infoTitBig}>🔗 SUPERSERIES Y BISERIES</div>
                  <div style={infoSec}>
                    Cuando en tu rutina ves un aviso <b style={{ color:theme.gold }}>"SUPERSERIE"</b> arriba de un ejercicio, significa que ese ejercicio está agrupado con el que sigue (o los que siguen): los haces uno detrás de otro, <b style={{ color:theme.text }}>sin descansar entre ellos</b>. El cronómetro de descanso recién aparece cuando terminas la ronda completa del grupo, no entre cada ejercicio.
                  </div>

                  <div style={infoSec}>
                    <div style={infoTit}>⚡ Técnicas de intensidad</div>
                    Algunas series efectivas pueden venir marcadas con una técnica especial. Tu coach define el valor exacto para cada serie — lo vas a ver junto a ella. Estos son solo ejemplos de referencia:
                    <div style={infoSub}>
                      <b style={{ color:COLORES_TECNICA.dropset }}>Dropset</b><br/>
                      Al llegar al fallo o cerca de él, bajas el peso <span style={infoPct}>ej. 20-30%</span> de inmediato (sin descansar) y sigues sumando repeticiones.
                    </div>
                    <div style={infoSub}>
                      <b style={{ color:COLORES_TECNICA.isometrica }}>Pausa isométrica</b><br/>
                      Bajas controlado y te quedas quieto abajo <span style={infoPct}>ej. 3-5 seg</span> antes de subir explosivo.
                    </div>
                    <div style={infoSub}>
                      <b style={{ color:COLORES_TECNICA.restpause }}>Rest-pause</b><br/>
                      Llegas cerca del fallo, descansas <span style={infoPct}>ej. 10-15 seg</span> y sacas algunas repeticiones más con el mismo peso; puede haber una segunda pausa igual de corta para sumar unas pocas más.
                    </div>
                  </div>

                  <div style={infoDiv} />

                  <div style={infoSec}>
                    <div style={infoTit}>🏃 Cardio</div>
                    Algunos días tu rutina incluye cardio con una duración sugerida y, a veces, una zona de pulso (FC). Si no alcanzas a completar los minutos pedidos, puedes reemplazarlo por su equivalente en pasos.
                  </div>

                  <div style={infoTitBig}>🧘 VUELTA A LA CALMA</div>
                  <div style={infoSec}>
                    Al terminar tu sesión, dedica unos minutos a estiramientos pasivos de los músculos que trabajaste ese día — ayuda a la recuperación y baja gradualmente la intensidad antes de terminar. Tu coach puede indicarte estiramientos específicos según el grupo muscular entrenado.
                  </div>

                  <div style={infoDiv} />

                  <div style={infoSec}>
                    <div style={infoTit}>💥 Intensidad del entrenamiento</div>
                    Al terminar cada sesión te pedimos calificar qué tan intensa sentiste la sesión completa (1 al 10). A diferencia del RIR, que es por serie, esto es tu sensación general de todo el entrenamiento — le ayuda a tu coach a ver tu carga de esfuerzo día a día.
                  </div>

                  <div style={infoSec}>
                    <div style={infoTit}>😴 Calidad del sueño</div>
                    En tu Diario registras cuántas horas dormiste y qué tan buena fue esa calidad (1 al 10). La calidad tiene que ver sobre todo con cuántas veces te despertaste: si dormiste de corrido sin despertar, normalmente es muy buena calidad (8-10 aprox); si te despertaste varias veces durante la noche o te costó volver a dormirte, la calidad baja — aunque hayas dormido muchas horas en total. Esto le permite a tu coach relacionar tu descanso con tu rendimiento y ajustar tu plan si hace falta.
                  </div>

                  <div style={infoDiv} />

                  <div style={infoSec}>
                    <div style={infoTit}>Descansos entre series</div>
                    El rango indicado es una guía y puede ir desde 60 segundos hasta 240 o más, según el ejercicio. Si sientes que aún no te recuperas al llegar al tiempo máximo, está bien tomarte unos segundos más antes de la siguiente serie.
                  </div>

                  <div style={{ ...infoSec, marginBottom:0 }}>
                    <div style={infoTit}>Imágenes de referencia</div>
                    Las imágenes/animaciones de los ejercicios son referenciales, para ayudarte a identificar el movimiento. Algunos ejercicios pueden variar levemente según el equipo disponible en tu gimnasio.
                  </div>
                </>
              );
            })()}
          </div>
        </div>
      )}

      {/* Selector de rutina si hay más de una -- ordenadas de lunes a domingo,
          en grilla pareja (en vez de una fila de pastillas de ancho variable)
          para que quede prolijo sin importar cuántas rutinas tenga el día. */}
      {rutinas.length > 1 && (
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 6, marginBottom: 14 }}>
          {rutinas.slice().sort((a, b) => ORDEN_DIAS_SEMANA.indexOf(a.dia) - ORDEN_DIAS_SEMANA.indexOf(b.dia)).map(r => {
            const activa = rutinaActiva.id === r.id;
            return (
              <button key={r.id} onClick={() => { setRutinaActiva(r); setCompletado(false); setRegistros({}); }}
                style={{ textAlign: "left", display:"flex", alignItems:"center", gap:6, background: activa ? theme.accent : theme.surface, border: `1px solid ${activa ? theme.accent : theme.border}`, borderRadius: 10, padding: "8px 8px", cursor: "pointer", minWidth: 0 }}>
                {r.grupo_muscular && <ImagenGrupoMuscular nombre={r.grupo_muscular} mapa={mapaImagenesGrupoMuscular} size={32} />}
                <div style={{ minWidth: 0 }}>
                  <div style={{ fontSize: 9, fontWeight: 700, letterSpacing: 0.4, textTransform: "uppercase", color: activa ? "rgba(255,255,255,0.75)" : theme.muted }}>{r.dia || "Sin día"}</div>
                  <div style={{ fontSize: 11, fontWeight: 700, color: activa ? "#fff" : theme.text, marginTop: 2, lineHeight: 1.2, display: "-webkit-box", WebkitLineClamp: 2, WebkitBoxOrient: "vertical", overflow: "hidden" }}>{r.nombre}</div>
                </div>
              </button>
            );
          })}
        </div>
      )}

      {/* Calentamiento general de la sesión (colapsado por defecto) */}
      {Array.isArray(rutinaActiva.calentamiento_general) && rutinaActiva.calentamiento_general.length > 0 && (
        <Card style={{ marginBottom: 14, padding:0, overflow:"hidden", border: `1px solid ${theme.accent}44` }}>
          <div onClick={() => setVerCalentamiento(!verCalentamiento)} style={{ padding:14, cursor:"pointer", display:"flex", justifyContent:"space-between", alignItems:"center" }}>
            <div style={{ fontSize: 11, fontWeight: 800, color: theme.accentLight, letterSpacing: 0.5 }}>🔥 CALENTAMIENTO GENERAL</div>
            <span style={{ fontSize:11, color:theme.accentLight }}>{verCalentamiento ? "▲ ocultar" : `▼ ver (${rutinaActiva.calentamiento_general.length})`}</span>
          </div>
          {verCalentamiento && (
            <div style={{ padding:"0 14px 14px" }}>
              {rutinaActiva.calentamiento_general.map((m, i) => (
                <div key={i} style={{ padding: "8px 4px", display:"flex", alignItems:"center", gap:10, borderBottom: i < rutinaActiva.calentamiento_general.length - 1 ? `1px solid ${theme.border}` : "none" }}>
                  <ImagenReferenciaEjercicio nombre={m.nombre} mapa={mapaImagenes} size={56} />
                  <div style={{ flex:1, minWidth:0, borderLeft:`2px solid ${theme.accent}88`, paddingLeft:9 }}>
                    <div style={{ fontSize: 12, fontWeight: 700, color: theme.text, textTransform:"uppercase", letterSpacing:0.4, lineHeight:1.3, display:"-webkit-box", WebkitLineClamp:2, WebkitBoxOrient:"vertical", overflow:"hidden" }}>{m.nombre}</div>
                    <div style={{ fontSize: 11, color: theme.muted, marginTop:2 }}>{m.detalle}</div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </Card>
      )}

      {/* Ejercicios */}
      {ejercicios.map((ej) => {
        const series = Array.isArray(ej.series) ? ej.series : [];
        return (
          <Card key={ej.id} style={{ marginBottom: 14 }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 6, gap:10 }}>
              <div style={{ display:"flex", alignItems:"center", gap:10, flex:1, minWidth:0 }}>
                <ImagenReferenciaEjercicio nombre={ej.nombre} mapa={mapaImagenes} size={64} />
                <div style={{ flex:1, minWidth:0, borderLeft:`3px solid ${theme.accent}`, paddingLeft:10 }}>
                  {ej.grupo_superserie && (
                    <div style={{ display:"inline-block", fontSize:9, fontWeight:800, color:theme.gold, background:`${theme.gold}18`, border:`1px solid ${theme.gold}44`, borderRadius:6, padding:"2px 6px", marginBottom:4 }}>🔗 SUPERSERIE {ej.grupo_superserie} · sin descanso entre ejercicios</div>
                  )}
                  <div style={{ fontSize: 14, fontWeight: 800, color: theme.text, marginBottom: 4, textTransform:"uppercase", letterSpacing:0.4, lineHeight:1.3, display:"-webkit-box", WebkitLineClamp:2, WebkitBoxOrient:"vertical", overflow:"hidden" }}>{ej.nombre}</div>
                  <div style={{ display:"flex", alignItems:"center", gap:8, flexWrap:"wrap" }}>
                    <div style={{ fontSize: 11, color: theme.muted }}>⏱ Descanso: {ej.descanso_desde && ej.descanso_hasta ? `${ej.descanso_desde}-${ej.descanso_hasta}s` : `${ej.descanso}s`}</div>
                    <div style={{ fontSize: 9.5, fontWeight:800, color: theme.muted, background:theme.card, border:`1px solid ${theme.border}`, borderRadius:6, padding:"2px 6px" }} title="Tempo: bajada-pausa-subida">🆃 {ej.tempo || "3-1-1"}</div>
                  </div>
                </div>
              </div>
              {ej.video_url && (
                <a href={ej.video_url} target="_blank" rel="noreferrer" style={{ width: 36, height: 36, borderRadius: 10, background: theme.surface, display: "flex", alignItems: "center", justifyContent: "center", border: `1px solid ${theme.border}`, flexShrink: 0, textDecoration: "none" }}>▶️</a>
              )}
            </div>

            {(() => {
              let contAprox = 0, contEfect = 0;
              let seccionAnterior = null;
              return series.map((s, idx) => {
                const key = `${ej.id}-${idx}`;
                const reg = registros[key] || {};
                const tipo = s.tipo || "efectiva";
                let etiqueta, colorTipo, tituloSeccion;
                if (tipo === "aproximacion") { contAprox++; etiqueta = `A${contAprox}`; colorTipo = "#B0C4DE"; tituloSeccion = "APROXIMACIÓN"; }
                else { contEfect++; etiqueta = `${contEfect}`; colorTipo = theme.accentLight; tituloSeccion = "SERIES EFECTIVAS"; }
                const mostrarEncabezado = tipo !== seccionAnterior;
                seccionAnterior = tipo;
                const rir = typeof s.rir === "number" ? s.rir : parseInt(s.rir) || 2;
                const rc = getRirColor(rir);
                // La carga "semana anterior" se compara por posición entre series
                // EFECTIVAS únicamente (contEfect), no por posición en el arreglo
                // completo, para que la aproximación no la desordene.
                const anterior = tipo === "efectiva" ? ultimasCargas[`${ej.id}-${contEfect}`] : null;
                // El kg sugerido de aproximación se calcula con el % (extremo
                // inferior del rango que definió el coach) sobre el último peso
                // conocido de la PRIMERA serie efectiva de este ejercicio. Si el
                // alumno todavía no tiene carga registrada ahí, no hay sugerencia
                // -- igual que la primera vez en una serie efectiva.
                const refEfectiva = ultimasCargas[`${ej.id}-1`];
                const kgSugeridoAprox = (refEfectiva?.kg && s.pctDesde) ? redondearKg((parseFloat(s.pctDesde) / 100) * refEfectiva.kg) : null;
                const placeholderKg = tipo === "efectiva"
                  ? (anterior?.kg || "kg")
                  : (kgSugeridoAprox || "kg");
                // Color propio por técnica de intensidad, para el nombre dentro del
                // recuadro de la serie (no se usa para teñir el recuadro entero,
                // solo el texto, así queda claro a qué serie corresponde sin
                // "pintar" toda la fila).
                const colorTecnica = tipo === "efectiva" ? COLORES_TECNICA[s.tecnica] : null;
                const esActiva = estadoSerie === "activa" && serieObjetivo && serieObjetivo.ejId === ej.id && serieObjetivo.idx === idx;
                // Para aproximación, kg/reps vienen precargados automáticamente
                // (ver efecto de precarga más arriba) -- eso solo no cuenta como
                // "hecha", si no toda fila de aproximación se vería marcada en
                // verde desde el principio sin que el alumno hiciera nada. Solo
                // cuenta si tocó el check, o si escribió algo a mano encima.
                const hecha = !!seriesHechas[key] || (tipo === "efectiva" ? !!(reg.kg && reg.reps) : !!((reg.kg && !reg._autoKg) || (reg.reps && !reg._autoReps)));
                // La aproximación no usa columna de RIR (se trabaja en % de la
                // efectiva, no en esfuerzo percibido) -- 5 columnas en vez de 6.
                const columnas = tipo === "efectiva" ? "38px 1fr 46px 40px 44px 24px" : "38px 1fr 46px 40px 24px";
                return (
                  <div key={idx}>
                  {mostrarEncabezado && (
                    <div style={{ marginTop: idx > 0 ? 12 : 0, marginBottom: 6 }}>
                      <div style={{ fontSize: 10, fontWeight: 800, color: colorTipo, background: `${colorTipo}18`, border: `1px solid ${colorTipo}44`, borderRadius: 6, padding: "3px 8px", marginBottom: 6, display: "inline-block" }}>{tituloSeccion}</div>
                      <div style={{ display: "grid", gridTemplateColumns: columnas, gap: 3 }}>
                        {(tipo === "efectiva" ? ["SERIE", "OBJETIVO", "KG", "REPS", "RIR", "✓"] : ["SERIE", "OBJETIVO", "KG", "REPS", "✓"]).map(h => (
                          <span key={h} style={{ fontSize: 9, color: theme.muted, textAlign: "center", fontWeight: 700 }}>{h}</span>
                        ))}
                      </div>
                    </div>
                  )}
                  <div style={{
                    display: "grid", gridTemplateColumns: columnas, gap: 3, alignItems: "center", marginBottom: 2, borderRadius: 10, padding: tipo === "aproximacion" ? "5px 6px" : "7px 6px",
                    background: esActiva ? `${theme.accentLight}29` : hecha ? `${theme.success}12` : `${colorTipo}0d`,
                    border: `1px solid ${esActiva ? theme.accentLight : hecha ? theme.success + "44" : colorTipo + "33"}`,
                    boxShadow: esActiva ? `0 0 0 1px ${theme.accentLight}, 0 0 14px ${theme.accentLight}59` : "none",
                  }}>
                    <div style={{ textAlign: "center", fontSize: 11, fontWeight: 800, color: colorTipo }}>{etiqueta}</div>
                    <div style={{ fontSize: 12, color: theme.muted, paddingLeft: 4, lineHeight: 1.15, minWidth: 0 }}>
                      <span style={{ color: theme.text, fontWeight: 700, display: "block", lineHeight: 1.1 }}>{s.reps} reps</span>
                      {tipo === "aproximacion" && (s.pctDesde || s.pctHasta) && (
                        <div style={{ fontSize: 8.5, color: colorTipo, fontWeight: 700, marginTop: 2, lineHeight: 1.1 }}>{s.pctDesde}-{s.pctHasta}% de tu efectiva</div>
                      )}
                      {tipo === "efectiva" && s.tecnica === "dropset" && (
                        <div style={{ fontSize: 9, color: colorTecnica, fontWeight: 700, marginTop: 4, marginLeft: -10, lineHeight: 1.1, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{s.dropsetCantidad || 2} drops -{s.dropsetPct || 25}%</div>
                      )}
                      {tipo === "efectiva" && s.tecnica === "isometrica" && (
                        <div style={{ fontSize: 9, color: colorTecnica, fontWeight: 700, marginTop: 4, marginLeft: -10, lineHeight: 1.1, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>Pausa {s.isoSegundos || 4}s (iso)</div>
                      )}
                      {tipo === "efectiva" && s.tecnica === "restpause" && (
                        <div style={{ fontSize: 9, color: colorTecnica, fontWeight: 700, marginTop: 4, marginLeft: -10, lineHeight: 1.1, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>R-pause {s.rpCantidad || 2}×{s.rpSegundos || 15}s</div>
                      )}
                    </div>
                    <input value={reg.kg || ""} onChange={e => setReg(ej.id, idx, "kg", e.target.value)} placeholder={placeholderKg}
                      style={{ background: theme.card, border: `1px solid ${reg.kg ? theme.accent + "66" : theme.border}`, borderRadius: 6, padding: "5px 2px", color: theme.text, fontSize: 12, fontWeight: 700, width: "100%", textAlign: "center", outline: "none", boxSizing: "border-box" }} />
                    <input value={reg.reps || ""} onChange={e => setReg(ej.id, idx, "reps", e.target.value)} placeholder={s.reps}
                      style={{ background: theme.card, border: `1px solid ${reg.reps ? theme.accent + "66" : theme.border}`, borderRadius: 6, padding: "5px 2px", color: theme.text, fontSize: 12, fontWeight: 700, width: "100%", textAlign: "center", outline: "none", boxSizing: "border-box" }} />
                    {tipo === "efectiva" && (
                      <div style={{ background: `${rc}18`, border: `1px solid ${rc}55`, borderRadius: 6, padding: "4px 2px", textAlign: "center", fontSize: 10, fontWeight: 800, color: rc }}>{getRirLabel(rir)}</div>
                    )}
                    <div onClick={() => setSeriesHechas({ ...seriesHechas, [key]: !seriesHechas[key] })}
                      style={{ width: 20, height: 20, borderRadius: 6, border: `2px solid ${seriesHechas[key] ? theme.success : theme.border}`, background: seriesHechas[key] ? theme.success : "transparent", display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", fontSize: 11, color: "#fff", fontWeight: 800 }}>{seriesHechas[key] ? "✓" : ""}</div>
                  </div>
                  {esActiva && (
                    <div style={{ display:"flex", alignItems:"center", gap:6, fontSize:10, color:theme.accentLight, fontWeight:700, paddingLeft:6, marginBottom:6, marginTop:-2 }}>
                      🔵 Serie en curso...
                    </div>
                  )}
                  {anterior && (
                    <div style={{ fontSize: 10, color: theme.muted, paddingLeft: 6, marginBottom: 8 }}>
                      Semana anterior: <span style={{ color: colorTipo, fontWeight: 700 }}>{anterior.kg}kg × {anterior.reps}</span> {anterior.fecha ? `(${anterior.fecha})` : ""}
                    </div>
                  )}
                  </div>
                );
              });
            })()}
          </Card>
        );
      })}

      {/* Cardio planificado del día (los pasos se registran en Inicio) */}
      {Array.isArray(rutinaActiva.cardio) && rutinaActiva.cardio.length > 0 && (
        <Card style={{ marginBottom: 14, border: `1px solid ${theme.accent}44` }}>
          <div style={{ fontSize: 11, fontWeight: 800, color: theme.accentLight, letterSpacing: 0.5, marginBottom: 12 }}>🏃 CARDIO</div>

          {rutinaActiva.cardio.map((c, i) => {
            const reg = cardioRegistros[i] || {};
            const fcMaxTeorica = edadAlumno ? 220 - edadAlumno : null;
            const lpmMin = fcMaxTeorica && c.fcMinPct ? Math.round(fcMaxTeorica * (parseFloat(c.fcMinPct) / 100)) : null;
            const lpmMax = fcMaxTeorica && c.fcMaxPct ? Math.round(fcMaxTeorica * (parseFloat(c.fcMaxPct) / 100)) : null;
            const pasosEquivalentes = c.duracionMin ? estimarPasosEquivalentes(c.duracionMin) : 0;
            return (
              <div key={i} style={{ background:theme.surface, borderRadius:8, padding:10, marginTop: i === 0 ? 0 : 8 }}>
                <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:6, gap:8, flexWrap:"wrap" }}>
                  <div style={{ fontSize:13, fontWeight:700, color:theme.text }}>{c.tipo || "Cardio"}</div>
                  <div style={{ display:"flex", gap:6 }}>
                    <button onClick={() => marcarCardio(i, c, (reg.completado && !reg.via_pasos) ? null : "cardio")}
                      title="Hice el cardio"
                      style={{ background: (reg.completado && !reg.via_pasos) ? `${theme.success}22` : "transparent", border:`1px solid ${(reg.completado && !reg.via_pasos) ? theme.success : theme.border}`, borderRadius:6, padding:"4px 8px", color: (reg.completado && !reg.via_pasos) ? theme.success : theme.muted, fontSize:10, cursor:"pointer", fontWeight:700, whiteSpace:"nowrap" }}>
                      {(reg.completado && !reg.via_pasos) ? "✅ Cardio" : "🏃 Cardio"}
                    </button>
                    {pasosEquivalentes > 0 && (
                      <button onClick={() => marcarCardio(i, c, (reg.completado && reg.via_pasos) ? null : "pasos")}
                        title={`Hice ≈${pasosEquivalentes.toLocaleString("es-CL")} pasos en vez del cardio`}
                        style={{ background: (reg.completado && reg.via_pasos) ? `${theme.success}22` : "transparent", border:`1px solid ${(reg.completado && reg.via_pasos) ? theme.success : theme.border}`, borderRadius:6, padding:"4px 8px", color: (reg.completado && reg.via_pasos) ? theme.success : theme.muted, fontSize:10, cursor:"pointer", fontWeight:700, whiteSpace:"nowrap" }}>
                        {(reg.completado && reg.via_pasos) ? "✅ Pasos" : "🚶 Pasos"}
                      </button>
                    )}
                  </div>
                </div>
                {c.duracionMin ? (
                  <div style={{ display:"flex", alignItems:"baseline", gap:6, marginBottom:6 }}>
                    <span style={{ fontSize:28, fontWeight:900, color:theme.text, lineHeight:1 }}>{c.duracionMin}</span>
                    <span style={{ fontSize:12, color:theme.muted, fontWeight:600 }}>minutos</span>
                  </div>
                ) : (
                  <div style={{ fontSize:11, color:theme.muted, marginBottom: (lpmMin || lpmMax) ? 4 : 8 }}>Planificado: sin duración definida</div>
                )}
                {c.notas && (
                  <div style={{ fontSize:11, color:theme.muted, marginBottom: (lpmMin || lpmMax) ? 4 : 8 }}>{c.notas}</div>
                )}
                {(lpmMin || lpmMax) && (
                  <div style={{ fontSize:11, color:theme.accentLight, marginBottom:8, textAlign:"center" }}>
                    <div>🎯 Zona quema grasa: {lpmMin || "—"}{lpmMax ? `-${lpmMax}` : ""} lpm</div>
                    <div style={{ color:theme.muted, fontSize:12, marginTop:0 }}>(latidos por minuto)</div>
                  </div>
                )}
                {!reg.completado && pasosEquivalentes > 0 && (
                  <div style={{ fontSize:11, color:theme.warning, lineHeight:1.4 }}>
                    💡 Si no alcanzas a hacer los {c.duracionMin} min de cardio, puedes sustituirlos con <span style={{ fontWeight:700 }}>≈{pasosEquivalentes.toLocaleString("es-CL")} pasos</span> extra y marcar "🚶 Pasos" en vez de "🏃 Cardio".
                  </div>
                )}
              </div>
            );
          })}
        </Card>
      )}

      {/* Vuelta a la calma: estiramientos pasivos post-sesión (colapsado por defecto) */}
      {Array.isArray(rutinaActiva.vuelta_calma) && rutinaActiva.vuelta_calma.length > 0 && (
        <Card style={{ marginBottom: 14, padding:0, overflow:"hidden", border: `1px solid ${theme.accent}44` }}>
          <div onClick={() => setVerVueltaCalma(!verVueltaCalma)} style={{ padding:14, cursor:"pointer", display:"flex", justifyContent:"space-between", alignItems:"center" }}>
            <div style={{ fontSize: 11, fontWeight: 800, color: theme.accentLight, letterSpacing: 0.5 }}>🧘 VUELTA A LA CALMA</div>
            <span style={{ fontSize:11, color:theme.accentLight }}>{verVueltaCalma ? "▲ ocultar" : `▼ ver (${rutinaActiva.vuelta_calma.length})`}</span>
          </div>
          {verVueltaCalma && (
            <div style={{ padding:"0 14px 14px" }}>
              {rutinaActiva.vuelta_calma.map((m, i) => (
                <div key={i} style={{ padding: "8px 4px", display:"flex", alignItems:"center", gap:10, borderBottom: i < rutinaActiva.vuelta_calma.length - 1 ? `1px solid ${theme.border}` : "none" }}>
                  <ImagenReferenciaEjercicio nombre={m.nombre} mapa={mapaImagenes} size={56} />
                  <div style={{ flex:1, minWidth:0, borderLeft:`2px solid ${theme.accent}88`, paddingLeft:9 }}>
                    <div style={{ fontSize: 12, fontWeight: 700, color: theme.text, textTransform:"uppercase", letterSpacing:0.4, lineHeight:1.3, display:"-webkit-box", WebkitLineClamp:2, WebkitBoxOrient:"vertical", overflow:"hidden" }}>{m.nombre}</div>
                    <div style={{ fontSize: 11, color: theme.muted, marginTop:2 }}>{m.detalle}</div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </Card>
      )}

      {!completado && faltaParaTerminar && (
        <Card style={{ textAlign:"center", padding:16, border:`1px dashed ${theme.border}` }}>
          <div style={{ fontSize:12, color:theme.muted, lineHeight:1.5 }}>
            {faltaParaTerminar === "series"
              ? "Te faltan series por completar más arriba."
              : "Te falta marcar el cardio como hecho más arriba."}
            {" "}Termina eso para poder cerrar el entrenamiento.
          </div>
        </Card>
      )}

      {!completado && !faltaParaTerminar && (
        <Btn onClick={async () => {
            const { data: { user } } = await supabase.auth.getUser();
            if (user && rutinaActiva) {
              const inserts = [];
              const hoyStr = fechaOperativaStr();
              ejercicios.forEach(ej => {
                const series = Array.isArray(ej.series) ? ej.series : [];
                let serieEfectiva = 0; // numeración independiente de la aproximación
                series.forEach((s, idx) => {
                  const key = `${ej.id}-${idx}`;
                  const reg = registros[key] || {};
                  const tipo = s.tipo || "efectiva";
                  if (tipo === "efectiva") serieEfectiva++;
                  const sugerido = tipo === "efectiva" ? ultimasCargas[`${ej.id}-${serieEfectiva}`]?.kg : null;
                  const kgFinal = reg.kg || sugerido || null;
                  const repsFinal = reg.reps || s.reps || null;
                  // Solo se guardan las series efectivas. La aproximación no se
                  // registra para no distorsionar las cargas reales de trabajo.
                  // La numeración de "serie" arranca en 1 para las efectivas, sin
                  // contar las de aproximación que las preceden.
                  if (tipo === "efectiva" && (kgFinal || repsFinal)) {
                    inserts.push({
                      usuario_id: user.id,
                      ejercicio_id: ej.id,
                      rutina_id: rutinaActiva.id,
                      serie: serieEfectiva,
                      kg: parseFloat(kgFinal) || null,
                      reps: parseInt(repsFinal) || null,
                      fecha: hoyStr,
                    });
                  }
                });
              });
              if (inserts.length > 0) {
                // Si el alumno ya había completado este entrenamiento hoy, se
                // reemplazan sus registros de hoy en vez de duplicarlos.
                await supabase.from("registros_entreno").delete()
                  .eq("usuario_id", user.id)
                  .eq("rutina_id", rutinaActiva.id)
                  .eq("fecha", hoyStr);
                const { error } = await supabase.from("registros_entreno").insert(inserts);
                if (error) {
                  alert("No se pudieron guardar tus cargas: " + error.message);
                  return;
                }
                await cargarUltimasCargas(user.id);
              }
            }
            setCompletado(true);
          }} style={{ background: `linear-gradient(135deg, ${theme.accentLight}, ${theme.accent})`, boxShadow: `0 0 18px ${theme.accent}66`, padding: 16, fontSize: 15, fontWeight: 800, letterSpacing: 1, borderRadius: 14 }}>✓ ENTRENAMIENTO COMPLETADO</Btn>
      )}

      {completado && (
        <>
            {diarioPaso === "form" ? (
              <Card style={{ border: `1px solid ${theme.accent}44` }}>
                <div style={{ textAlign: "center", marginBottom: 14 }}>
                  <div style={{ fontSize: 28, marginBottom: 4 }}>🏆</div>
                  <div style={{ fontSize: 15, fontWeight: 700, color: theme.text }}>¡Entrenamiento completado!</div>
                  <div style={{ fontSize: 12, color: theme.muted, marginTop: 2 }}>Antes de salir, contanos rápido cómo estuvo</div>
                </div>

                <div style={{ marginBottom: 14 }}>
                  <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 6 }}>
                    <span style={{ fontSize: 13, color: theme.text }}>💥 ¿Qué tan intenso sentiste el entreno?</span>
                    <span style={{ fontSize: 13, fontWeight: 700, color: theme.accentLight }}>{intensidad}/10</span>
                  </div>
                  <input type="range" min={1} max={10} value={intensidad} onChange={e => setIntensidad(Number(e.target.value))} style={{ width: "100%", accentColor: theme.accent }} />
                </div>

                <div style={{ marginBottom: 14 }}>
                  <div style={{ fontSize: 13, color: theme.text, marginBottom: 8 }}>😴 ¿Cuántas horas dormiste anoche?</div>
                  <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                    <input value={horasSueno} onChange={e => setHorasSueno(e.target.value)} placeholder="0" type="number" step="0.5"
                      style={{ background: theme.surface, border: `2px solid #B0C4DE`, borderRadius: 10, padding: "10px 14px", color: theme.text, fontSize: 20, fontWeight: 800, width: 80, textAlign: "center", outline: "none" }} />
                    <span style={{ fontSize: 14, color: theme.muted }}>horas</span>
                  </div>
                </div>

                <div style={{ marginBottom: 18 }}>
                  <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 6 }}>
                    <span style={{ fontSize: 13, color: theme.text }}>😴 Calidad del sueño</span>
                    <span style={{ fontSize: 13, fontWeight: 700, color: "#B0C4DE" }}>{calidadSueno}/10</span>
                  </div>
                  <input type="range" min={1} max={10} value={calidadSueno} onChange={e => setCalidadSueno(Number(e.target.value))} style={{ width: "100%", accentColor: "#B0C4DE" }} />
                </div>

                <button onClick={async () => {
                  setGuardandoDiario(true);
                  const { data: { user } } = await supabase.auth.getUser();
                  if (user) {
                    const hoyStr = fechaOperativaStr();
                    await supabase.from("diario_registros").upsert({
                      usuario_id: user.id,
                      fecha: hoyStr,
                      energia: intensidad,
                      sueno: calidadSueno,
                      horas: parseFloat(horasSueno) || null,
                    }, { onConflict: "usuario_id,fecha" });
                  }
                  setGuardandoDiario(false);
                  setDiarioPaso("listo");
                }} style={{ width: "100%", background: `linear-gradient(135deg, ${theme.accentLight}, ${theme.accent})`, border: "none", borderRadius: 10, padding: 12, color: "#fff", fontSize: 14, fontWeight: 800, cursor: "pointer" }}>{guardandoDiario ? "Guardando..." : "Guardar y terminar"}</button>
                <div onClick={() => setDiarioPaso("listo")} style={{ textAlign: "center", fontSize: 12, color: theme.muted, marginTop: 10, cursor: "pointer" }}>Saltar</div>
              </Card>
            ) : (
              <Card style={{ textAlign: "center", background: `${theme.success}18`, border: `1px solid ${theme.success}44` }}>
                <div style={{ fontSize: 32, marginBottom: 8 }}>🏆</div>
                <div style={{ fontSize: 16, fontWeight: 700, color: theme.success }}>¡Bien hecho!</div>
                <div style={{ fontSize: 13, color: theme.muted, marginTop: 4 }}>Cargas guardadas correctamente</div>
              </Card>
            )}
          </>
      )}

      {mostrarBarraSerie && (
        <div style={{ position:"absolute", bottom:72, left:0, right:0, padding:"12px 16px", background:theme.surface, borderTop:`1px solid ${theme.border}`, boxShadow:"0 -8px 20px rgba(0,0,0,0.35)", zIndex:50 }}>
          <div style={{ textAlign:"center", fontSize:10, fontWeight:700, letterSpacing:0.3, lineHeight:"16px", minHeight:16, marginBottom:6, color: bottomLabelColorSerie, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>
            {bottomLabelSerie}
          </div>
          <button onClick={handleBotonSerie}
            style={{ width:"100%", position:"relative", overflow:"hidden", border:"none", borderRadius:14, padding:15, fontSize:14, fontWeight:800, letterSpacing:0.5, cursor:"pointer", color:"#fff", background: estadoSerie === "descansando" ? "#0B1F17" : bgBotonSerie, boxShadow:sombraBotonSerie }}>
            {estadoSerie === "descansando" && (
              <div style={{ position:"absolute", top:0, left:0, bottom:0, width:`${progresoDescansoPct}%`, background:bgBotonSerie, transition:"width 1s linear, background 1s linear" }} />
            )}
            <span style={{ position:"relative" }}>{textoBotonSerie}</span>
          </button>
          {estadoSerie === "descansando" && (
            <button onClick={() => {
              const opciones = ["salta", "memoria", "conecta"];
              setTipoMinijuego(opciones[Math.floor(Math.random() * opciones.length)]);
              setMinijuegoAbierto(true);
            }}
              style={{ width:"100%", marginTop:8, borderRadius:12, padding:11, fontSize:12.5, fontWeight:800, cursor:"pointer", border:`1.5px solid ${theme.accentLight}`, background:`${theme.accentLight}22`, color:"#8FA6FF", display:"flex", alignItems:"center", justifyContent:"center", gap:6 }}>
              🎮 Abrir minijuego
            </button>
          )}
        </div>
      )}
      {minijuegoAbierto && (
        <MinijuegoModal tipo={tipoMinijuego} onCerrar={cerrarMinijuego} />
      )}
      {minijuegoAbierto && estadoSerie === "idle" && (
        <div style={{ position:"absolute", inset:0, background:"rgba(5,5,10,0.95)", zIndex:2700, display:"flex", alignItems:"center", justifyContent:"center", padding:20 }}>
          <div style={{ background:theme.surface, border:`2px solid ${theme.success}`, borderRadius:18, padding:"26px 22px", textAlign:"center", maxWidth:280 }}>
            <div style={{ fontSize:34, marginBottom:8 }}>⏰</div>
            <div style={{ color:theme.success, fontWeight:800, fontSize:15, marginBottom:6 }}>¡Tu descanso terminó!</div>
            <div style={{ color:"#B0C4DE", fontSize:11.5, lineHeight:1.5, marginBottom:14 }}>Es hora de tu siguiente serie. Vuelve a la rutina cuando quieras.</div>
            <button onClick={cerrarMinijuego}
              style={{ border:"none", background:theme.success, color:"#052e1c", borderRadius:10, padding:"11px 22px", fontSize:12.5, fontWeight:800, cursor:"pointer" }}>
              Volver a la rutina
            </button>
          </div>
        </div>
      )}
      <NavBar active="rutina" onNav={onNav} />
    </div>
  );
}

function NutricionScreen({ onNav }) {
  const [dietas, setDietas] = useState([]);
  const [dieta, setDieta] = useState(null);
  const [loading, setLoading] = useState(true);
  const [bloqueado, setBloqueado] = useState(false);
  const [userId, setUserId] = useState(null);
  const [comidasEstado, setComidasEstado] = useState({});
  const [suplementosEstado, setSuplementosEstado] = useState({});
  const [modalCambio, setModalCambio] = useState(false);
  const [modalComidaIndex, setModalComidaIndex] = useState(null);
  const [modalDescripcion, setModalDescripcion] = useState("");
  const [modalFotoUrl, setModalFotoUrl] = useState(null);
  const [modalSubiendoFoto, setModalSubiendoFoto] = useState(false);
  const hoyStr = fechaOperativaStr();

  useEffect(() => {
    const cargar = async () => {
      const { data: { user } } = await supabase.auth.getUser();
      if (user) {
        const { data: pagoData } = await supabase.from("pagos").select("estado").eq("usuario_id", user.id).order("created_at", { ascending: false }).limit(1);
        if (pagoData && pagoData.length > 0 && pagoData[0].estado === "bloqueado") {
          setBloqueado(true);
          setLoading(false);
          return;
        }
        const { data } = await supabase
          .from("dietas")
          .select("*")
          .eq("usuario_id", user.id)
          .order("created_at", { ascending: false });
        if (data && data.length > 0) {
          setDietas(data);
          // Se acopla automáticamente al plan asignado al día de hoy (según la
          // rutina que le toca ese día), sin depender de que el alumno elija
          // manualmente ni de que guarde algo antes. Si ningún plan está
          // asignado a hoy, se usa el más reciente como respaldo general.
          const nombreHoy = nombreDiaOperativo();
          const dietaHoy = data.find(d => Array.isArray(d.dias) && d.dias.includes(nombreHoy));
          setDieta(dietaHoy || data[0]);
        }
        setUserId(user.id);

        // Carga el registro de cumplimiento de hoy (si ya marcó algo antes)
        const { data: regs } = await supabase
          .from("dieta_registros")
          .select("*")
          .eq("usuario_id", user.id)
          .eq("fecha", hoyStr);
        if (regs && regs.length > 0) {
          const estadoMap = {};
          regs.forEach(r => { estadoMap[r.comida_index] = r.estado; });
          setComidasEstado(estadoMap);
        }

        // Carga el registro de "tomado" de suplementos de hoy (si ya marcó algo antes)
        const { data: suplRegs } = await supabase
          .from("suplemento_registros")
          .select("*")
          .eq("usuario_id", user.id)
          .eq("fecha", hoyStr);
        if (suplRegs && suplRegs.length > 0) {
          const suplMap = {};
          suplRegs.forEach(r => { suplMap[r.suplemento_index] = r.tomado; });
          setSuplementosEstado(suplMap);
        }
      }
      setLoading(false);
    };
    cargar();
  }, []);

  if (loading) return (
    <div style={{ padding:"20px 16px 90px", height:"100%", boxSizing:"border-box", display:"flex", alignItems:"center", justifyContent:"center" }}>
      <div style={{ color:theme.muted }}>Cargando dieta...</div>
    </div>
  );

  if (bloqueado) return (
    <div style={{ padding: "20px 16px 90px", overflowY: "auto", height: "100%", boxSizing: "border-box" }}>
      <span onClick={() => onNav("alumno_home")} style={{ fontSize: 16, cursor: "pointer", color: theme.text }}>← Inicio</span>
      <Card style={{ textAlign: "center", padding: 40, marginTop: 20, background: `${theme.danger}12`, border: `1px solid ${theme.danger}44` }}>
        <div style={{ fontSize: 32, marginBottom: 12 }}>🔒</div>
        <div style={{ fontSize: 16, fontWeight: 800, color: theme.danger, marginBottom: 8 }}>Acceso bloqueado</div>
        <div style={{ fontSize: 13, color: theme.muted, marginBottom: 16 }}>Tu acceso a la dieta está bloqueado por pago pendiente. Regulariza tu situación para volver a verla.</div>
        <Btn onClick={() => onNav("pagos_alumno")}>Ver mis pagos</Btn>
      </Card>
      <NavBar active="nutricion" onNav={onNav} />
    </div>
  );

  if (!dieta) return (
    <div style={{ padding:"20px 16px 90px", overflowY:"auto", height:"100%", boxSizing:"border-box" }}>
      <div style={{ marginBottom:20 }}>
        <span onClick={() => onNav("alumno_home")} style={{ fontSize: 16, cursor: "pointer", color: theme.text, marginBottom: 6, display: "inline-block" }}>← Inicio</span>
        <div style={{ color:theme.muted, fontSize:12, marginTop:4 }}>PLAN NUTRICIONAL</div>
        <div style={{ fontSize:22, fontWeight:800, color:theme.text }}>Tu Dieta 🥗</div>
      </div>
      <Card style={{ textAlign:"center", padding:40 }}>
        <div style={{ fontSize:32, marginBottom:12 }}>🥗</div>
        <div style={{ fontSize:15, fontWeight:700, color:theme.text, marginBottom:8 }}>Tu coach aún no ha creado tu plan nutricional</div>
        <div style={{ fontSize:13, color:theme.muted }}>Aparecerá aquí cuando esté listo</div>
      </Card>
      <NavBar active="nutricion" onNav={onNav} />
    </div>
  );

  const comidas = Array.isArray(dieta.comidas) ? dieta.comidas : [];
  const suplementos = Array.isArray(dieta.suplementos) ? dieta.suplementos : [];
  const equivalencias = Array.isArray(dieta.equivalencias) ? dieta.equivalencias : [];

  const guardarRegistro = async (index, estado, descripcion = null, fotoUrl = null) => {
    if (!userId) return;
    await supabase.from("dieta_registros").upsert({
      usuario_id: userId,
      fecha: hoyStr,
      comida_index: index,
      comida_nombre: comidas[index]?.nombre || null,
      estado,
      descripcion,
      foto_url: fotoUrl,
    }, { onConflict: "usuario_id,fecha,comida_index" });
  };

  const handleComidaEstado = (index, estado) => {
    if (estado === "cambio") {
      setModalComidaIndex(index);
      setModalDescripcion("");
      setModalFotoUrl(null);
      setModalCambio(true);
    } else {
      setComidasEstado(prev => ({ ...prev, [index]: estado }));
      guardarRegistro(index, estado);
    }
  };

  // Comprime y sube la foto de la comida cambiada al mismo bucket que las
  // fotos de anamnesis/progreso, pero en su propia carpeta por alumno,
  // nombrada por fecha + índice de comida para no pisar otros días.
  const subirFotoComida = async (file) => {
    if (!file || !userId || modalComidaIndex === null) return;
    setModalSubiendoFoto(true);
    const comprimida = await comprimirFotoGlobal(file);
    const path = `${userId}/dieta/${hoyStr}-${modalComidaIndex}.jpg`;
    const { error } = await supabase.storage
      .from("fotos-alumnos")
      .upload(path, comprimida, { contentType: "image/jpeg", upsert: true });
    setModalSubiendoFoto(false);
    if (error) { alert("No se pudo subir la foto: " + error.message); return; }
    setModalFotoUrl(`https://srlucwsakjuivogvunzx.supabase.co/storage/v1/object/public/fotos-alumnos/${path}?t=${new Date().getTime()}`);
  };

  const cerrarModalCambio = () => {
    setModalCambio(false);
    setModalComidaIndex(null);
    setModalDescripcion("");
    setModalFotoUrl(null);
  };

  const handleGuardarCambio = () => {
    setComidasEstado(prev => ({ ...prev, [modalComidaIndex]: "cambio" }));
    guardarRegistro(modalComidaIndex, "cambio", modalDescripcion, modalFotoUrl);
    cerrarModalCambio();
  };

  const toggleSuplementoTomado = async (index, nombre) => {
    if (!userId) return;
    const nuevoValor = !suplementosEstado[index];
    setSuplementosEstado(prev => ({ ...prev, [index]: nuevoValor }));
    await supabase.from("suplemento_registros").upsert({
      usuario_id: userId,
      fecha: hoyStr,
      suplemento_index: index,
      suplemento_nombre: nombre || null,
      tomado: nuevoValor,
    }, { onConflict: "usuario_id,fecha,suplemento_index" });
  };

  const getEstadoColor = (estado) => {
    if (estado === "completada") return theme.success;
    if (estado === "no_hecha") return theme.danger;
    if (estado === "cambio") return theme.accent;
    return theme.surface;
  };

  return (
    <div style={{ padding:"20px 16px 90px", overflowY:"auto", height:"100%", boxSizing:"border-box" }}>
      <div style={{ marginBottom:20 }}>
        <span onClick={() => onNav("alumno_home")} style={{ fontSize: 16, cursor: "pointer", color: theme.text, marginBottom: 6, display: "inline-block" }}>← Inicio</span>
        <div style={{ color:theme.muted, fontSize:12, marginTop:4 }}>
          PLAN NUTRICIONAL{Array.isArray(dieta.dias) && dieta.dias.length > 0 ? ` · ${dieta.dias.join(" Y ").toUpperCase()}` : ""}
        </div>
        <div style={{ fontSize:22, fontWeight:800, color:theme.text }}>{dieta.nombre || "Tu Dieta"} 🥗</div>
      </div>

      {dietas.length > 1 && (
        <div style={{ display:"flex", gap:8, marginBottom:14, flexWrap:"wrap" }}>
          {dietas.map(d => (
            <button key={d.id} onClick={() => setDieta(d)}
              style={{ background: dieta.id === d.id ? theme.accent : theme.surface, border: `1px solid ${dieta.id === d.id ? theme.accent : theme.border}`, borderRadius: 8, padding: "6px 12px", color: dieta.id === d.id ? "#fff" : theme.muted, fontSize: 12, cursor: "pointer", fontWeight: 600 }}>
              {d.nombre || "Plan sin nombre"}
            </button>
          ))}
        </div>
      )}

      {/* Macros */}
      <Card style={{ marginBottom:14, background:"linear-gradient(135deg,#0f172a,#1e293b)", border:`1px solid ${theme.accent}33` }}>
        <div style={{ fontSize:12, color:theme.muted, marginBottom:12 }}>OBJETIVOS DIARIOS</div>
        <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr 1fr", gap:8, textAlign:"center" }}>
          {[
            { label:"Calorías", value:dieta.calorias, unit:"kcal", color:theme.accentLight },
            { label:"Proteína", value:dieta.proteinas, unit:"g", color:"#39FF88" },
            { label:"Carbos", value:dieta.carbos, unit:"g", color:"#B0C4DE" },
            { label:"Grasas", value:dieta.grasas, unit:"g", color:"#FFD166" },
          ].map(m => (
            <div key={m.label}>
              <div style={{ fontSize:18, fontWeight:800, color:m.color, textShadow:`0 0 10px ${m.color}66` }}>{m.value || "—"}</div>
              <div style={{ fontSize:10, color:theme.muted }}>{m.unit}</div>
              <div style={{ fontSize:10, color:theme.muted, marginTop:2 }}>{m.label}</div>
            </div>
          ))}
        </div>
      </Card>

      {/* Comidas con checkboxes */}
      {comidas.map((c, i) => {
        const estado = comidasEstado[i];
        const estados = [
          { key: "completada", icon: "✅", color: theme.success },
          { key: "no_hecha", icon: "❌", color: theme.danger },
          { key: "cambio", icon: "🔄", color: theme.accentLight },
        ];
        return (
          <Card key={i} style={{ marginBottom:10, border: estado ? `1px solid ${getEstadoColor(estado)}55` : `1px solid ${theme.border}`, boxShadow: estado ? `0 0 16px ${getEstadoColor(estado)}22` : "none" }}>
            <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:12 }}>
              <div style={{ width:28, height:28, borderRadius:8, background:theme.accent, display:"flex", alignItems:"center", justifyContent:"center", fontSize:12, fontWeight:800, flexShrink:0, boxShadow:`0 0 10px ${theme.accent}55` }}>{i+1}</div>
              <div style={{ flex:1, minWidth:0 }}>
                <div style={{ fontSize:14, fontWeight:700, color:theme.text }}>{c.nombre}</div>
                {c.hora && <div style={{ fontSize:11, color:theme.muted }}>{c.hora}</div>}
              </div>
            </div>

            {c.alimentos?.map((a, ai) => (
              <div key={ai} style={{ fontSize:13, color:theme.muted, paddingLeft:38, lineHeight:1.8 }}>
                · {a.gramos ? `${a.gramos}${a.unidad === "und" ? " und " : "g "}` : ""}{a.nombre}
              </div>
            ))}

            {/* Botones checkbox solo iconos, simétricos y con brillo futurista */}
            <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr", gap:8, marginTop:12, paddingTop:10, borderTop:`1px solid ${theme.border}` }}>
              {estados.map(e => {
                const activo = estado === e.key;
                return (
                  <button key={e.key} onClick={() => handleComidaEstado(i, e.key)}
                    style={{
                      height:30, borderRadius:9,
                      background: activo ? `linear-gradient(135deg, ${e.color}33, ${e.color}11)` : theme.surface,
                      border: `1.5px solid ${activo ? e.color : theme.border}`,
                      boxShadow: activo ? `0 0 10px ${e.color}55, inset 0 0 6px ${e.color}22` : "none",
                      display:"flex", alignItems:"center", justifyContent:"center",
                      fontSize:14, cursor:"pointer", transition:"all 0.2s",
                      filter: activo ? "none" : "grayscale(0.6) opacity(0.55)",
                    }}>
                    {e.icon}
                  </button>
                );
              })}
            </div>
          </Card>
        );
      })}

      {/* Modal para cambios de comida */}
      {modalCambio && (
        <div style={{ position:"absolute", top:0, left:0, right:0, bottom:0, background:"rgba(5,5,10,0.85)", backdropFilter:"blur(3px)", display:"flex", alignItems:"flex-end", zIndex:1000 }}>
          <div style={{ background:theme.card, borderRadius:"18px 18px 0 0", padding:20, width:"100%", maxHeight:"80vh", overflowY:"auto", border:`1px solid ${theme.accent}44`, borderBottom:"none", boxShadow:`0 -6px 30px ${theme.accent}33`, boxSizing:"border-box" }}>
            <div style={{ width:36, height:4, borderRadius:2, background:theme.border, margin:"0 auto 14px" }} />
            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:14 }}>
              <div style={{ fontSize:16, fontWeight:800, color:theme.text }}>🔄 ¿Qué cambiaste?</div>
              <button onClick={cerrarModalCambio} style={{ background:theme.surface, border:`1px solid ${theme.border}`, borderRadius:"50%", width:30, height:30, fontSize:18, cursor:"pointer", color:theme.muted, display:"flex", alignItems:"center", justifyContent:"center" }}>×</button>
            </div>

            <textarea placeholder="Describe qué cambios hiciste en esta comida..."
              value={modalDescripcion} onChange={e => setModalDescripcion(e.target.value)}
              style={{ background:theme.surface, border:`1px solid ${theme.border}`, borderRadius:10, padding:12, width:"100%", boxSizing:"border-box", color:theme.text, fontSize:14, resize:"none", minHeight:80, outline:"none", marginBottom:14 }} />

            <div style={{ fontSize:11, color:theme.muted, marginBottom:8 }}>Foto de lo que comiste (opcional)</div>
            {modalFotoUrl ? (
              <div style={{ position:"relative", display:"inline-block", marginBottom:14 }}>
                <img src={modalFotoUrl} alt="Foto de la comida" style={{ width:96, height:96, borderRadius:10, objectFit:"cover", border:`1px solid ${theme.border}` }} />
                <button onClick={() => setModalFotoUrl(null)}
                  style={{ position:"absolute", top:-8, right:-8, width:24, height:24, borderRadius:"50%", background:theme.danger, border:`1px solid ${theme.card}`, color:"#fff", fontSize:13, fontWeight:800, cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center" }}>×</button>
              </div>
            ) : (
              <label style={{ display:"flex", alignItems:"center", justifyContent:"center", gap:6, background:theme.surface, border:`1px dashed ${theme.border}`, borderRadius:10, padding:14, color:theme.accentLight, fontSize:13, fontWeight:700, cursor:"pointer", marginBottom:14 }}>
                {modalSubiendoFoto ? "Subiendo..." : "📷 Agregar foto"}
                <input type="file" accept="image/*" style={{ display:"none" }} disabled={modalSubiendoFoto} onChange={e => subirFotoComida(e.target.files[0])} />
              </label>
            )}

            <div style={{ display:"flex", gap:8 }}>
              <button onClick={handleGuardarCambio} disabled={modalSubiendoFoto}
                style={{ flex:1, background:`linear-gradient(135deg, ${theme.accentLight}, ${theme.accent})`, border:"none", borderRadius:10, padding:12, color:"#fff", fontSize:14, fontWeight:700, cursor: modalSubiendoFoto ? "default" : "pointer", opacity: modalSubiendoFoto ? 0.6 : 1, boxShadow:`0 0 14px ${theme.accent}55` }}>
                Guardar
              </button>
              <button onClick={cerrarModalCambio}
                style={{ flex:1, background:theme.surface, border:`1px solid ${theme.border}`, borderRadius:10, padding:12, color:theme.text, fontSize:14, fontWeight:700, cursor:"pointer" }}>
                Cancelar
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Equivalencias */}
      {equivalencias.length > 0 && (
        <Card style={{ marginBottom:12 }}>
          <div style={{ fontSize:12, color:theme.muted, marginBottom:10 }}>EQUIVALENCIAS PERMITIDAS</div>
          {equivalencias.map((e, i) => (
            <div key={i} style={{ display:"flex", alignItems:"center", gap:8, marginBottom:6, fontSize:13 }}>
              <span style={{ color:theme.text }}>{e.a}</span>
              <span style={{ color:theme.accent, fontWeight:700 }}>↔</span>
              <span style={{ color:theme.text }}>{e.b}</span>
            </div>
          ))}
        </Card>
      )}

      {/* Aviso si quedan suplementos de hoy sin marcar */}
      {suplementos.length > 0 && suplementos.some((s, i) => s.nombre && !suplementosEstado[i]) && (
        <Card style={{ marginBottom:14, background:`${theme.warning}12`, border:`1px solid ${theme.warning}44` }}>
          <div style={{ display:"flex", alignItems:"center", gap:8 }}>
            <span style={{ fontSize:18 }}>⏰</span>
            <div style={{ fontSize:12, color:theme.warning, fontWeight:700 }}>Recuerda tomar tu suplementación de hoy — márcala abajo cuando la tomes.</div>
          </div>
        </Card>
      )}

      {/* Suplementos */}
      {suplementos.length > 0 && (
        <Card style={{ marginBottom:14, border:`1px solid ${theme.accent}44`, background:"#0e1420" }}>
          <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:12 }}>
            <span style={{ fontSize:16 }}>💊</span>
            <div style={{ fontSize:12, fontWeight:800, color:theme.accentLight, letterSpacing:0.5 }}>SUPLEMENTACIÓN</div>
          </div>
          {suplementos.map((s, i) => {
            const tomado = !!suplementosEstado[i];
            return (
              <div key={i} onClick={() => toggleSuplementoTomado(i, s.nombre)}
                style={{ display:"flex", alignItems:"center", justifyContent:"space-between", background: tomado ? `${theme.success}14` : theme.surface, border: `1px solid ${tomado ? theme.success + "55" : "transparent"}`, borderRadius:10, padding:"10px 12px", marginBottom:8, cursor:"pointer" }}>
                <div style={{ display:"flex", alignItems:"center", gap:10 }}>
                  <div style={{ width:22, height:22, borderRadius:6, border:`1.5px solid ${tomado ? theme.success : theme.border}`, background: tomado ? theme.success : "transparent", display:"flex", alignItems:"center", justifyContent:"center", fontSize:13, color:"#fff", flexShrink:0 }}>
                    {tomado ? "✓" : ""}
                  </div>
                  <div>
                    <div style={{ fontSize:13, fontWeight:700, color:theme.text }}>{s.nombre}</div>
                    <div style={{ fontSize:11, color:theme.muted }}>{s.momento}</div>
                  </div>
                </div>
                <div style={{ background:`${theme.accent}22`, border:`1px solid ${theme.accent}44`, borderRadius:6, padding:"3px 10px", fontSize:12, fontWeight:700, color:theme.accentLight }}>{s.dosis}</div>
              </div>
            );
          })}
        </Card>
      )}

      {dieta.notas && (
        <Card style={{ marginBottom:14 }}>
          <div style={{ fontSize:12, color:theme.muted, marginBottom:6 }}>📝 NOTAS DEL COACH</div>
          <div style={{ fontSize:13, color:theme.text, lineHeight:1.6 }}>{dieta.notas}</div>
        </Card>
      )}
      <NavBar active="nutricion" onNav={onNav} />
    </div>
  );
}

function DietaCoach({ alumno }) {
  const [dietas, setDietas] = useState([]);
  const [loading, setLoading] = useState(true);
  const [creando, setCreando] = useState(false);
  const [guardando, setGuardando] = useState(false);
  const [exito, setExito] = useState(false);
  const [modoDuplicar, setModoDuplicar] = useState(false);
  const [editandoDietaId, setEditandoDietaId] = useState(null);
  const formRef = useRef(null);

  const [nombrePlan, setNombrePlan] = useState("");
  const [diasDieta, setDiasDieta] = useState([]);
  const [calorias, setCalorias] = useState("");
  const [proteinas, setProteinas] = useState("");
  const [carbos, setCarbos] = useState("");
  const [grasas, setGrasas] = useState("");
  const [notas, setNotas] = useState("");
  const [comidas, setComidas] = useState([
    { nombre: "Desayuno", hora: "07:00", alimentos: [{ nombre: "", gramos: "" }] },
    { nombre: "Almuerzo", hora: "13:00", alimentos: [{ nombre: "", gramos: "" }] },
    { nombre: "Cena", hora: "20:00", alimentos: [{ nombre: "", gramos: "" }] },
  ]);
  const [suplementos, setSuplemento] = useState([{ nombre: "", dosis: "", momento: "" }]);
  const [equivalencias, setEquivalencias] = useState([{ a: "", b: "" }]);
  const [alimentosUsados, setAlimentosUsados] = useState([]);
  const [mapaAlimentos, setMapaAlimentos] = useState({});

  useEffect(() => { cargarDietas(); cargarAlimentosUsados(); }, [alumno]);

  const cargarAlimentosUsados = async () => {
    const { data } = await supabase.from("dietas").select("comidas");
    if (data) {
      const nombres = new Set();
      const mapa = {};
      data.forEach(d => {
        (Array.isArray(d.comidas) ? d.comidas : []).forEach(c => {
          (c.alimentos || []).forEach(a => {
            if (a.nombre) {
              nombres.add(a.nombre);
              if (a.gramos) mapa[a.nombre] = { gramos: a.gramos, unidad: a.unidad || "g" };
            }
          });
        });
      });
      setAlimentosUsados([...nombres].sort());
      setMapaAlimentos(mapa);
    }
  };

  const cargarDietas = async () => {
    if (!alumno?.id) return;
    const { data } = await supabase.from("dietas").select("*").eq("usuario_id", alumno.id).order("created_at", { ascending: false });
    if (data) setDietas(data);
    setLoading(false);
  };

  const agregarComida = () => setComidas([...comidas, { nombre: "Snack", hora: "", alimentos: [{ nombre: "", gramos: "" }] }]);
  const agregarAlimento = (ci) => { const u = [...comidas]; u[ci].alimentos.push({ nombre: "", gramos: "" }); setComidas(u); };
  const eliminarAlimento = (ci, ai) => { const u = [...comidas]; u[ci].alimentos.splice(ai, 1); setComidas(u); };
  const eliminarComida = (ci) => { const u = [...comidas]; u.splice(ci, 1); setComidas(u); };
  const updateComida = (ci, campo, val) => { const u = [...comidas]; u[ci][campo] = val; setComidas(u); };
  const updateAlimento = (ci, ai, campo, val) => {
    const u = [...comidas];
    u[ci].alimentos[ai][campo] = val;
    if (campo === "nombre" && mapaAlimentos[val] && !u[ci].alimentos[ai].gramos) {
      u[ci].alimentos[ai].gramos = mapaAlimentos[val].gramos;
      u[ci].alimentos[ai].unidad = mapaAlimentos[val].unidad;
    }
    setComidas(u);
  };

  const inputStyle = { background:theme.surface, border:`1px solid ${theme.border}`, borderRadius:8, padding:"8px 10px", color:theme.text, fontSize:13, outline:"none", width:"100%", boxSizing:"border-box" };
  const DIAS_SEMANA = ["Lunes","Martes","Miércoles","Jueves","Viernes","Sábado","Domingo"];
  const toggleDiaDieta = (dia) => {
    setDiasDieta(prev => prev.includes(dia) ? prev.filter(d => d !== dia) : [...prev, dia]);
  };

  const guardar = async () => {
    setGuardando(true);
    const datos = {
      nombre: nombrePlan,
      dias: diasDieta,
      calorias: parseInt(calorias) || null,
      proteinas: parseInt(proteinas) || null,
      carbos: parseInt(carbos) || null,
      grasas: parseInt(grasas) || null,
      comidas: comidas.filter(c => c.nombre),
      suplementos: suplementos.filter(s => s.nombre),
      equivalencias: equivalencias.filter(e => e.a && e.b),
      notas,
    };
    if (editandoDietaId) {
      const { error } = await supabase.from("dietas").update(datos).eq("id", editandoDietaId);
      if (error) { alert("Error actualizando dieta: " + error.message); setGuardando(false); return; }
    } else {
      const { error } = await supabase.from("dietas").insert({ usuario_id: alumno.id, ...datos });
      if (error) { alert("Error creando dieta: " + error.message); setGuardando(false); return; }
    }
    setGuardando(false);
    setExito(true);
    setCreando(false);
    setModoDuplicar(false);
    setEditandoDietaId(null);
    cargarDietas();
    cargarAlimentosUsados();
    setTimeout(() => setExito(false), 3000);
  };

  const resetForm = () => {
    setNombrePlan("");
    setDiasDieta([]);
    setCalorias(""); setProteinas(""); setCarbos(""); setGrasas(""); setNotas(NOTAS_DIETA_DEFAULT);
    setComidas([
      { nombre: "Desayuno", hora: "07:00", alimentos: [{ nombre: "", gramos: "" }] },
      { nombre: "Almuerzo", hora: "13:00", alimentos: [{ nombre: "", gramos: "" }] },
      { nombre: "Cena", hora: "20:00", alimentos: [{ nombre: "", gramos: "" }] },
    ]);
    setSuplemento([{ nombre: "", dosis: "", momento: "" }]);
    setEquivalencias([{ a: "", b: "" }]);
  };

  const cargarParaEditar = (dieta, modo) => {
    setNombrePlan(modo === "editar" ? (dieta.nombre || "") : (dieta.nombre ? dieta.nombre + " (copia)" : ""));
    setDiasDieta(Array.isArray(dieta.dias) ? [...dieta.dias] : []);
    setCalorias(dieta.calorias || "");
    setProteinas(dieta.proteinas || "");
    setCarbos(dieta.carbos || "");
    setGrasas(dieta.grasas || "");
    setNotas(dieta.notas || "");
    setComidas(Array.isArray(dieta.comidas) && dieta.comidas.length > 0 ? dieta.comidas : [{ nombre: "Desayuno", hora: "07:00", alimentos: [{ nombre: "", gramos: "" }] }]);
    setSuplemento(Array.isArray(dieta.suplementos) && dieta.suplementos.length > 0 ? dieta.suplementos : [{ nombre: "", dosis: "", momento: "" }]);
    setEquivalencias(Array.isArray(dieta.equivalencias) && dieta.equivalencias.length > 0 ? dieta.equivalencias : [{ a: "", b: "" }]);
    setModoDuplicar(modo === "duplicar");
    setEditandoDietaId(modo === "editar" ? dieta.id : null);
    setCreando(true);
    setTimeout(() => formRef.current?.scrollIntoView({ behavior: "smooth", block: "start" }), 100);
  };

  const empezarNuevaDieta = async () => {
    resetForm();
    setModoDuplicar(false);
    setEditandoDietaId(null);
    // Si este alumno todavía no tiene ninguna dieta, se precarga la última plantilla usada
    // (de cualquier alumno) como punto de partida, para no escribir todo de cero.
    if (dietas.length === 0) {
      const { data } = await supabase.from("dietas").select("*").order("created_at", { ascending: false }).limit(1);
      if (data && data.length > 0) {
        const plantilla = data[0];
        setCalorias(plantilla.calorias || "");
        setProteinas(plantilla.proteinas || "");
        setCarbos(plantilla.carbos || "");
        setGrasas(plantilla.grasas || "");
        setComidas(Array.isArray(plantilla.comidas) && plantilla.comidas.length > 0 ? plantilla.comidas : [{ nombre: "Desayuno", hora: "07:00", alimentos: [{ nombre: "", gramos: "" }] }]);
        setSuplemento(Array.isArray(plantilla.suplementos) && plantilla.suplementos.length > 0 ? plantilla.suplementos : [{ nombre: "", dosis: "", momento: "" }]);
        setEquivalencias(Array.isArray(plantilla.equivalencias) && plantilla.equivalencias.length > 0 ? plantilla.equivalencias : [{ a: "", b: "" }]);
      }
    }
    setCreando(true);
  };

  return (
    <div>
      {exito && (
        <Card style={{ textAlign:"center", padding:16, marginBottom:14, background:`${theme.success}18`, border:`1px solid ${theme.success}44` }}>
          <div style={{ fontSize:13, fontWeight:700, color:theme.success }}>✅ Dieta guardada correctamente</div>
        </Card>
      )}

      {/* Dietas existentes */}
      {!loading && dietas.map(d => (
        <Card key={d.id} style={{ marginBottom:10 }}>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:8 }}>
            <div style={{ fontSize:14, fontWeight:700, color:theme.text }}>🥗 {d.nombre || "Plan Nutricional"}</div>
            <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
              {Array.isArray(d.dias) && d.dias.length > 0
                ? d.dias.map(dia => <Tag key={dia} color={theme.gold}>{dia}</Tag>)
                : <Tag color={theme.muted}>Sin día asignado</Tag>}
              <Tag color={theme.accentLight}>{d.calorias} kcal</Tag>
              <button onClick={() => cargarParaEditar(d, "editar")} style={{ background:`${theme.success}22`, border:`1px solid ${theme.success}44`, borderRadius:6, padding:"4px 8px", color:theme.success, fontSize:11, cursor:"pointer", fontWeight:700 }}>✏️ Editar</button>
              <button onClick={() => cargarParaEditar(d, "duplicar")} style={{ background:`${theme.accent}22`, border:`1px solid ${theme.accent}44`, borderRadius:6, padding:"4px 8px", color:theme.accentLight, fontSize:11, cursor:"pointer", fontWeight:700 }}>⧉ Duplicar</button>
              <button onClick={async () => { if (!confirm(`¿Eliminar el plan "${d.nombre || "sin nombre"}"?`)) return; await supabase.from("dietas").delete().eq("id", d.id); cargarDietas(); }}
                style={{ background:`${theme.danger}22`, border:`1px solid ${theme.danger}44`, borderRadius:6, padding:"4px 8px", color:theme.danger, fontSize:11, cursor:"pointer", fontWeight:700 }}>× Eliminar</button>
            </div>
          </div>
          <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr", gap:6, fontSize:12, color:theme.muted }}>
            <span>Prot: {d.proteinas}g</span>
            <span>Carbos: {d.carbos}g</span>
            <span>Grasas: {d.grasas}g</span>
          </div>
          {Array.isArray(d.comidas) && d.comidas.length > 0 && (
            <div style={{ marginTop:8, fontSize:11, color:theme.muted }}>
              {d.comidas.map((c, i) => <span key={i} style={{ marginRight:8 }}>• {c.nombre}</span>)}
            </div>
          )}
        </Card>
      ))}

      {!creando ? (
        <Btn onClick={empezarNuevaDieta}>+ Crear Plan Nutricional</Btn>
      ) : (
        <div ref={formRef}>
        <Card>
          <div style={{ fontSize:13, fontWeight:800, color:theme.accent, marginBottom:4 }}>
            {editandoDietaId ? "✏️ EDITANDO PLAN" : modoDuplicar ? "⧉ DUPLICANDO PLAN" : "NUEVO PLAN NUTRICIONAL"}
          </div>
          {editandoDietaId && <div style={{ fontSize:11, color:theme.muted, marginBottom:10 }}>Los cambios se guardan sobre este mismo plan.</div>}
          {modoDuplicar && <div style={{ fontSize:11, color:theme.muted, marginBottom:10 }}>Ajustá lo que necesites y guardá como un plan nuevo; el original no se modifica.</div>}

          <div style={{ marginBottom:14 }}>
            <div style={{ fontSize:10, color:theme.muted, marginBottom:3 }}>Nombre del plan (ej: Tren superior - Lunes y Jueves)</div>
            <input style={inputStyle} placeholder="Ej: Días de entreno" value={nombrePlan} onChange={e => setNombrePlan(e.target.value)} />
          </div>

          <div style={{ marginBottom:14 }}>
            <div style={{ fontSize:10, color:theme.muted, marginBottom:6 }}>¿Qué días de la semana se usa este plan? (aparecerá automático esos días en la app del alumno)</div>
            <div style={{ display:"flex", flexWrap:"wrap", gap:6 }}>
              {DIAS_SEMANA.map(dia => {
                const activo = diasDieta.includes(dia);
                return (
                  <button key={dia} type="button" onClick={() => toggleDiaDieta(dia)}
                    style={{
                      background: activo ? theme.accent : theme.surface,
                      border: `1px solid ${activo ? theme.accent : theme.border}`,
                      borderRadius: 8, padding: "6px 10px", color: activo ? "#fff" : theme.muted,
                      fontSize: 12, fontWeight: 700, cursor: "pointer",
                      boxShadow: activo ? `0 0 8px ${theme.accent}55` : "none",
                    }}>
                    {dia.slice(0, 3)}
                  </button>
                );
              })}
            </div>
          </div>

          {/* Macros */}
          <div style={{ fontSize:11, fontWeight:700, color:theme.muted, marginBottom:8 }}>MACROS DIARIOS</div>
          <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8, marginBottom:14 }}>
            {[["Calorías (kcal)", calorias, setCalorias],["Proteínas (g)", proteinas, setProteinas],["Carbohidratos (g)", carbos, setCarbos],["Grasas (g)", grasas, setGrasas]].map(([label, val, set]) => (
              <div key={label}>
                <div style={{ fontSize:10, color:theme.muted, marginBottom:3 }}>{label}</div>
                <input style={inputStyle} type="number" placeholder="0" value={val} onChange={e => set(e.target.value)} />
              </div>
            ))}
          </div>

          {/* Comidas */}
          <div style={{ fontSize:11, fontWeight:700, color:theme.muted, marginBottom:8 }}>COMIDAS</div>
          {comidas.map((c, ci) => (
            <div key={ci} style={{ background:theme.surface, borderRadius:10, padding:12, marginBottom:10 }}>
              <div style={{ display:"flex", gap:8, marginBottom:8, alignItems:"center" }}>
                <input style={{ ...inputStyle, flex:2 }} placeholder="Nombre comida" value={c.nombre} onChange={e => updateComida(ci, "nombre", e.target.value)} />
                <input style={{ ...inputStyle, flex:1 }} placeholder="Hora" value={c.hora} onChange={e => updateComida(ci, "hora", e.target.value)} />
                <button onClick={() => eliminarComida(ci)} style={{ background:`${theme.danger}22`, border:`1px solid ${theme.danger}44`, borderRadius:6, padding:"6px 8px", color:theme.danger, fontSize:12, cursor:"pointer" }}>×</button>
              </div>
              {c.alimentos.map((a, ai) => (
                <div key={ai} style={{ display:"flex", gap:6, marginBottom:6, alignItems:"center" }}>
                  <input style={{ ...inputStyle, flex:3 }} placeholder="Alimento (ej: Pechuga de pollo)" value={a.nombre} onChange={e => updateAlimento(ci, ai, "nombre", e.target.value)} list="lista-alimentos" />
                  <datalist id="lista-alimentos">
                    {alimentosUsados.map(n => <option key={n} value={n} />)}
                  </datalist>
                  <input style={{ ...inputStyle, flex:1, width:55 }} placeholder="Cant." type="number" value={a.gramos} onChange={e => updateAlimento(ci, ai, "gramos", e.target.value)} />
                  <select style={{ ...inputStyle, flex:1, width:70, padding:"8px 4px" }} value={a.unidad || "g"} onChange={e => updateAlimento(ci, ai, "unidad", e.target.value)}>
                    <option value="g">g</option>
                    <option value="und">und</option>
                  </select>
                  {c.alimentos.length > 1 && <button onClick={() => eliminarAlimento(ci, ai)} style={{ background:"transparent", border:"none", color:theme.danger, fontSize:16, cursor:"pointer" }}>×</button>}
                </div>
              ))}
              <button onClick={() => agregarAlimento(ci)} style={{ background:"transparent", border:`1px dashed ${theme.border}`, borderRadius:6, padding:"4px 10px", color:theme.muted, fontSize:11, cursor:"pointer" }}>+ Alimento</button>
            </div>
          ))}
          <button onClick={agregarComida} style={{ background:"transparent", border:`1px dashed ${theme.accent}`, borderRadius:8, padding:"8px", color:theme.accentLight, fontSize:12, cursor:"pointer", width:"100%", marginBottom:14 }}>+ Agregar Comida</button>

          {/* Suplementos */}
          <div style={{ fontSize:11, fontWeight:700, color:theme.muted, marginBottom:8 }}>SUPLEMENTACIÓN</div>
          {suplementos.map((s, i) => (
            <div key={i} style={{ display:"flex", gap:6, marginBottom:6 }}>
              <input style={{ ...inputStyle, flex:2 }} placeholder="Suplemento" value={s.nombre} onChange={e => { const u=[...suplementos]; u[i].nombre=e.target.value; setSuplemento(u); }} />
              <input style={{ ...inputStyle, flex:1 }} placeholder="Dosis" value={s.dosis} onChange={e => { const u=[...suplementos]; u[i].dosis=e.target.value; setSuplemento(u); }} />
              <input style={{ ...inputStyle, flex:2 }} placeholder="Momento" value={s.momento} onChange={e => { const u=[...suplementos]; u[i].momento=e.target.value; setSuplemento(u); }} />
            </div>
          ))}
          <button onClick={() => setSuplemento([...suplementos, { nombre:"", dosis:"", momento:"" }])} style={{ background:"transparent", border:`1px dashed ${theme.border}`, borderRadius:6, padding:"4px 10px", color:theme.muted, fontSize:11, cursor:"pointer", marginBottom:14 }}>+ Suplemento</button>

          {/* Equivalencias */}
          <div style={{ fontSize:11, fontWeight:700, color:theme.muted, marginBottom:8 }}>EQUIVALENCIAS PERMITIDAS</div>
          {equivalencias.map((e, i) => (
            <div key={i} style={{ display:"flex", gap:6, alignItems:"center", marginBottom:6 }}>
              <input style={{ ...inputStyle, flex:1 }} placeholder="Ej: Pollo" value={e.a} onChange={ev => { const u=[...equivalencias]; u[i].a=ev.target.value; setEquivalencias(u); }} />
              <span style={{ color:theme.accent, fontWeight:700 }}>↔</span>
              <input style={{ ...inputStyle, flex:1 }} placeholder="Ej: Pavo" value={e.b} onChange={ev => { const u=[...equivalencias]; u[i].b=ev.target.value; setEquivalencias(u); }} />
            </div>
          ))}
          <button onClick={() => setEquivalencias([...equivalencias, { a:"", b:"" }])} style={{ background:"transparent", border:`1px dashed ${theme.border}`, borderRadius:6, padding:"4px 10px", color:theme.muted, fontSize:11, cursor:"pointer", marginBottom:14 }}>+ Equivalencia</button>

          {/* Notas */}
          <div style={{ fontSize:11, fontWeight:700, color:theme.muted, marginBottom:6 }}>NOTAS PARA EL ALUMNO</div>
          <textarea style={{ ...inputStyle, minHeight:60, resize:"none", marginBottom:14 }} placeholder="Indicaciones generales..." value={notas} onChange={e => setNotas(e.target.value)} />

          <div style={{ display:"flex", gap:8 }}>
            <Btn onClick={guardar} style={{ background:theme.success }}>{guardando ? "Guardando..." : editandoDietaId ? "✓ Guardar Cambios" : "✓ Guardar Dieta"}</Btn>
            <Btn variant="ghost" onClick={() => { setCreando(false); setModoDuplicar(false); setEditandoDietaId(null); }}>Cancelar</Btn>
          </div>
        </Card>
        </div>
      )}
    </div>
  );
}
function DiarioScreen({ onNav }) {
  const [energia, setEnergia] = useState(7);
  const [sueno, setSueno] = useState(7);
  const [horas, setHoras] = useState("8");
  const [guardado, setGuardado] = useState(false);
  const [loading, setLoading] = useState(true);
  const [dias, setDias] = useState([]);
  const [userId, setUserId] = useState(null);

  const diasNombre = ["Dom","Lun","Mar","Mié","Jue","Vie","Sáb"];

  const cargar = async () => {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) { setLoading(false); return; }
    setUserId(user.id);

    const hoy = fechaOperativa();
    const hace6 = new Date(hoy); hace6.setDate(hoy.getDate() - 29);
    const fechaDesde = aFechaStr(hace6);

    const { data: registros } = await supabase
      .from("diario_registros")
      .select("*")
      .eq("usuario_id", user.id)
      .gte("fecha", fechaDesde)
      .order("fecha", { ascending: true });

    const { data: entrenos } = await supabase
      .from("registros_entreno")
      .select("fecha")
      .eq("usuario_id", user.id)
      .gte("fecha", fechaDesde);
    const fechasEntreno = new Set((entrenos || []).map(e => e.fecha));

    const { data: pasosRegs } = await supabase
      .from("pasos_registros")
      .select("fecha, pasos")
      .eq("usuario_id", user.id)
      .gte("fecha", fechaDesde);
    const mapaPasos = {};
    (pasosRegs || []).forEach(p => { mapaPasos[p.fecha] = p.pasos; });

    const arr = [];
    for (let i = 29; i >= 0; i--) {
      const d = new Date(hoy);
      d.setDate(hoy.getDate() - i);
      const fechaStr = aFechaStr(d);
      const esHoy = i === 0;
      const reg = (registros || []).find(r => r.fecha === fechaStr);
      arr.push({
        dia: esHoy ? "Hoy" : diasNombre[d.getDay()],
        fecha: d.toLocaleDateString("es-CL", { day: "numeric", month: "short" }),
        fechaStr,
        energia: reg?.energia ?? null,
        sueno: reg?.sueno ?? null,
        horas: reg?.horas ?? null,
        entreno: fechasEntreno.has(fechaStr),
        pasos: mapaPasos[fechaStr] ?? null,
      });
    }
    setDias(arr);

    const regHoy = (registros || []).find(r => r.fecha === aFechaStr(hoy));
    if (regHoy) {
      setEnergia(regHoy.energia || 7);
      setSueno(regHoy.sueno || 7);
      setHoras(regHoy.horas ? String(regHoy.horas) : "8");
      setGuardado(true);
    } else {
      setGuardado(false);
    }
    setLoading(false);
  };

  useEffect(() => { cargar(); }, []);

  const guardarHoy = async () => {
    if (!userId) return;
    const hoyStr = fechaOperativaStr();
    const { error } = await supabase.from("diario_registros").upsert({
      usuario_id: userId,
      fecha: hoyStr,
      energia,
      sueno,
      horas: parseFloat(horas) || null,
    }, { onConflict: "usuario_id,fecha" });
    if (error) { alert("Error guardando: " + error.message); return; }
    setGuardado(true);
    cargar();
  };

  const conDatos = dias.filter(d => d.energia !== null);
  const promedioEnergia = conDatos.length > 0 ? (conDatos.reduce((a,b) => a + b.energia, 0) / conDatos.length).toFixed(1) : "—";
  const promedioSueno = conDatos.length > 0 ? (conDatos.reduce((a,b) => a + b.sueno, 0) / conDatos.length).toFixed(1) : "—";
  const promedioHoras = conDatos.length > 0 ? (conDatos.reduce((a,b) => a + parseFloat(b.horas || 0), 0) / conDatos.length).toFixed(1) : "—";

  const diaAlerta = dias.find(d => d.energia !== null && d.energia <= 5 && d.sueno !== null && d.sueno <= 5 && !d.entreno);

  if (loading) return (
    <div style={{ padding: "20px 16px 90px", height: "100%", boxSizing: "border-box", display: "flex", alignItems: "center", justifyContent: "center" }}>
      <div style={{ color: theme.muted }}>Cargando...</div>
    </div>
  );

  return (
    <div style={{ padding: "20px 16px 90px", overflowY: "auto", height: "100%", boxSizing: "border-box" }}>
      <div style={{ marginBottom: 20 }}>
        <span onClick={() => onNav("alumno_home")} style={{ fontSize: 16, cursor: "pointer", color: theme.text, marginBottom: 6, display: "inline-block" }}>← Inicio</span>
        <div style={{ color: theme.muted, fontSize: 12, marginTop: 4 }}>REGISTRO DIARIO</div>
        <div style={{ fontSize: 22, fontWeight: 800, color: theme.text }}>Sueño y Energía 🌙</div>
      </div>

      {/* Promedios semanales */}
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 10, marginBottom: 16 }}>
        {[
          { label: "Energía prom.", value: promedioEnergia, unit: "/10", color: theme.accent, icon: "⚡" },
          { label: "Calidad sueño", value: promedioSueno, unit: "/10", color: "#A78BFA", icon: "😴" },
          { label: "Horas prom.", value: promedioHoras, unit: "hrs", color: theme.success, icon: "🕐" },
        ].map(s => (
          <Card key={s.label} style={{ padding: 12, textAlign: "center" }}>
            <div style={{ fontSize: 16 }}>{s.icon}</div>
            <div style={{ fontSize: 20, fontWeight: 900, color: s.color, marginTop: 4 }}>{s.value}</div>
            <div style={{ fontSize: 10, color: s.color, marginBottom: 2 }}>{s.unit}</div>
            <div style={{ fontSize: 9, color: theme.muted }}>{s.label}</div>
          </Card>
        ))}
      </div>

      {/* Historial semanal */}
      <Card style={{ marginBottom: 14 }}>
        <div style={{ fontSize: 12, color: theme.muted, marginBottom: 12 }}>ÚLTIMOS 30 DÍAS</div>
        {dias.slice().reverse().map((d, i) => (
          <div key={i} style={{
            display: "grid", gridTemplateColumns: "32px 1fr 1fr 1fr 30px",
            gap: 6, alignItems: "center", marginBottom: 10,
            background: d.dia === "Hoy" ? `${theme.accent}15` : theme.surface,
            border: `1px solid ${d.dia === "Hoy" ? theme.accent+"44" : theme.border}`,
            borderRadius: 10, padding: "8px 6px"
          }}>
            <div style={{ textAlign: "center" }}>
              <div style={{ fontSize: 10, fontWeight: 800, color: d.dia === "Hoy" ? theme.accent : theme.text }}>{d.dia}</div>
              <div style={{ fontSize: 8, color: theme.muted }}>{d.fecha}</div>
            </div>
            {d.energia !== null ? (
              <>
                <div style={{ textAlign: "center" }}>
                  <div style={{ fontSize: 9, color: theme.muted, marginBottom: 2 }}>⚡ Energía</div>
                  <div style={{ background: theme.card, borderRadius: 6, height: 6, overflow: "hidden" }}>
                    <div style={{ width: `${d.energia * 10}%`, height: "100%", background: d.energia >= 7 ? theme.success : d.energia >= 5 ? theme.warning : theme.danger, borderRadius: 6 }} />
                  </div>
                  <div style={{ fontSize: 9, fontWeight: 700, color: theme.text, marginTop: 2 }}>{d.energia}/10</div>
                </div>
                <div style={{ textAlign: "center" }}>
                  <div style={{ fontSize: 9, color: theme.muted, marginBottom: 2 }}>😴 Sueño</div>
                  <div style={{ background: theme.card, borderRadius: 6, height: 6, overflow: "hidden" }}>
                    <div style={{ width: `${d.sueno * 10}%`, height: "100%", background: d.sueno >= 7 ? "#A78BFA" : d.sueno >= 5 ? theme.warning : theme.danger, borderRadius: 6 }} />
                  </div>
                  <div style={{ fontSize: 9, fontWeight: 700, color: theme.text, marginTop: 2 }}>{d.horas || "—"}h · {d.sueno}/10</div>
                </div>
              </>
            ) : (
              <div style={{ gridColumn: "2/4", fontSize: 11, color: theme.muted }}>Sin registro{d.dia === "Hoy" ? " — anótalo ↓" : ""}</div>
            )}
            <div style={{ textAlign: "center" }}>
              <div style={{ fontSize: 9, color: theme.muted, marginBottom: 2 }}>🚶 Pasos</div>
              <div style={{ fontSize: 9, fontWeight: 700, color: d.pasos ? theme.text : theme.muted, marginTop: 8 }}>{d.pasos ? d.pasos.toLocaleString("es-CL") : "—"}</div>
            </div>
            <div style={{ textAlign: "center" }}>
              {d.entreno
                ? <div title="Entrenó" style={{ width: 22, height: 22, margin: "0 auto", borderRadius: "50%", background: `${theme.success}22`, border: `1px solid ${theme.success}44`, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 11 }}>💪</div>
                : <div title="Descanso" style={{ width: 22, height: 22, margin: "0 auto", borderRadius: "50%", background: `${theme.muted}15`, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 10, color: theme.muted }}>–</div>
              }
            </div>
          </div>
        ))}
      </Card>

      {/* Alerta correlación (solo si hay un día real que la justifique) */}
      {diaAlerta && (
        <Card style={{ marginBottom: 14, background: `${theme.danger}12`, border: `1px solid ${theme.danger}33` }}>
          <div style={{ display: "flex", gap: 10, alignItems: "flex-start" }}>
            <span style={{ fontSize: 18 }}>⚠️</span>
            <div>
              <div style={{ fontSize: 12, fontWeight: 800, color: theme.danger, marginBottom: 3 }}>Alerta de rendimiento</div>
              <div style={{ fontSize: 12, color: theme.muted, lineHeight: 1.5 }}>
                El {diaAlerta.dia} dormiste {diaAlerta.horas || "pocas"}h y tu energía fue {diaAlerta.energia}/10 — ese día no entrenaste. Tu coach puede ver este patrón.
              </div>
            </div>
          </div>
        </Card>
      )}

      {/* Registro de hoy */}
      {!guardado ? (
        <Card style={{ border: `1px solid ${theme.accent}44` }}>
          <div style={{ fontSize: 12, fontWeight: 800, color: theme.accent, marginBottom: 14 }}>📝 REGISTRA HOY</div>

          <div style={{ marginBottom: 14 }}>
            <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 6 }}>
              <span style={{ fontSize: 13, color: theme.text }}>⚡ Energía del día</span>
              <span style={{ fontSize: 13, fontWeight: 700, color: theme.accent }}>{energia}/10</span>
            </div>
            <input type="range" min={1} max={10} value={energia} onChange={e => setEnergia(Number(e.target.value))} style={{ width: "100%", accentColor: theme.accent }} />
          </div>

          <div style={{ marginBottom: 14 }}>
            <div style={{ fontSize: 13, color: theme.text, marginBottom: 8 }}>😴 Horas dormidas anoche</div>
            <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
              <input value={horas} onChange={e => setHoras(e.target.value)} placeholder="0" type="number" step="0.5"
                style={{ background: theme.surface, border: `2px solid #A78BFA`, borderRadius: 10, padding: "10px 14px", color: theme.text, fontSize: 20, fontWeight: 800, width: 80, textAlign: "center", outline: "none" }} />
              <span style={{ fontSize: 14, color: theme.muted }}>horas</span>
            </div>
          </div>

          <div style={{ marginBottom: 16 }}>
            <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 6 }}>
              <span style={{ fontSize: 13, color: theme.text }}>😴 Calidad del sueño</span>
              <span style={{ fontSize: 13, fontWeight: 700, color: "#A78BFA" }}>{sueno}/10</span>
            </div>
            <input type="range" min={1} max={10} value={sueno} onChange={e => setSueno(Number(e.target.value))} style={{ width: "100%", accentColor: "#A78BFA" }} />
          </div>

          <button onClick={guardarHoy} style={{ background: theme.accent, border: "none", borderRadius: 10, padding: "12px", color: "#fff", fontWeight: 700, fontSize: 14, cursor: "pointer", width: "100%" }}>
            Guardar registro de hoy
          </button>
        </Card>
      ) : (
        <Card style={{ textAlign: "center", padding: 24, background: `${theme.success}15`, border: `1px solid ${theme.success}44` }}>
          <div style={{ fontSize: 36, marginBottom: 8 }}>✅</div>
          <div style={{ fontSize: 15, fontWeight: 800, color: theme.success }}>¡Registro guardado!</div>
          <div style={{ fontSize: 12, color: theme.muted, marginTop: 4 }}>Tu coach puede ver tu progreso diario</div>
          <button onClick={() => setGuardado(false)} style={{ background: "transparent", border: `1px solid ${theme.border}`, borderRadius: 8, padding: "8px 16px", color: theme.muted, fontSize: 12, cursor: "pointer", marginTop: 12 }}>Editar</button>
        </Card>
      )}
      <NavBar active="diario" onNav={onNav} />
    </div>
  );
}

function CheckinScreen({ onNav }) {
  const [lightbox, setLightbox] = useState(null);
  const [peso, setPeso] = useState("");
  const [porcGrasa, setPorcGrasa] = useState("");
  const [cintura, setCintura] = useState("");
  const [brazo, setBrazo] = useState("");
  const [pecho, setPecho] = useState("");
  const [pierna, setPierna] = useState("");
  const [cadera, setCadera] = useState("");
  const [comentarios, setComentarios] = useState("");
  const [enviado, setEnviado] = useState(false);
  const [guardando, setGuardando] = useState(false);
  const [checkins, setCheckins] = useState([]);
  const [fotos, setFotos] = useState({ frente: null, espalda: null, perfDer: null, perfIzq: null });
  const [fotosPreview, setFotosPreview] = useState({ frente: null, espalda: null, perfDer: null, perfIzq: null });

  useEffect(() => {
    const cargar = async () => {
      const { data: { user } } = await supabase.auth.getUser();
      if (user) {
        const { data } = await supabase
          .from("checkins")
          .select("*")
          .eq("usuario_id", user.id)
          .order("fecha", { ascending: false })
          .limit(4);
        if (data) setCheckins(data);
      }
    };
    cargar();
  }, [enviado]);

  const comprimirFoto = (file) => {
    return new Promise((resolve) => {
      const canvas = document.createElement("canvas");
      const ctx = canvas.getContext("2d");
      const img = new Image();
      img.onload = () => {
        const MAX = 800;
        let w = img.width, h = img.height;
        if (w > h && w > MAX) { h = h * MAX / w; w = MAX; }
        else if (h > MAX) { w = w * MAX / h; h = MAX; }
        canvas.width = w; canvas.height = h;
        ctx.drawImage(img, 0, 0, w, h);
        canvas.toBlob(resolve, "image/jpeg", 0.7);
      };
      img.src = URL.createObjectURL(file);
    });
  };

  const handleFoto = async (key, file) => {
    if (!file) return;
    const preview = URL.createObjectURL(file);
    setFotosPreview(prev => ({ ...prev, [key]: preview }));
    const compressed = await comprimirFoto(file);
    setFotos(prev => ({ ...prev, [key]: compressed }));
  };

  const subirFoto = async (userId, key, blob) => {
    if (!blob) return null;
    const fecha = fechaOperativaStr();
    const path = `${userId}/${fecha}/${key}.jpg`;
    const { error } = await supabase.storage
      .from("fotos-alumnos")
      .upload(path, blob, { contentType: "image/jpeg", upsert: true });
    if (error) return null;
    const publicUrl = `https://srlucwsakjuivogvunzx.supabase.co/storage/v1/object/public/fotos-alumnos/${path}`;
    return publicUrl;
  };

  const enviarCheckin = async () => {
    setGuardando(true);
    const { data: { user } } = await supabase.auth.getUser();
    if (user) {
      const urlFrente = fotos.frente ? await subirFoto(user.id, "frente", fotos.frente) : null;
      const urlEspalda = fotos.espalda ? await subirFoto(user.id, "espalda", fotos.espalda) : null;
      const urlPerfDer = fotos.perfDer ? await subirFoto(user.id, "perfDer", fotos.perfDer) : null;
      const urlPerfIzq = fotos.perfIzq ? await subirFoto(user.id, "perfIzq", fotos.perfIzq) : null;

      await supabase.from("checkins").insert({
        usuario_id: user.id,
        peso: parseFloat(peso) || null,
        porc_grasa: parseFloat(porcGrasa) || null,
        cintura: parseFloat(cintura) || null,
        brazo: parseFloat(brazo) || null,
        pecho: parseFloat(pecho) || null,
        pierna: parseFloat(pierna) || null,
        cadera: parseFloat(cadera) || null,
        comentarios,
        foto_frente: urlFrente,
        foto_espalda: urlEspalda,
        foto_perf_der: urlPerfDer,
        foto_perf_izq: urlPerfIzq,
      });
    }
    setGuardando(false);
    setEnviado(true);
  };

  return (
    <div style={{ padding: "20px 16px 90px", overflowY: "auto", height: "100%", boxSizing: "border-box" }}>
      <div style={{ marginBottom: 20 }}>
        <span onClick={() => onNav("alumno_home")} style={{ fontSize: 16, cursor: "pointer", color: theme.text, marginBottom: 6, display: "inline-block" }}>← Inicio</span>
        <div style={{ color: theme.muted, fontSize: 12, marginTop: 4 }}>SEGUIMIENTO CADA 4 SEMANAS</div>
        <div style={{ fontSize: 22, fontWeight: 800, color: theme.text }}>Check-In 📊</div>
      </div>

      {checkins.length > 0 && (
        <Card style={{ marginBottom: 14 }}>
          <div style={{ fontSize: 12, color: theme.muted, marginBottom: 10 }}>HISTORIAL RECIENTE</div>
          <div style={{ display: "flex", gap: 8, overflowX: "auto" }}>
            {checkins.map((c, i) => (
              <div key={i} style={{ background: theme.surface, borderRadius: 10, padding: "10px 12px", flexShrink: 0, textAlign: "center", minWidth: 80 }}>
                <div style={{ fontSize: 10, color: theme.muted, marginBottom: 4 }}>{c.fecha}</div>
                <div style={{ fontSize: 16, fontWeight: 800, color: theme.text }}>{c.peso}kg</div>
                {c.porc_grasa && <div style={{ fontSize: 11, color: "#B0C4DE" }}>{c.porc_grasa}% grasa</div>}
              </div>
            ))}
          </div>
        </Card>
      )}

      {!enviado ? (
        <>
          {/* Peso + % Grasa */}
          <Card style={{ marginBottom: 14 }}>
            <div style={{ fontSize: 12, color: theme.muted, marginBottom: 10 }}>PESO Y COMPOSICIÓN CORPORAL</div>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
              <div>
                <div style={{ fontSize: 11, color: theme.muted, marginBottom: 4 }}>Peso</div>
                <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                  <input value={peso} onChange={e => setPeso(e.target.value)} placeholder="0.0" type="number" step="0.1"
                    style={{ background: theme.surface, border: `2px solid ${theme.accent}`, borderRadius: 10, padding: "10px 8px", color: theme.text, fontSize: 20, fontWeight: 800, width: "100%", textAlign: "center", outline: "none", boxSizing: "border-box" }} />
                  <span style={{ fontSize: 13, color: theme.muted }}>kg</span>
                </div>
              </div>
              <div>
                <div style={{ fontSize: 11, color: theme.muted, marginBottom: 4 }}>% Grasa (aprox)</div>
                <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                  <input value={porcGrasa} onChange={e => setPorcGrasa(e.target.value)} placeholder="~20" type="number" step="0.5"
                    style={{ background: theme.surface, border: "2px solid #B0C4DE", borderRadius: 10, padding: "10px 8px", color: theme.text, fontSize: 20, fontWeight: 800, width: "100%", textAlign: "center", outline: "none", boxSizing: "border-box" }} />
                  <span style={{ fontSize: 13, color: theme.muted }}>%</span>
                </div>
              </div>
            </div>
            <div style={{ marginTop: 12, background: theme.surface, borderRadius: 10, padding: 10 }}>
              <div style={{ fontSize: 11, color: "#B0C4DE", fontWeight: 700, marginBottom: 6 }}>📊 Referencia % grasa corporal</div>
              <div style={{ fontSize: 10, color: theme.muted, marginBottom: 6 }}>Compárate con la imagen y estima tu porcentaje</div>
              <img src={GRASA_IMG} alt="Referencia % grasa" onClick={() => setLightbox(GRASA_IMG)} style={{ width: "100%", borderRadius: 6, cursor: "pointer", display: "block" }} />
            </div>
          </Card>

          {/* Medidas */}
          <Card style={{ marginBottom: 14 }}>
            <div style={{ fontSize: 12, color: theme.muted, marginBottom: 10 }}>MEDIDAS (cm)</div>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
              {[
                ["Cintura", cintura, setCintura],
                ["Brazo (contracción)", brazo, setBrazo],
                ["Pecho", pecho, setPecho],
                ["Pierna", pierna, setPierna],
                ["Cadera/Glúteos", cadera, setCadera],
              ].map(([label, val, set]) => (
                <div key={label}>
                  <div style={{ fontSize: 11, color: theme.muted, marginBottom: 4 }}>{label}</div>
                  <input value={val} onChange={e => set(e.target.value)} placeholder="0" type="number"
                    style={{ background: theme.surface, border: `1px solid ${theme.border}`, borderRadius: 8, padding: "8px 12px", color: theme.text, fontSize: 15, width: "100%", textAlign: "center", outline: "none", boxSizing: "border-box" }} />
                </div>
              ))}
            </div>
          </Card>

          {/* Fotos */}
          <Card style={{ marginBottom: 14 }}>
            <div style={{ fontSize: 12, color: theme.muted, marginBottom: 6 }}>📸 FOTOS CORPORALES</div>
            <div style={{ fontSize: 11, color: theme.muted, marginBottom: 10 }}>Se comprimen automáticamente · Haz clic para ver en grande</div>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
              {[
                { key: "frente", label: "Frente", emoji: "👤" },
                { key: "espalda", label: "Espalda", emoji: "🔙" },
                { key: "perfDer", label: "Perfil Der.", emoji: "➡️" },
                { key: "perfIzq", label: "Perfil Izq.", emoji: "⬅️" },
              ].map(f => (
                <label key={f.key} style={{
                  border: `1px dashed ${fotosPreview[f.key] ? theme.success : theme.border}`,
                  borderRadius: 10, height: 90, display: "flex", flexDirection: "column",
                  alignItems: "center", justifyContent: "center", cursor: "pointer", overflow: "hidden"
                }}>
                  {fotosPreview[f.key] ? (
                    <img src={fotosPreview[f.key]} alt={f.label} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                  ) : (
                    <>
                      <span style={{ fontSize: 24 }}>{f.emoji}</span>
                      <span style={{ fontSize: 10, color: theme.muted, marginTop: 4 }}>{f.label}</span>
                    </>
                  )}
                  <input type="file" accept="image/*" style={{ display: "none" }}
                    onChange={e => handleFoto(f.key, e.target.files[0])} />
                </label>
              ))}
            </div>
          </Card>

          {/* Comentarios */}
          <Card style={{ marginBottom: 14 }}>
            <div style={{ fontSize: 12, color: theme.muted, marginBottom: 6 }}>Comentarios de las últimas 4 semanas</div>
            <textarea value={comentarios} onChange={e => setComentarios(e.target.value)}
              placeholder="¿Cómo fueron tus últimas 4 semanas? Avances, dudas, sensaciones, cómo te sentiste..."
              style={{ background: theme.surface, border: `1px solid ${theme.border}`, borderRadius: 8, padding: "10px 12px", color: theme.text, fontSize: 13, width: "100%", minHeight: 80, resize: "none", outline: "none", boxSizing: "border-box" }} />
          </Card>

          <Btn onClick={enviarCheckin} style={{ fontSize: 15, fontWeight: 800, padding: 16 }}>
            {guardando ? "Subiendo fotos..." : "Enviar Check-In →"}
          </Btn>
        </>
      ) : (
        <Card style={{ textAlign: "center", padding: 32 }}>
          <div style={{ fontSize: 48, marginBottom: 12 }}>✅</div>
          <div style={{ fontSize: 18, fontWeight: 800, color: theme.text, marginBottom: 6 }}>¡Check-In enviado!</div>
          <div style={{ fontSize: 13, color: theme.muted }}>Tu coach revisará tu progreso pronto.</div>
          <Btn onClick={() => {
            setEnviado(false); setPeso(""); setPorcGrasa(""); setCintura(""); setBrazo("");
            setPecho(""); setPierna(""); setCadera(""); setComentarios("");
            setFotos({ frente: null, espalda: null, perfDer: null, perfIzq: null });
            setFotosPreview({ frente: null, espalda: null, perfDer: null, perfIzq: null });
          }} style={{ marginTop: 20 }} variant="ghost">Nuevo check-in</Btn>
        </Card>
      )}
      <NavBar active="checkin" onNav={onNav} />
      <ImageLightbox src={lightbox} onClose={() => setLightbox(null)} />
    </div>
  );
}

function MensajesScreen({ onNav }) {
  const [mensajes, setMensajes] = useState([]);
  const [texto, setTexto] = useState("");
  const [loading, setLoading] = useState(true);
  const [userId, setUserId] = useState(null);

  useEffect(() => {
    const init = async () => {
      const { data: { user } } = await supabase.auth.getUser();
      if (user) {
        setUserId(user.id);
        await cargarMensajes(user.id);
        // Marcar como leídos los mensajes del coach
        // mensajes marcados como leidos al abrir el chat
      }
      setLoading(false);
    };
    init();

    // Realtime — escucha nuevos mensajes
    const channel = supabase.channel("mensajes-alumno")
      .on("postgres_changes", { event: "INSERT", schema: "public", table: "mensajes" }, () => {
        supabase.auth.getUser().then(({ data: { user } }) => {
          if (user) cargarMensajes(user.id);
        });
      })
      .subscribe();

    return () => supabase.removeChannel(channel);
  }, []);

  const cargarMensajes = async (uid) => {
    const { data } = await supabase
      .from("mensajes")
      .select("*")
      .eq("usuario_id", uid)
      .order("created_at", { ascending: true });
    if (data) setMensajes(data);
  };

  const enviar = async () => {
    if (!texto.trim() || !userId) return;
    await supabase.from("mensajes").insert({
      usuario_id: userId,
      de: "alumno",
      texto: texto.trim(),
      leido: false,
    });
    setTexto("");
  };

  return (
    <div style={{ height: "100%", display: "flex", flexDirection: "column" }}>
      <div style={{ padding: "16px 16px 12px", background: theme.surface, borderBottom: `1px solid ${theme.border}`, display: "flex", alignItems: "center", gap: 10 }}>
        <span onClick={() => onNav("alumno_home")} style={{ fontSize: 20, cursor: "pointer", color: theme.text }}>←</span>
        <div>
          <div style={{ color: theme.muted, fontSize: 12 }}>COMUNICACIÓN</div>
          <div style={{ fontSize: 20, fontWeight: 800, color: theme.text }}>Mensajes 💬</div>
        </div>
      </div>
      <div style={{ flex: 1, overflowY: "auto", padding: "12px 16px" }}>
        {loading ? (
          <div style={{ textAlign: "center", color: theme.muted, marginTop: 40 }}>Cargando...</div>
        ) : mensajes.length === 0 ? (
          <div style={{ textAlign: "center", padding: 40 }}>
            <div style={{ fontSize: 32, marginBottom: 12 }}>💬</div>
            <div style={{ fontSize: 14, fontWeight: 700, color: theme.text, marginBottom: 6 }}>Sin mensajes aún</div>
            <div style={{ fontSize: 12, color: theme.muted }}>Escribe un mensaje a tu coach</div>
          </div>
        ) : (
          mensajes.map((m, i) => (
            <div key={i} style={{ display: "flex", justifyContent: m.de === "coach" ? "flex-start" : "flex-end", marginBottom: 10 }}>
              {m.de === "coach" && (
                <div style={{ width: 28, height: 28, borderRadius: 14, background: theme.accent, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 12, fontWeight: 800, marginRight: 8, flexShrink: 0 }}>C</div>
              )}
              <div style={{ background: m.de === "coach" ? theme.card : theme.accent, border: `1px solid ${m.de === "coach" ? theme.border : theme.accent}`, borderRadius: 12, padding: "10px 14px", maxWidth: "75%" }}>
                <div style={{ fontSize: 13, color: theme.text, lineHeight: 1.5 }}>{m.texto}</div>
                <div style={{ fontSize: 10, color: m.de === "coach" ? theme.muted : "rgba(255,255,255,0.6)", marginTop: 4 }}>
                  {new Date(m.created_at).toLocaleDateString("es-CL", { day: "numeric", month: "short", hour: "2-digit", minute: "2-digit" })}
                </div>
              </div>
            </div>
          ))
        )}
      </div>
      <div style={{ padding: "10px 16px 12px", background: theme.surface, borderTop: `1px solid ${theme.border}`, display: "flex", gap: 8 }}>
        <input value={texto} onChange={e => setTexto(e.target.value)} onKeyDown={e => e.key === "Enter" && enviar()}
          placeholder="Escribe un mensaje..."
          style={{ flex: 1, background: theme.card, border: `1px solid ${theme.border}`, borderRadius: 10, padding: "10px 14px", color: theme.text, fontSize: 13, outline: "none" }} />
        <button onClick={enviar} style={{ background: theme.accent, border: "none", borderRadius: 10, padding: "10px 16px", color: "#fff", fontWeight: 700, fontSize: 14, cursor: "pointer" }}>→</button>
      </div>
    </div>
  );
}
function ProgresoScreen({ onNav }) {
  const [loading, setLoading] = useState(true);
  const [checkins, setCheckins] = useState([]);
  const [fotoAntes, setFotoAntes] = useState(null);
  const [fotoActual, setFotoActual] = useState(null);
  const [prs, setPrs] = useState([]);
  const [lightbox, setLightbox] = useState(null);
  const [userId, setUserId] = useState(null);
  const [ciclosResumen, setCiclosResumen] = useState([]);
  const [entrenosResumen, setEntrenosResumen] = useState([]);
  const [dietaRegsResumen, setDietaRegsResumen] = useState([]);
  const [diasPlanificadosResumen, setDiasPlanificadosResumen] = useState(0);
  const [semanaExpandidaResumen, setSemanaExpandidaResumen] = useState(null);
  const [diaExpandidoResumen, setDiaExpandidoResumen] = useState(null);
  const [pasosResumen, setPasosResumen] = useState([]);
  const [anillos30, setAnillos30] = useState(null);

  useEffect(() => {
    const cargar = async () => {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) { setLoading(false); return; }
      setUserId(user.id);

      // Peso corporal: historial real de check-ins
      const { data: checkinsData } = await supabase
        .from("checkins")
        .select("peso, fecha, foto_frente, porc_grasa, cintura, cadera, brazo, pecho, pierna")
        .eq("usuario_id", user.id)
        .order("fecha", { ascending: true });
      if (checkinsData) setCheckins(checkinsData.filter(c => c.peso));

      // Pasos: historial de los últimos 30 días para el gráfico de tendencia
      const hoyPasos = fechaOperativa();
      const desdePasos = new Date(hoyPasos); desdePasos.setDate(hoyPasos.getDate() - 29);
      const { data: pasosData } = await supabase
        .from("pasos_registros")
        .select("fecha, pasos")
        .eq("usuario_id", user.id)
        .gte("fecha", aFechaStr(desdePasos))
        .order("fecha", { ascending: true });
      if (pasosData) setPasosResumen(pasosData.filter(p => p.pasos != null));

      // Cumplimiento de los últimos 30 días: Entreno / Nutrición / Diario.
      const hoyOp30 = fechaOperativa();
      const hace30Str = aFechaStr((() => { const d = new Date(hoyOp30); d.setDate(d.getDate() - 29); return d; })());
      const [rutinasRes, entRes, diaRes, dieRes] = await Promise.all([
        supabase.from("rutinas").select("dia").eq("usuario_id", user.id),
        supabase.from("registros_entreno").select("fecha").eq("usuario_id", user.id).gte("fecha", hace30Str),
        supabase.from("diario_registros").select("fecha").eq("usuario_id", user.id).gte("fecha", hace30Str),
        supabase.from("dieta_registros").select("fecha, estado").eq("usuario_id", user.id).gte("fecha", hace30Str),
      ]);
      const entreno30 = new Set((entRes.data || []).map(r => r.fecha)).size;
      const diario30 = new Set((diaRes.data || []).map(r => r.fecha)).size;
      const dieta30 = dieRes.data || [];
      const nutriPct = dieta30.length > 0 ? Math.round((dieta30.filter(r => r.estado === "completada").length / dieta30.length) * 100) : null;
      const diasPorSemana = new Set((rutinasRes.data || []).map(r => r.dia)).size;
      const planEntreno30 = diasPorSemana > 0 ? Math.round(diasPorSemana * 30 / 7) : 0;
      const entrenoPct = planEntreno30 > 0 ? Math.min(100, Math.round((entreno30 / planEntreno30) * 100)) : null;
      const diarioPct = Math.round((diario30 / 30) * 100);
      setAnillos30({ entrenoPct, nutriPct, diarioPct });

      // Foto "antes": la de la Anamnesis. Foto "actual": el check-in más reciente con foto.
      const { data: usr } = await supabase.from("usuarios").select("foto_frente, fecha_inicio_plan").eq("id", user.id).single();
      if (usr?.foto_frente) setFotoAntes(usr.foto_frente);
      if (checkinsData) {
        const conFoto = checkinsData.filter(c => c.foto_frente);
        if (conFoto.length > 0) setFotoActual(conFoto[conFoto.length - 1].foto_frente);
      }

      // Resumen semana a semana (cargas de entreno, sueño, días entrenados, cumplimiento
      // dieta), la misma construcción de ciclos que usa el coach en su Diario -- de hecho
      // se reutiliza el mismo componente SemanaCard, en modo solo-lectura (ver más abajo),
      // para que el alumno vea exactamente la misma información que ve el coach.
      const { ciclos: ciclosArr, entrenosDetalle: entrenos, dietaRegs: dietaR, diasPlanificados: dp } =
        await cargarCiclosAlumno(user.id, usr?.fecha_inicio_plan);
      setCiclosResumen(ciclosArr);
      setEntrenosResumen(entrenos);
      setDietaRegsResumen(dietaR);
      setDiasPlanificadosResumen(dp);
      if (ciclosArr.length > 0) {
        const cicloActivo = ciclosArr[ciclosArr.length - 1];
        const semanaActual = cicloActivo.semanas[cicloActivo.semanas.length - 1];
        if (semanaActual) setSemanaExpandidaResumen(semanaActual.key);
      }

      // PRs reales: solo de los 4 ejercicios básicos, y solo si están en su rutina
      const EJERCICIOS_PR_BASICOS = [
        { clave: "press banca", label: "Press Banca" },
        { clave: "sentadilla", label: "Sentadilla Libre" },
        { clave: "hip thrust", label: "Hip Thrust" },
        { clave: "peso muerto rumano", label: "Peso Muerto Rumano" },
        { clave: "peso muerto", label: "Peso Muerto Convencional" },
        { clave: "dominada", label: "Dominadas" },
        { clave: "dip", label: "Dips / Fondos en Paralelas" },
        { clave: "fondos en paralelas", label: "Dips / Fondos en Paralelas" },
      ];
      const matchBasico = (nombreEjercicio) => {
        const n = (nombreEjercicio || "").toLowerCase();
        // Se ordena por claves más específicas primero (ej: distinguir "peso muerto rumano" de "peso muerto")
        const ordenados = [...EJERCICIOS_PR_BASICOS].sort((a, b) => b.clave.length - a.clave.length);
        return ordenados.find(b => n.includes(b.clave));
      };

      const { data: registros } = await supabase
        .from("registros_entreno")
        .select("kg, reps, fecha, creado_en, ejercicios(nombre)")
        .eq("usuario_id", user.id)
        .not("kg", "is", null)
        .order("creado_en", { ascending: true });
      if (registros) {
        const porEjercicio = {};
        registros.forEach(r => {
          const nombreReal = r.ejercicios?.nombre;
          const basico = matchBasico(nombreReal);
          if (!basico) return;
          if (!porEjercicio[basico.label]) porEjercicio[basico.label] = [];
          porEjercicio[basico.label].push({ carga: r.kg, reps: r.reps });
        });
        const lista = Object.entries(porEjercicio).map(([ejercicio, historialCompleto]) => {
          // Se queda solo con los momentos en que se superó el peso máximo anterior (progresión real de PR)
          let maxHasta = -Infinity;
          const historial = [];
          historialCompleto.forEach(h => {
            if (h.carga > maxHasta) { maxHasta = h.carga; historial.push(h); }
          });
          return { ejercicio, historial };
        }).filter(p => p.historial.length > 0);
        setPrs(lista);
      }

      setLoading(false);
    };
    cargar();
  }, []);

  if (loading) return (
    <div style={{ padding: "20px 16px 90px", height: "100%", boxSizing: "border-box", display: "flex", alignItems: "center", justifyContent: "center" }}>
      <div style={{ color: theme.muted }}>Cargando...</div>
    </div>
  );

  const pesos = checkins.map(c => c.peso);
  const maxP = pesos.length > 0 ? Math.max(...pesos) : 0;
  const minP = pesos.length > 0 ? Math.min(...pesos) - 0.5 : 0;
  const chartH = 100;
  const pesoActual = pesos.length > 0 ? pesos[pesos.length - 1] : null;
  const pesoInicial = pesos.length > 0 ? pesos[0] : null;
  const diferencia = pesoActual !== null && pesoInicial !== null ? (pesoActual - pesoInicial).toFixed(1) : null;

  return (
    <div style={{ padding: "20px 16px 90px", overflowY: "auto", height: "100%", boxSizing: "border-box" }}>
      <div style={{ marginBottom: 20 }}><span onClick={() => onNav("alumno_home")} style={{ fontSize: 16, cursor: "pointer", color: theme.text, marginBottom: 6, display: "inline-block" }}>← Inicio</span><div style={{ color: theme.muted, fontSize: 12, marginTop: 4 }}>SEGUIMIENTO</div><div style={{ fontSize: 22, fontWeight: 800, color: theme.text }}>Progreso 📈</div></div>

      {anillos30 && (
        <Card style={{ marginBottom: 14, padding: "12px 10px" }}>
          <div style={{ fontSize: 10, color: theme.muted, letterSpacing: 1, marginBottom: 10, textAlign: "center" }}>CUMPLIMIENTO · ÚLTIMOS 30 DÍAS</div>
          <div style={{ display: "flex", justifyContent: "space-around" }}>
            {[
              { label: "Entreno", pct: anillos30.entrenoPct, color: theme.accentLight, icon: "🏋️" },
              { label: "Nutrición", pct: anillos30.nutriPct, color: theme.success, icon: "🥗" },
              { label: "Diario", pct: anillos30.diarioPct, color: "#A78BFA", icon: "📝" },
            ].map(a => (
              <div key={a.label} style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 6 }}>
                <div style={{ width: 56, height: 56, borderRadius: "50%", background: a.pct == null ? theme.surface : `conic-gradient(${a.color} ${Math.max(0, Math.min(100, a.pct)) * 3.6}deg, ${theme.surface} 0deg)`, display: "flex", alignItems: "center", justifyContent: "center" }}>
                  <div style={{ width: 44, height: 44, borderRadius: "50%", background: theme.card, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 12, fontWeight: 800, color: theme.text }}>
                    {a.pct == null ? "—" : `${a.pct}%`}
                  </div>
                </div>
                <div style={{ fontSize: 10, color: theme.muted, fontWeight: 700 }}>{a.icon} {a.label}</div>
              </div>
            ))}
          </div>
        </Card>
      )}

      <Card style={{ marginBottom: 14 }}>
        <div style={{ fontSize: 12, color: theme.muted, marginBottom: 4 }}>PESO CORPORAL</div>
        {pesos.length === 0 ? (
          <div style={{ fontSize: 13, color: theme.muted, padding: "12px 0" }}>Aún no tienes check-ins con peso registrado.</div>
        ) : (
          <>
            <div style={{ fontSize: 22, fontWeight: 800, color: theme.text, marginBottom: 12 }}>
              {pesoActual} kg {diferencia !== null && (
                <span style={{ fontSize: 13, color: diferencia <= 0 ? theme.success : theme.warning, fontWeight: 600 }}>
                  {diferencia <= 0 ? "↓" : "↑"} {Math.abs(diferencia)} kg
                </span>
              )}
            </div>
            {pesos.length > 1 ? (
              <svg width="100%" height={chartH+30} style={{ overflow: "visible" }}>
                {checkins.map((c,i) => {
                  const x=(i/(checkins.length-1))*100, y=chartH-((c.peso-minP)/(maxP-minP||1))*chartH;
                  const fechaCorta = new Date(c.fecha).toLocaleDateString("es-CL", { day:"numeric", month:"short" });
                  return (<g key={i}>{i>0&&(()=>{const px=((i-1)/(checkins.length-1))*100,py=chartH-((checkins[i-1].peso-minP)/(maxP-minP||1))*chartH;return <line x1={`${px}%`} y1={py} x2={`${x}%`} y2={y} stroke={theme.accent} strokeWidth={2}/>;})()}<circle cx={`${x}%`} cy={y} r={4} fill={theme.accent}/><text x={`${x}%`} y={chartH+20} textAnchor="middle" fill={theme.muted} fontSize={9}>{fechaCorta}</text></g>);
                })}
              </svg>
            ) : (
              <div style={{ fontSize: 12, color: theme.muted }}>Necesitas al menos 2 check-ins para ver el gráfico de evolución.</div>
            )}
          </>
        )}
      </Card>

      <Card style={{ marginBottom: 14 }}>
        <div style={{ fontSize: 12, color: theme.muted, marginBottom: 4 }}>🚶 PASOS DIARIOS (ÚLTIMOS 30 DÍAS)</div>
        {pasosResumen.length === 0 ? (
          <div style={{ fontSize: 13, color: theme.muted, padding: "12px 0" }}>Aún no tienes pasos registrados.</div>
        ) : (() => {
          const maxPasos = Math.max(...pasosResumen.map(p => p.pasos), 1);
          const promPasos = Math.round(pasosResumen.reduce((a, p) => a + p.pasos, 0) / pasosResumen.length);
          const barH = 90;
          const anchoBarra = Math.max(6, Math.min(18, 90 / pasosResumen.length));
          return (
            <>
              <div style={{ fontSize: 20, fontWeight: 800, color: theme.text, marginBottom: 12 }}>
                {promPasos.toLocaleString("es-CL")} <span style={{ fontSize: 12, color: theme.muted, fontWeight: 600 }}>pasos/día promedio</span>
              </div>
              <div style={{ display: "flex", alignItems: "flex-end", gap: Math.max(2, 4 - Math.floor(pasosResumen.length / 15)), height: barH + 24, overflowX: pasosResumen.length > 20 ? "auto" : "visible" }}>
                {pasosResumen.map((p, i) => {
                  const h = Math.max(3, (p.pasos / maxPasos) * barH);
                  const fechaCorta = new Date(p.fecha).toLocaleDateString("es-CL", { day: "numeric", month: "short" });
                  return (
                    <div key={i} style={{ display: "flex", flexDirection: "column", alignItems: "center", flexShrink: 0, width: anchoBarra }}>
                      <div title={`${p.pasos.toLocaleString("es-CL")} pasos`} style={{ width: "100%", height: h, background: `linear-gradient(180deg, ${theme.accentLight}, ${theme.accent})`, borderRadius: 3, boxShadow: `0 0 6px ${theme.accent}55` }} />
                      {(i === 0 || i === pasosResumen.length - 1 || pasosResumen.length <= 8) && (
                        <div style={{ fontSize: 8, color: theme.muted, marginTop: 4, whiteSpace: "nowrap" }}>{fechaCorta}</div>
                      )}
                    </div>
                  );
                })}
              </div>
            </>
          );
        })()}
      </Card>

      {checkins.length > 1 && (() => {
        const primero = checkins[0], ultimo = checkins[checkins.length - 1];
        const metricas = [
          { label: "% Grasa", key: "porc_grasa", unidad: "%", color: "#B0C4DE" },
          { label: "Cintura", key: "cintura", unidad: "cm", color: "#B0C4DE" },
          { label: "Cadera", key: "cadera", unidad: "cm", color: "#B0C4DE" },
          { label: "Brazo", key: "brazo", unidad: "cm", color: "#B0C4DE" },
          { label: "Pecho", key: "pecho", unidad: "cm", color: "#B0C4DE" },
          { label: "Pierna", key: "pierna", unidad: "cm", color: "#B0C4DE" },
        ].filter(m => primero[m.key] || ultimo[m.key]);
        if (metricas.length === 0) return null;
        return (
          <Card style={{ marginBottom: 14 }}>
            <div style={{ fontSize: 12, color: theme.muted, marginBottom: 12 }}>EVOLUCIÓN DE MEDIDAS</div>
            {metricas.map(m => {
              const val1 = primero[m.key], val2 = ultimo[m.key];
              const diff = (val1 && val2) ? (val2 - val1).toFixed(1) : null;
              return (
                <div key={m.key} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10, paddingBottom: 10, borderBottom: `1px solid ${theme.border}` }}>
                  <span style={{ fontSize: 13, color: theme.text, fontWeight: 600 }}>{m.label}</span>
                  <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                    <span style={{ fontSize: 12, color: theme.muted }}>{val1 || "—"}{m.unidad}</span>
                    <span style={{ color: theme.muted, fontSize: 12 }}>→</span>
                    <span style={{ fontSize: 14, fontWeight: 800, color: m.color }}>{val2 || "—"}{m.unidad}</span>
                    {diff !== null && (
                      <span style={{ fontSize: 11, fontWeight: 700, color: diff <= 0 ? theme.success : theme.warning }}>
                        {diff > 0 ? "+" : ""}{diff}
                      </span>
                    )}
                  </div>
                </div>
              );
            })}
          </Card>
        );
      })()}

      <Card style={{ marginBottom: 14 }}>
        <div style={{ fontSize: 12, color: theme.muted, marginBottom: 10 }}>COMPARACIÓN DE FOTOS</div>
        {!fotoAntes && !fotoActual ? (
          <div style={{ fontSize: 13, color: theme.muted }}>Aún no tienes fotos para comparar. Súbelas en tu Anamnesis o Check-in.</div>
        ) : (
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
            {[{label:"Antes (Anamnesis)", url: fotoAntes, actual:false},{label:"Actual (Check-in)", url: fotoActual, actual:true}].map(({label,url,actual})=>(
              <div key={label} style={{ background: theme.surface, borderRadius: 10, overflow:"hidden", border: `1px solid ${actual?theme.accent+"44":theme.border}` }}>
                {url ? (
                  <img src={url} alt={label} onClick={() => setLightbox(url)} style={{ width:"100%", height:120, objectFit:"cover", cursor:"pointer" }} />
                ) : (
                  <div style={{ height:120, display:"flex", alignItems:"center", justifyContent:"center" }}><span style={{ fontSize: 24, opacity:0.3 }}>📷</span></div>
                )}
                <div style={{ padding:"6px 4px", textAlign:"center" }}>
                  <span style={{ fontSize: 11, color: theme.muted }}>{label}</span>
                  {actual && url && <div><Tag color={theme.success}>Actual</Tag></div>}
                </div>
              </div>
            ))}
          </div>
        )}
      </Card>

      <Card style={{ marginBottom: 14 }}>
        <div style={{ fontSize: 12, color: theme.muted, marginBottom: 4 }}>📅 RESUMEN SEMANA A SEMANA</div>
        <div style={{ fontSize: 11, color: theme.muted, marginBottom: 10 }}>Tus cargas de entreno, sueño y cumplimiento de dieta, semana a semana -- lo mismo que ve tu coach.</div>
        {ciclosResumen.length === 0 ? (
          <div style={{ fontSize: 13, color: theme.muted }}>Aún no hay suficientes registros para mostrar un resumen semanal.</div>
        ) : (() => {
          const ctxResumenAlumno = {
            resumenSemana: (semana) => resumenSemanaCalc(semana, entrenosResumen, dietaRegsResumen),
            semanaExpandida: semanaExpandidaResumen, setSemanaExpandida: setSemanaExpandidaResumen,
            diaExpandido: diaExpandidoResumen, setDiaExpandido: setDiaExpandidoResumen,
            diasPlanificados: diasPlanificadosResumen, entrenosDetalle: entrenosResumen, dietaRegs: dietaRegsResumen,
            edicionSerie: null, edicionKg: "", setEdicionKg: () => {}, edicionReps: "", setEdicionReps: () => {},
            guardarEdicionSerie: () => {}, cancelarEdicionSerie: () => {}, iniciarEdicionSerie: () => {},
            edicionComida: null, edicionEstado: "", setEdicionEstado: () => {}, edicionDescripcion: "", setEdicionDescripcion: () => {},
            guardarEdicionComida: () => {}, cancelarEdicionComida: () => {}, iniciarEdicionComida: () => {},
            COLOR_RPE: "#B0C4DE", COLOR_SUENO: "#39FF88",
            iconEstado: (estado) => estado === "completada" ? "✅" : estado === "no_hecha" ? "❌" : estado === "cambio" ? "🔄" : "⬜",
            readOnly: true,
          };
          return [...ciclosResumen[ciclosResumen.length - 1].semanas].reverse().map((semana) => (
            <SemanaCard key={semana.key} semana={semana} ctx={ctxResumenAlumno} />
          ));
        })()}
      </Card>

      <Card style={{ marginBottom: 14 }}>
        <div style={{ fontSize: 12, color: theme.muted, marginBottom: 12 }}>RÉCORDS PERSONALES 🏆</div>
        {prs.length === 0 ? (
          <div style={{ fontSize: 13, color: theme.muted }}>Aún no hay cargas registradas en tus entrenamientos. Tus PRs aparecerán acá a medida que entrenes.</div>
        ) : (
          prs.map((pr,idx) => {
            const ultimo = pr.historial[pr.historial.length-1];
            return (
              <div key={pr.ejercicio} style={{ marginBottom: 16 }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 6 }}><span style={{ fontSize: 16 }}>🏋️</span><span style={{ fontSize: 13, fontWeight: 700, color: theme.text }}>{pr.ejercicio}</span></div>
                  <div style={{ display: "flex", alignItems: "center", gap: 6 }}><span style={{ fontSize: 14, fontWeight: 900, color: theme.warning }}>{ultimo.carga} kg</span>{ultimo.reps && <span style={{ fontSize: 11, color: theme.muted }}>× {ultimo.reps} rep{ultimo.reps!==1?"s":""}</span>}<Tag color={theme.warning}>PR</Tag></div>
                </div>
                <div style={{ display: "flex", gap: 4, flexWrap: "wrap" }}>
                  {pr.historial.map((h,i)=>(<div key={i} style={{ display:"flex",alignItems:"center",gap:3 }}><div style={{ background:i===pr.historial.length-1?`${theme.warning}22`:theme.surface,border:`1px solid ${i===pr.historial.length-1?theme.warning+"66":theme.border}`,borderRadius:8,padding:"4px 8px",textAlign:"center" }}><div style={{ fontSize:12,fontWeight:800,color:i===pr.historial.length-1?theme.warning:theme.text }}>{h.carga}kg</div>{h.reps && <div style={{ fontSize:10,color:theme.muted }}>×{h.reps}</div>}</div>{i<pr.historial.length-1&&<span style={{ color:theme.border,fontSize:12 }}>›</span>}</div>))}
                </div>
                {idx<prs.length-1&&<div style={{ borderBottom:`1px solid ${theme.border}`,marginTop:14 }}/>}
              </div>
            );
          })
        )}
      </Card>
      <NavBar active="progreso" onNav={onNav} />
      <ImageLightbox src={lightbox} onClose={() => setLightbox(null)} />
    </div>
  );
}
function CoachPanel({ onNav, onVerAlumno }) {
  const [alumnos, setAlumnos] = useState([]);
  const [loading, setLoading] = useState(true);
  const [mensajesPendientes, setMensajesPendientes] = useState(0);
  const [alumnosPorVencer, setAlumnosPorVencer] = useState([]);
  const [checkinsPendientes, setCheckinsPendientes] = useState(0);

  useEffect(() => {
    const cargarAlumnos = async () => {
      const { data } = await supabase
        .from("usuarios")
        .select("id, nombre, email, whatsapp, objetivo, peso_actual, edad, sexo, estatura, created_at")
        .order("created_at", { ascending: false });
      if (data) {
          const alumnosFiltrados = data.filter(a => a.email !== "coach.claudiomiquel@gmail.com");
          const { data: msjs } = await supabase.from("mensajes").select("usuario_id").eq("de", "alumno").eq("leido", false);
          const idsConMensaje = new Set((msjs || []).map(m => m.usuario_id));
          setAlumnos(alumnosFiltrados.map(a => ({ ...a, tieneMensaje: idsConMensaje.has(a.id) })));
        }
        setLoading(false);
      const { data: pendientes } = await supabase.from("mensajes").select("id, usuario_id, texto, created_at").eq("de", "alumno").eq("leido", false).order("created_at", { ascending: false });
      if (pendientes) setMensajesPendientes(pendientes.length);
      const { data: pagosData } = await supabase.from("pagos").select("*, usuarios(nombre, id)").eq("estado", "activo").order("fecha_vencimiento", { ascending: true });
      if (pagosData) {
        const hoy = new Date();
        const porVencer = pagosData.filter(p => {
          const vence = new Date(p.fecha_vencimiento);
          const dias = Math.ceil((vence - hoy) / (1000 * 60 * 60 * 24));
          return dias <= 3 && dias >= 0;
        }).map(p => ({
          ...p.usuarios,
          diasRestantes: Math.ceil((new Date(p.fecha_vencimiento) - hoy) / (1000 * 60 * 60 * 24))
        }));
        setAlumnosPorVencer(porVencer);
      }
      const { data: chks } = await supabase.from("checkins").select("id").order("created_at", { ascending: false });
      if (chks) setCheckinsPendientes(chks.length);
    };
    cargarAlumnos();
  }, []);


  return (
    <div style={{ padding:"20px 16px 24px",overflowY:"auto",height:"100%",boxSizing:"border-box" }}>
      <div style={{ display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:20 }}>
        <div>
          <div style={{ display:"flex",alignItems:"center",gap:8,marginBottom:2 }}>
            <img src={ICON} alt="logo" style={{ width:28,height:18,objectFit:"contain" }}/>
            <div style={{ fontSize:18,fontWeight:900,letterSpacing:1,color:theme.text }}>MIQUEL COACH</div>
          </div>
          <div style={{ fontSize:10,fontWeight:800,color:theme.accentLight,letterSpacing:4 }}>PERFORMANCE</div>
        </div>
        <Btn onClick={() => { supabase.auth.signOut(); onNav("login"); }} variant="ghost" style={{ width:"auto",padding:"8px 14px",fontSize:12 }}>Salir</Btn>
      </div>

      {/* Métricas */}
      <div style={{ display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:10,marginBottom:16 }}>
        {[
          { label:"Alumnos", value: String(alumnos.length), icon:"👥", color:theme.accentLight },
          { label:"Sin pago", value:String(alumnosPorVencer.length), icon:"💳", color:theme.danger },
        ].map(m=>(
          <Card key={m.label} style={{ textAlign:"center",padding:14 }}>
            <div style={{ fontSize:20 }}>{m.icon}</div>
            <div style={{ fontSize:22,fontWeight:900,color:m.color,marginTop:4 }}>{m.value}</div>
            <div style={{ fontSize:10,color:theme.muted }}>{m.label}</div>
          </Card>
        ))}
      </div>

      {/* Lista alumnos reales */}
      {mensajesPendientes > 0 && (
        <div style={{ marginBottom: 16 }}>
          {alumnosPorVencer.length > 0 && (
        <div style={{ marginBottom: 16 }}>
          <div style={{ fontSize: 12, color: theme.warning, fontWeight: 700, marginBottom: 10 }}>⚠️ PAGOS POR VENCER</div>
          {alumnosPorVencer.map(a => (
            <div key={a.id} style={{ background:`${theme.warning}10`, border:`1px solid ${theme.warning}33`, borderRadius:12, padding:"12px 14px", marginBottom:8, display:"flex", justifyContent:"space-between", alignItems:"center" }}>
              <div>
                <div style={{ fontSize:14, fontWeight:700, color:theme.text }}>{a.nombre}</div>
                <div style={{ fontSize:12, color:theme.muted }}>{a.diasRestantes === 0 ? "Vence hoy" : `Vence en ${a.diasRestantes} días`}</div>
              </div>
              <button onClick={() => onVerAlumno({...a, tabInicial: "Pagos"})} style={{ background:`${theme.warning}22`, border:`1px solid ${theme.warning}55`, borderRadius:8, padding:"5px 10px", color:theme.warning, fontSize:11, fontWeight:700, cursor:"pointer" }}>Ver →</button>
            </div>
          ))}
        </div>
      )}
          <div style={{ fontSize: 12, color: theme.danger, fontWeight: 700, marginBottom: 10 }}>💬 MENSAJES SIN LEER</div>
          {alumnos.filter(a => a.tieneMensaje).map(a => (
            <div key={a.id} onClick={() => { onVerAlumno({...a, tabInicial: "Mensajes"}); }}
              style={{ background:`${theme.danger}10`, border:`1px solid ${theme.danger}33`, borderRadius:12, padding:"12px 14px", marginBottom:8, cursor:"pointer", display:"flex", justifyContent:"space-between", alignItems:"center" }}>
              <div>
                <div style={{ fontSize:14, fontWeight:700, color:theme.text }}>{a.nombre}</div>
                <div style={{ fontSize:12, color:theme.muted }}>Tiene mensajes sin leer</div>
              </div>
              <div style={{ background:theme.danger, borderRadius:8, padding:"4px 10px", fontSize:12, fontWeight:800, color:"#fff" }}>Ver →</div>
            </div>
          ))}
        </div>
      )}
      <div style={{ fontSize:12,color:theme.muted,marginBottom:10 }}>ALUMNOS REGISTRADOS</div>
      {loading ? (
        <Card style={{ textAlign:"center",padding:20 }}>
          <div style={{ color:theme.muted,fontSize:13 }}>Cargando alumnos...</div>
        </Card>
      ) : alumnos.length === 0 ? (
        <Card style={{ textAlign:"center",padding:20 }}>
          <div style={{ fontSize:24,marginBottom:8 }}>👥</div>
          <div style={{ color:theme.muted,fontSize:13 }}>Aún no hay alumnos registrados</div>
        </Card>
      ) : (
        alumnos.map(a => (
          <div key={a.id} onClick={() => onVerAlumno(a)} style={{ marginBottom:10, cursor:"pointer", background:theme.card, border:`1px solid ${theme.border}`, borderRadius:14, padding:"14px 16px" }}>
            <div style={{ display:"flex",alignItems:"center",gap:12 }}>
              <div style={{ width:40,height:40,minWidth:40,borderRadius:12,background:theme.accent,display:"flex",alignItems:"center",justifyContent:"center",fontSize:16,fontWeight:800 }}>
                {a.nombre ? a.nombre[0].toUpperCase() : "?"}
              </div>
              <div style={{ flex:1, display:"grid", gridTemplateColumns:"1fr 1fr", gap:"2px 10px", alignItems:"center" }}>
                <div style={{ fontSize:14,fontWeight:700,color:theme.text, gridColumn:"1 / -1" }}>{a.nombre || "Sin nombre"}</div>
                <div style={{ fontSize:11,color:theme.muted, display:"flex", alignItems:"center", gap:4 }}>📱 {a.whatsapp || "—"}</div>
                <div style={{ fontSize:11,color:theme.muted, display:"flex", alignItems:"center", gap:4, justifySelf:"end" }}>🎯 {a.objetivo || "—"}</div>
              </div>
            </div>
          </div>
        ))
      )}
    </div>
  );
}

function PagosAlumnoScreen({ onNav }) {
  const [pago, setPago] = useState(null);
  const [loading, setLoading] = useState(true);
  const [reportado, setReportado] = useState(false);

  useEffect(() => {
    const cargar = async () => {
      const { data: { user } } = await supabase.auth.getUser();
      if (user) {
        const { data } = await supabase.from("pagos").select("*").eq("usuario_id", user.id).order("created_at", { ascending: false }).limit(1);
        if (data && data.length > 0) { setPago(data[0]); setReportado(data[0].reportado_por_alumno || false); }
      }
      setLoading(false);
    };
    cargar();
  }, []);

  const marcarPagado = async () => {
    if (!pago) return;
    await supabase.from("pagos").update({ reportado_por_alumno: true }).eq("id", pago.id);
    setReportado(true);
  };

  if (loading) return (
    <div style={{ padding:"20px 16px 90px", height:"100%", boxSizing:"border-box", display:"flex", alignItems:"center", justifyContent:"center" }}>
      <div style={{ color:theme.muted }}>Cargando...</div>
    </div>
  );

  const hoy = new Date();
  const vence = pago?.fecha_vencimiento ? new Date(pago.fecha_vencimiento) : null;
  const diasRestantes = vence ? Math.ceil((vence - hoy) / (1000 * 60 * 60 * 24)) : null;
  let estadoColor = theme.success, estadoTexto = "Al día", estadoIcono = "✅";
  if (pago?.estado === "bloqueado") { estadoColor = theme.danger; estadoTexto = "Bloqueado"; estadoIcono = "🔒"; }
  else if (diasRestantes !== null && diasRestantes < 0) { estadoColor = theme.danger; estadoTexto = "Vencido"; estadoIcono = "❌"; }
  else if (diasRestantes !== null && diasRestantes <= 3) { estadoColor = theme.warning; estadoTexto = "Por vencer"; estadoIcono = "⚠️"; }

  return (
    <div style={{ padding:"20px 16px 90px", overflowY:"auto", height:"100%", boxSizing:"border-box" }}>
      <div style={{ marginBottom:20 }}>
        <span onClick={() => onNav("alumno_home")} style={{ fontSize: 16, cursor: "pointer", color: theme.text, marginBottom: 6, display: "inline-block" }}>← Inicio</span>
        <div style={{ color:theme.muted, fontSize:12, marginTop:4 }}>MEMBRESÍA</div>
        <div style={{ fontSize:22, fontWeight:800, color:theme.text }}>Tus Pagos 💳</div>
      </div>

      {!pago ? (
        <Card style={{ textAlign:"center", padding:40 }}>
          <div style={{ fontSize:32, marginBottom:12 }}>💳</div>
          <div style={{ fontSize:15, fontWeight:700, color:theme.text, marginBottom:8 }}>Aún no hay información de pagos</div>
          <div style={{ fontSize:13, color:theme.muted }}>Tu coach cargará esta información pronto</div>
        </Card>
      ) : (
        <>
          <Card style={{ marginBottom:14, textAlign:"center", padding:24, background:`${estadoColor}12`, border:`1px solid ${estadoColor}44` }}>
            <div style={{ fontSize:28, marginBottom:8 }}>{estadoIcono}</div>
            <div style={{ fontSize:16, fontWeight:800, color:estadoColor, marginBottom:4 }}>{estadoTexto}</div>
            {vence && (
              <div style={{ fontSize:13, color:theme.muted }}>
                {diasRestantes >= 0 ? `Vence el ${vence.toLocaleDateString("es-CL", { day:"2-digit", month:"long", year:"numeric" })}` : `Venció el ${vence.toLocaleDateString("es-CL", { day:"2-digit", month:"long", year:"numeric" })}`}
              </div>
            )}
          </Card>

          {pago.monto && (
            <Card style={{ marginBottom:14 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center" }}>
                <span style={{ fontSize:13, color:theme.muted }}>Monto</span>
                <span style={{ fontSize:18, fontWeight:800, color:theme.text }}>${pago.monto}</span>
              </div>
            </Card>
          )}

          {(estadoTexto === "Por vencer" || estadoTexto === "Vencido") && (
            <button onClick={marcarPagado} disabled={reportado} style={{ background: reportado ? `${theme.success}22` : theme.accent, border:"none", borderRadius:10, padding:"12px 16px", color: reportado ? theme.success : "#fff", fontWeight:700, fontSize:14, cursor: reportado ? "default" : "pointer", width:"100%", marginBottom:14 }}>
              {reportado ? "✅ Aviso enviado al coach" : "✓ Ya realicé la transferencia"}
            </button>
          )}

          <Card>
            <div style={{ fontSize:12, color:theme.muted }}>Si ya realizaste el pago y no se refleja, avisale directo a tu coach por el chat de Mensajes.</div>
          </Card>
        </>
      )}
    </div>
  );
}
function PagosCoach({ alumno }) {
  const [pago, setPago] = useState(null);
  const [loading, setLoading] = useState(true);
  const [fechaVencimiento, setFechaVencimiento] = useState("");
  const [monto, setMonto] = useState("");
  const [guardando, setGuardando] = useState(false);
  const [exito, setExito] = useState("");

  useEffect(() => { cargarPago(); }, [alumno]);

  const cargarPago = async () => {
    if (!alumno?.id) return;
    const { data } = await supabase.from("pagos").select("*").eq("usuario_id", alumno.id).order("created_at", { ascending: false }).limit(1);
    if (data && data.length > 0) setPago(data[0]);
    setLoading(false);
  };

  const asignarPago = async () => {
    if (!fechaVencimiento) return;
    setGuardando(true);
    await supabase.from("pagos").insert({
      usuario_id: alumno.id,
      fecha_vencimiento: fechaVencimiento,
      monto: parseInt(monto) || null,
      estado: "activo",
    });
    setExito("Pago asignado correctamente");
    setFechaVencimiento("");
    setMonto("");
    cargarPago();
    setGuardando(false);
    setTimeout(() => setExito(""), 3000);
  };

  const confirmarPago = async () => {
    if (!pago) return;
    setGuardando(true);
    const nuevaFecha = new Date();
    nuevaFecha.setDate(nuevaFecha.getDate() + 28);
    await supabase.from("pagos").update({
      estado: "activo",
      fecha_pago: fechaLocalStr(),
      reportado_por_alumno: false,
      fecha_vencimiento: fechaLocalStr(nuevaFecha),
    }).eq("id", pago.id);
    setExito("✅ Pago confirmado — renovado 4 semanas");
    cargarPago();
    setGuardando(false);
    setTimeout(() => setExito(""), 3000);
  };

  const bloquear = async () => {
    if (!pago) return;
    await supabase.from("pagos").update({ estado: pago.estado === "bloqueado" ? "activo" : "bloqueado" }).eq("id", pago.id);
    cargarPago();
  };

  const inputStyle = { background: theme.surface, border: `1px solid ${theme.border}`, borderRadius: 8, padding: "8px 10px", color: theme.text, fontSize: 13, outline: "none", width: "100%", boxSizing: "border-box" };

  if (loading) return <Card style={{ textAlign: "center", padding: 20 }}><div style={{ color: theme.muted }}>Cargando...</div></Card>;

  return (
    <div>
      {exito && <Card style={{ textAlign: "center", padding: 14, marginBottom: 14, background: `${theme.success}18`, border: `1px solid ${theme.success}44` }}><div style={{ fontSize: 13, fontWeight: 700, color: theme.success }}>{exito}</div></Card>}

      {/* Estado actual */}
      {pago && (
        <Card style={{ marginBottom: 14, border: `1px solid ${pago.estado === "bloqueado" ? theme.danger + "55" : pago.reportado_por_alumno ? theme.warning + "55" : theme.success + "55"}` }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
            <div style={{ fontSize: 14, fontWeight: 700, color: theme.text }}>Estado de pago</div>
            <Tag color={pago.estado === "bloqueado" ? theme.danger : pago.reportado_por_alumno ? theme.warning : theme.success}>
              {pago.estado === "bloqueado" ? "🔒 Bloqueado" : pago.reportado_por_alumno ? "⚠️ Reportó pago" : "✅ Activo"}
            </Tag>
          </div>
          <div style={{ fontSize: 13, color: theme.muted, marginBottom: 4 }}>Vence: <span style={{ color: theme.text, fontWeight: 600 }}>{pago.fecha_vencimiento}</span></div>
          {pago.monto && <div style={{ fontSize: 13, color: theme.muted, marginBottom: 10 }}>Monto: <span style={{ color: theme.text, fontWeight: 600 }}>${pago.monto.toLocaleString()}</span></div>}

          <div style={{ display: "flex", gap: 8 }}>
            {pago.reportado_por_alumno && (
              <button onClick={confirmarPago} style={{ flex: 1, background: `${theme.success}22`, border: `1px solid ${theme.success}55`, borderRadius: 8, padding: "8px", color: theme.success, fontSize: 12, fontWeight: 700, cursor: "pointer" }}>
                ✓ Confirmar pago
              </button>
            )}
            <button onClick={bloquear} style={{ flex: 1, background: pago.estado === "bloqueado" ? `${theme.success}22` : `${theme.danger}22`, border: `1px solid ${pago.estado === "bloqueado" ? theme.success + "55" : theme.danger + "55"}`, borderRadius: 8, padding: "8px", color: pago.estado === "bloqueado" ? theme.success : theme.danger, fontSize: 12, fontWeight: 700, cursor: "pointer" }}>
              {pago.estado === "bloqueado" ? "🔓 Desbloquear" : "🔒 Bloquear"}
            </button>
          </div>
        </Card>
      )}

      {/* Asignar nuevo pago */}
      <Card>
        <div style={{ fontSize: 12, color: theme.muted, marginBottom: 12 }}>{pago ? "RENOVAR PAGO" : "ASIGNAR PRIMER PAGO"}</div>
        <div style={{ marginBottom: 10 }}>
          <div style={{ fontSize: 11, color: theme.muted, marginBottom: 4 }}>Fecha de vencimiento</div>
          <input type="date" style={inputStyle} value={fechaVencimiento} onChange={e => setFechaVencimiento(e.target.value)} />
        </div>
        <div style={{ marginBottom: 14 }}>
          <div style={{ fontSize: 11, color: theme.muted, marginBottom: 4 }}>Monto (opcional)</div>
          <input type="number" style={inputStyle} placeholder="Ej: 50000" value={monto} onChange={e => setMonto(e.target.value)} />
        </div>
        <Btn onClick={asignarPago} style={{ background: theme.success }}>{guardando ? "Guardando..." : "Asignar pago"}</Btn>
      </Card>
    </div>
  );
}
