function RutinaCoach({ alumno }) {
  const [rutinas, setRutinas] = useState([]);
  const [loading, setLoading] = useState(true);
  const [creando, setCreando] = useState(false);
  const [modoDuplicar, setModoDuplicar] = useState(false);
  const [editandoRutinaId, setEditandoRutinaId] = useState(null);
  const formRef = useRef(null);
  const [verCargas, setVerCargas] = useState({});
  const [cargas, setCargas] = useState({});
  const [nombreRutina, setNombreRutina] = useState("");
  const [diaRutina, setDiaRutina] = useState("");
  const [grupoMuscularRutina, setGrupoMuscularRutina] = useState("");
  const [mapaImagenesGrupoMuscular, setMapaImagenesGrupoMuscular] = useState({});
  const [nombresGruposMuscularesUsados, setNombresGruposMuscularesUsados] = useState([]);
  const [calentamientoGeneral, setCalentamientoGeneral] = useState([]);
  const [vueltaCalma, setVueltaCalma] = useState([]);
  const [cardio, setCardio] = useState([]);
  const [metaPasos, setMetaPasos] = useState("");
  const [ejercicios, setEjercicios] = useState([
    { nombre: "", videoUrl: "", descansoDesde: 60, descansoHasta: 90, tempoBajada: "3", tempoPausa: "1", tempoSubida: "1", grupoSuperserie: "",
      seriesAproximacion: [{ reps: "8", pctDesde: "50", pctHasta: "60" }, { reps: "6", pctDesde: "70", pctHasta: "80" }, { reps: "3", pctDesde: "85", pctHasta: "90" }],
      seriesEfectivas: [{ reps: "10", rir: 2, tecnica: "normal" }] }
  ]);
  // Ids (_dbId) de ejercicios que existían en la rutina y el coach sacó
  // durante la edición -- se borran de Supabase recién al guardar, para no
  // perder el ejercicio si cancela la edición sin guardar.
  const [ejerciciosEliminados, setEjerciciosEliminados] = useState([]);
  // Estado (expandido/colapsado) de la sección Aproximación por ejercicio --
  // por defecto solo el primer ejercicio de la rutina la muestra expandida.
  const [aproxExpandida, setAproxExpandida] = useState({});
  const [guardando, setGuardando] = useState(false);
  const [exito, setExito] = useState(false);
  const [nombresEjerciciosUsados, setNombresEjerciciosUsados] = useState([]);
  const [fechaInicioPlan, setFechaInicioPlan] = useState("");
  const [guardandoFechaInicio, setGuardandoFechaInicio] = useState(false);
  const [mapaImagenes, setMapaImagenes] = useState({});
  const [rutinaExpandida, setRutinaExpandida] = useState({});
  const [plantillas, setPlantillas] = useState([]);
  const [mostrarPlantillas, setMostrarPlantillas] = useState(false);
  const [modoPlantilla, setModoPlantilla] = useState(false);
  const [guardarPlantillaAbierto, setGuardarPlantillaAbierto] = useState(false);
  const [nombrePlantillaNueva, setNombrePlantillaNueva] = useState("");
  const [guardandoPlantilla, setGuardandoPlantilla] = useState(false);

  useEffect(() => {
    cargarRutinas();
    cargarNombresEjercicios();
    cargarNombresGruposMusculares();
    cargarPlantillas();
    setFechaInicioPlan(alumno?.fecha_inicio_plan || "");
  }, [alumno]);

  useEffect(() => { cargarMapaImagenesEjercicios().then(setMapaImagenes); }, []);
  useEffect(() => { cargarMapaImagenesGrupoMuscular().then(setMapaImagenesGrupoMuscular); }, []);
  const recargarMapaImagenesGrupoMuscular = () => {
    cargarMapaImagenesGrupoMuscular().then(setMapaImagenesGrupoMuscular);
    cargarNombresGruposMusculares();
  };

  // El conteo de las 4 semanas del ciclo (ver Diario) arranca automáticamente desde
  // el primer registro del alumno. Si el coach prefiere que arranque un día puntual
  // (ej: siempre lunes, aunque la cuenta se haya creado el sábado), la define acá.
  const guardarFechaInicioPlan = async () => {
    if (!alumno?.id) return;
    setGuardandoFechaInicio(true);
    const { error } = await supabase.from("usuarios").update({ fecha_inicio_plan: fechaInicioPlan || null }).eq("id", alumno.id);
    setGuardandoFechaInicio(false);
    if (error) { alert("Error al guardar la fecha de inicio: " + error.message); return; }
  };

  const cargarNombresEjercicios = async () => {
    const { data } = await supabase.from("ejercicios").select("nombre");
    if (data) {
      const unicos = [...new Set(data.map(e => e.nombre).filter(Boolean))].sort();
      setNombresEjerciciosUsados(unicos);
    }
  };
  const cargarNombresGruposMusculares = async () => {
    const { data } = await supabase.from("grupo_muscular_imagenes").select("nombre_original");
    if (data) setNombresGruposMuscularesUsados([...new Set(data.map(g => g.nombre_original).filter(Boolean))].sort());
  };

  // Plantillas de rutina: no son de ningún alumno en particular, se
  // reutilizan como punto de partida al armar la rutina de cualquiera.
  const cargarPlantillas = async () => {
    const { data } = await supabase.from("rutina_plantillas").select("*").order("created_at", { ascending: false });
    if (data) setPlantillas(data);
  };

  const usarPlantilla = (p) => {
    setNombreRutina(p.nombre || "");
    setDiaRutina(p.dia || "");
    setGrupoMuscularRutina(p.grupo_muscular || "");
    setCalentamientoGeneral(Array.isArray(p.calentamiento_general) ? p.calentamiento_general : []);
    setVueltaCalma(Array.isArray(p.vuelta_calma) ? p.vuelta_calma : []);
    setCardio(Array.isArray(p.cardio) ? p.cardio : []);
    setMetaPasos(p.meta_pasos || "");
    const ejerciciosPlantilla = Array.isArray(p.ejercicios) && p.ejercicios.length > 0
      ? p.ejercicios.map(ej => ({ ...ej, _dbId: undefined }))
      : [{ nombre: "", videoUrl: "", descansoDesde: 60, descansoHasta: 90, tempoBajada: "3", tempoPausa: "1", tempoSubida: "1", grupoSuperserie: "", seriesAproximacion: [{ reps: "8", pctDesde: "50", pctHasta: "60" }, { reps: "6", pctDesde: "70", pctHasta: "80" }, { reps: "3", pctDesde: "85", pctHasta: "90" }], seriesEfectivas: [{ reps: "10", rir: 2, tecnica: "normal" }] }];
    setEjercicios(ejerciciosPlantilla);
    setEjerciciosEliminados([]); setAproxExpandida({});
    setModoPlantilla(true);
    setModoDuplicar(false);
    setEditandoRutinaId(null);
    setMostrarPlantillas(false);
    setCreando(true);
    setTimeout(() => formRef.current?.scrollIntoView({ behavior: "smooth", block: "start" }), 100);
  };

  const guardarComoPlantilla = async () => {
    if (!nombrePlantillaNueva.trim()) { alert("Ponle un nombre a la plantilla."); return; }
    setGuardandoPlantilla(true);
    const ejerciciosLimpios = ejercicios.filter(ej => ej.nombre).map(ej => ({ ...ej, _dbId: undefined }));
    const { error } = await supabase.from("rutina_plantillas").insert({
      nombre: nombrePlantillaNueva.trim(),
      dia: diaRutina,
      grupo_muscular: grupoMuscularRutina || null,
      calentamiento_general: calentamientoGeneral,
      vuelta_calma: vueltaCalma,
      cardio: cardio,
      meta_pasos: metaPasos ? parseInt(metaPasos) : null,
      ejercicios: ejerciciosLimpios,
    });
    setGuardandoPlantilla(false);
    if (error) { alert("Error guardando la plantilla: " + error.message); return; }
    setGuardarPlantillaAbierto(false);
    setNombrePlantillaNueva("");
    cargarPlantillas();
  };

  const eliminarPlantilla = async (p) => {
    if (!confirm(`¿Eliminar la plantilla "${p.nombre}"? Esto no afecta ninguna rutina ya asignada a alumnos.`)) return;
    const { error } = await supabase.from("rutina_plantillas").delete().eq("id", p.id);
    if (error) { alert("Error eliminando la plantilla: " + error.message); return; }
    cargarPlantillas();
  };

  const cargarRutinas = async () => {
    if (!alumno?.id) return;
    const { data } = await supabase
      .from("rutinas")
      .select("*, ejercicios(*)")
      .eq("usuario_id", alumno.id)
      .order("created_at", { ascending: false });
    if (data) setRutinas(data);

    const { data: cargasData } = await supabase
      .from("registros_entreno")
      .select("*, ejercicios(nombre)")
      .eq("usuario_id", alumno.id)
      .order("creado_en", { ascending: false });
    if (cargasData) {
      const grouped = {};
      cargasData.forEach(c => {
        if (!grouped[c.ejercicio_id]) grouped[c.ejercicio_id] = [];
        grouped[c.ejercicio_id].push(c);
      });
      setCargas(grouped);
    }
    setLoading(false);
  };

  const agregarEjercicio = () => {
    setEjercicios([...ejercicios, { nombre: "", videoUrl: "", descansoDesde: 60, descansoHasta: 90, tempoBajada: "3", tempoPausa: "1", tempoSubida: "1", grupoSuperserie: "",
      seriesAproximacion: [{ reps: "8", pctDesde: "50", pctHasta: "60" }, { reps: "6", pctDesde: "70", pctHasta: "80" }, { reps: "3", pctDesde: "85", pctHasta: "90" }],
      seriesEfectivas: [{ reps: "10", rir: 2, tecnica: "normal" }] }]);
  };

  // Sube/baja un ejercicio en la lista -- así se "inserta" uno entremedio:
  // se agrega al final con "+ Agregar Ejercicio" y se sube con ↑ hasta la
  // posición deseada. El orden final se recalcula por posición al guardar.
  const moverEjercicio = (idx, direccion) => {
    const nuevoIdx = idx + direccion;
    if (nuevoIdx < 0 || nuevoIdx >= ejercicios.length) return;
    const upd = [...ejercicios];
    [upd[idx], upd[nuevoIdx]] = [upd[nuevoIdx], upd[idx]];
    setEjercicios(upd);
  };

  const eliminarEjercicio = (idx) => {
    if (ejercicios.length <= 1) { alert("La rutina debe tener al menos un ejercicio."); return; }
    const ej = ejercicios[idx];
    if (!confirm(`¿Eliminar "${ej.nombre || "este ejercicio"}" de la rutina?`)) return;
    if (ej._dbId) setEjerciciosEliminados(prev => [...prev, ej._dbId]);
    setEjercicios(ejercicios.filter((_, i) => i !== idx));
  };

  // Inserta un ejercicio nuevo y vacío justo después de la posición idx --
  // así se agrega uno "en el medio" en un solo clic, sin tener que crearlo al
  // final y subirlo a fuerza de flechas.
  const insertarEjercicioDespues = (idx) => {
    const nuevo = { nombre: "", videoUrl: "", descansoDesde: 60, descansoHasta: 90, tempoBajada: "3", tempoPausa: "1", tempoSubida: "1", grupoSuperserie: "",
      seriesAproximacion: [{ reps: "8", pctDesde: "50", pctHasta: "60" }, { reps: "6", pctDesde: "70", pctHasta: "80" }, { reps: "3", pctDesde: "85", pctHasta: "90" }],
      seriesEfectivas: [{ reps: "10", rir: 2, tecnica: "normal" }] };
    const upd = [...ejercicios];
    upd.splice(idx + 1, 0, nuevo);
    setEjercicios(upd);
  };

  const gruposSerie = { aproximacion: "seriesAproximacion", efectiva: "seriesEfectivas" };

  const agregarSerie = (ejIdx, tipo = "efectiva") => {
    const campo = gruposSerie[tipo];
    const upd = [...ejercicios];
    let nueva;
    if (tipo === "efectiva") {
      // Copia reps y RIR de la última serie efectiva existente, para no
      // tener que volver a tipear todo -- el coach ajusta a mano si quiere
      // un valor distinto en esta serie nueva.
      const anteriores = upd[ejIdx][campo];
      const ultima = anteriores[anteriores.length - 1];
      nueva = ultima ? { reps: ultima.reps, rir: ultima.rir, tecnica: "normal" } : { reps: "10", rir: 2, tecnica: "normal" };
    } else {
      nueva = { reps: "8", pctDesde: "", pctHasta: "" };
    }
    upd[ejIdx][campo].push(nueva);
    setEjercicios(upd);
  };

  const eliminarSerie = (ejIdx, tipo, sIdx) => {
    const campo = gruposSerie[tipo];
    const upd = [...ejercicios];
    upd[ejIdx][campo].splice(sIdx, 1);
    setEjercicios(upd);
  };

  const updateEj = (idx, campo, val) => {
    const upd = [...ejercicios];
    upd[idx][campo] = val;
    setEjercicios(upd);
  };

  const updateSerie = (ejIdx, tipo, sIdx, campo, val) => {
    const campoGrupo = gruposSerie[tipo];
    const upd = [...ejercicios];
    upd[ejIdx][campoGrupo][sIdx][campo] = val === "" ? val : (campo === "rir" ? parseInt(val) : val);
    setEjercicios(upd);
  };

  // Cambia la técnica de una serie efectiva y precarga sus valores por
  // defecto (ver DEFAULTS_TECNICA) solo en los campos que todavía no tengan
  // nada cargado -- así no pisa un valor que el coach ya haya editado antes
  // si va y vuelve entre técnicas.
  const cambiarTecnica = (ejIdx, sIdx, tecnica) => {
    const upd = [...ejercicios];
    const serie = { ...upd[ejIdx].seriesEfectivas[sIdx], tecnica };
    const defaults = DEFAULTS_TECNICA[tecnica] || {};
    Object.keys(defaults).forEach(k => { if (serie[k] === undefined || serie[k] === "") serie[k] = defaults[k]; });
    upd[ejIdx].seriesEfectivas[sIdx] = serie;
    setEjercicios(upd);
  };

  const guardarRutina = async () => {
    if (!nombreRutina) return;
    setGuardando(true);

    if (editandoRutinaId) {
      // Edición real: actualiza la rutina y sus ejercicios existentes, sin perder el historial de cargas
      const { error: errRutina } = await supabase
        .from("rutinas")
        .update({ nombre: nombreRutina, dia: diaRutina, grupo_muscular: grupoMuscularRutina || null, calentamiento_general: calentamientoGeneral, vuelta_calma: vueltaCalma, cardio: cardio, meta_pasos: metaPasos ? parseInt(metaPasos) : null })
        .eq("id", editandoRutinaId);
      if (errRutina) { alert("Error actualizando rutina: " + errRutina.message); setGuardando(false); return; }

      for (let i = 0; i < ejercicios.length; i++) {
        const ej = ejercicios[i];
        if (!ej.nombre) continue;
        const seriesCombinadas = [
          ...ej.seriesAproximacion.map(s => ({ ...s, tipo: "aproximacion" })),
          ...ej.seriesEfectivas.map(s => ({ ...s, tipo: "efectiva" })),
        ];
        const datosEjercicio = {
          nombre: ej.nombre,
          video_url: ej.videoUrl,
          descanso: parseInt(ej.descansoHasta) || 90,
          descanso_desde: parseInt(ej.descansoDesde) || null,
          descanso_hasta: parseInt(ej.descansoHasta) || null,
          tempo: `${ej.tempoBajada || "3"}-${ej.tempoPausa || "1"}-${ej.tempoSubida || "1"}`,
          grupo_superserie: ej.grupoSuperserie || null,
          orden: i,
          series: seriesCombinadas
        };
        if (ej._dbId) {
          // Ya existía: se actualiza en su lugar (mismo id, conserva el historial de cargas)
          const { error } = await supabase.from("ejercicios").update(datosEjercicio).eq("id", ej._dbId);
          if (error) { alert("Error actualizando ejercicio: " + error.message); setGuardando(false); return; }
        } else {
          // Ejercicio nuevo agregado durante la edición
          const { error } = await supabase.from("ejercicios").insert({ rutina_id: editandoRutinaId, ...datosEjercicio });
          if (error) { alert("Error agregando ejercicio: " + error.message); setGuardando(false); return; }
        }
      }

      // Ejercicios que el coach sacó de la rutina durante esta edición: se
      // borran recién ahora, al confirmar el guardado.
      for (const idBorrar of ejerciciosEliminados) {
        const { error: errDel } = await supabase.from("ejercicios").delete().eq("id", idBorrar);
        if (errDel) { alert("Error eliminando ejercicio: " + errDel.message); setGuardando(false); return; }
      }
    } else {
      // Rutina nueva o duplicada: se crea desde cero
      const { data: rutina, error: errRutina } = await supabase
        .from("rutinas")
        .insert({ usuario_id: alumno.id, nombre: nombreRutina, dia: diaRutina, grupo_muscular: grupoMuscularRutina || null, calentamiento_general: calentamientoGeneral, vuelta_calma: vueltaCalma, cardio: cardio, meta_pasos: metaPasos ? parseInt(metaPasos) : null })
        .select().single();
      if (errRutina) { alert("Error creando rutina: " + errRutina.message); setGuardando(false); return; }

      if (rutina) {
        for (let i = 0; i < ejercicios.length; i++) {
          const ej = ejercicios[i];
          if (ej.nombre) {
            const seriesCombinadas = [
              ...ej.seriesAproximacion.map(s => ({ ...s, tipo: "aproximacion" })),
              ...ej.seriesEfectivas.map(s => ({ ...s, tipo: "efectiva" })),
            ];
            await supabase.from("ejercicios").insert({
              rutina_id: rutina.id,
              nombre: ej.nombre,
              video_url: ej.videoUrl,
              descanso: parseInt(ej.descansoHasta) || 90,
              descanso_desde: parseInt(ej.descansoDesde) || null,
              descanso_hasta: parseInt(ej.descansoHasta) || null,
              tempo: `${ej.tempoBajada || "3"}-${ej.tempoPausa || "1"}-${ej.tempoSubida || "1"}`,
              grupo_superserie: ej.grupoSuperserie || null,
              orden: i,
              series: seriesCombinadas
            });
          }
        }
      }
    }

    setGuardando(false);
    setExito(true);
    setCreando(false);
    setModoDuplicar(false);
    setModoPlantilla(false);
    setGuardarPlantillaAbierto(false);
    setNombrePlantillaNueva("");
    setEditandoRutinaId(null);
    setNombreRutina("");
    setDiaRutina("");
    setGrupoMuscularRutina("");
    setCalentamientoGeneral([]);
    setVueltaCalma([]);
    setCardio([]);
    setMetaPasos("10000");
    setEjercicios([{ nombre: "", videoUrl: "", descansoDesde: 60, descansoHasta: 90, tempoBajada: "3", tempoPausa: "1", tempoSubida: "1", grupoSuperserie: "",
      seriesAproximacion: [{ reps: "8", pctDesde: "50", pctHasta: "60" }, { reps: "6", pctDesde: "70", pctHasta: "80" }, { reps: "3", pctDesde: "85", pctHasta: "90" }],
      seriesEfectivas: [{ reps: "10", rir: 2, tecnica: "normal" }] }]);
    setEjerciciosEliminados([]); setAproxExpandida({});
    cargarRutinas();
    cargarNombresEjercicios();
    setTimeout(() => setExito(false), 3000);
  };

  const cargarParaEditar = (rutina, modo) => {
    setNombreRutina(modo === "editar" ? rutina.nombre : rutina.nombre + " (copia)");
    setDiaRutina(rutina.dia || "");
    setGrupoMuscularRutina(rutina.grupo_muscular || "");
    setCalentamientoGeneral(Array.isArray(rutina.calentamiento_general) ? rutina.calentamiento_general : []);
    setVueltaCalma(Array.isArray(rutina.vuelta_calma) ? rutina.vuelta_calma : []);
    setCardio(Array.isArray(rutina.cardio) ? rutina.cardio : []);
    setMetaPasos(rutina.meta_pasos || "10000");
    const ejerciciosCargados = (rutina.ejercicios || []).slice().sort((a, b) => (a.orden || 0) - (b.orden || 0)).map(ej => {
      const series = Array.isArray(ej.series) ? ej.series : [];
      // Migración defensiva: si esta rutina todavía tiene series con tipo
      // "calentamiento" (de antes de fusionar esa sección con aproximación),
      // se tratan como aproximación acá, aunque la migración SQL en la base
      // de datos no se haya corrido todavía.
      const seriesAproximacion = series.filter(s => s.tipo === "aproximacion" || s.tipo === "calentamiento");
      const seriesEfectivas = series.filter(s => !s.tipo || s.tipo === "efectiva");
      return {
        _dbId: modo === "editar" ? ej.id : undefined,
        nombre: ej.nombre || "",
        videoUrl: ej.video_url || "",
        descansoDesde: ej.descanso_desde || 60,
        descansoHasta: ej.descanso_hasta || ej.descanso || 90,
        tempoBajada: (ej.tempo || "3-1-1").split("-")[0] || "3",
        tempoPausa: (ej.tempo || "3-1-1").split("-")[1] || "1",
        tempoSubida: (ej.tempo || "3-1-1").split("-")[2] || "1",
        grupoSuperserie: ej.grupo_superserie || "",
        seriesAproximacion,
        seriesEfectivas: seriesEfectivas.length > 0 ? seriesEfectivas : [{ reps: "10", rir: 2, tecnica: "normal" }],
      };
    });
    setEjercicios(ejerciciosCargados.length > 0 ? ejerciciosCargados : [
      { nombre: "", videoUrl: "", descansoDesde: 60, descansoHasta: 90, tempoBajada: "3", tempoPausa: "1", tempoSubida: "1", grupoSuperserie: "",
        seriesAproximacion: [{ reps: "8", pctDesde: "50", pctHasta: "60" }, { reps: "6", pctDesde: "70", pctHasta: "80" }, { reps: "3", pctDesde: "85", pctHasta: "90" }],
        seriesEfectivas: [{ reps: "10", rir: 2, tecnica: "normal" }] }
    ]);
    setEjerciciosEliminados([]); setAproxExpandida({});
    setModoDuplicar(modo === "duplicar");
    setModoPlantilla(false);
    setEditandoRutinaId(modo === "editar" ? rutina.id : null);
    setCreando(true);
    // En modo "editar" el formulario se abre como acordeón debajo de la misma
    // rutina en la lista (ya está a la vista) -- el scroll al fondo de la
    // página solo tiene sentido para nueva rutina / duplicar / plantilla.
    if (modo !== "editar") {
      setTimeout(() => formRef.current?.scrollIntoView({ behavior: "smooth", block: "start" }), 100);
    }
  };

  const inputStyle = { background: theme.surface, border: `1px solid ${theme.border}`, borderRadius: 8, padding: "8px 10px", color: theme.text, fontSize: 13, outline: "none", width: "100%", boxSizing: "border-box" };
  const smallInput = { ...inputStyle, width: 60, textAlign: "center", padding: "6px 4px" };

  // Contenido del formulario de rutina (crear/editar/duplicar/plantilla), extraído
  // a una variable para poder mostrarlo en dos lugares: como acordeón debajo de la
  // rutina que se está editando (dentro de "RUTINAS ASIGNADAS"), o al fondo de la
  // página para el caso de "+ Crear Nueva Rutina" / plantilla / duplicar.
  const formularioContenido = (
    <>
          <div style={{ fontSize:13, fontWeight:800, color:theme.accent, marginBottom:4 }}>
            {editandoRutinaId ? "✏️ EDITANDO RUTINA" : modoPlantilla ? "🗂️ DESDE PLANTILLA" : modoDuplicar ? "⧉ DUPLICANDO RUTINA" : "NUEVA RUTINA"}
          </div>
          {editandoRutinaId && <div style={{ fontSize:11, color:theme.muted, marginBottom:10 }}>Estás editando esta rutina directamente. Los cambios se guardan sobre la misma rutina y se conserva el historial de cargas ya registrado.</div>}
          {modoDuplicar && <div style={{ fontSize:11, color:theme.muted, marginBottom:10 }}>Ajustá lo que necesites (nombre, series, pesos, ejercicios) y guardá. Se creará como una rutina nueva; la original no se modifica.</div>}
          {modoPlantilla && <div style={{ fontSize:11, color:theme.muted, marginBottom:10 }}>Cargada desde una plantilla. Ajusta lo que necesites para este alumno (ejercicios, series, pesos) y guarda -- se crea como una rutina nueva; la plantilla no se modifica.</div>}

          <div style={{ marginBottom:10 }}>
            <div style={{ fontSize:11, color:theme.muted, marginBottom:4 }}>Nombre de la rutina</div>
            <input style={inputStyle} placeholder="Ej: Push A - Lunes" value={nombreRutina} onChange={e => setNombreRutina(e.target.value)} />
          </div>

          <div style={{ marginBottom:16 }}>
            <div style={{ fontSize:11, color:theme.muted, marginBottom:4 }}>Día</div>
            <select style={inputStyle} value={diaRutina} onChange={e => setDiaRutina(e.target.value)}>
              <option value="">Selecciona...</option>
              {["Lunes","Martes","Miércoles","Jueves","Viernes","Sábado","Domingo"].map(d => <option key={d} value={d}>{d}</option>)}
            </select>
          </div>

          <div style={{ marginBottom:16 }}>
            <div style={{ fontSize:11, color:theme.muted, marginBottom:4 }}>Grupo muscular</div>
            <div style={{ display:"flex", alignItems:"center", gap:10 }}>
              <input style={{ ...inputStyle, flex:1 }} placeholder="Ej: Femoral" value={grupoMuscularRutina}
                onChange={e => setGrupoMuscularRutina(e.target.value)} list="lista-grupos-musculares" />
              <datalist id="lista-grupos-musculares">
                {nombresGruposMuscularesUsados.map(n => <option key={n} value={n} />)}
              </datalist>
              <ImagenGrupoMuscular nombre={grupoMuscularRutina} mapa={mapaImagenesGrupoMuscular} size={44} />
              <BotonSubirImagenGrupoMuscular nombre={grupoMuscularRutina} onSubida={recargarMapaImagenesGrupoMuscular} />
            </div>
          </div>

          <div style={{ marginBottom:16 }}>
            <div style={{ fontSize:11, color:theme.muted, marginBottom:6 }}>Calentamiento general de la sesión</div>
            <div style={{ display:"flex", gap:6, marginBottom:10, flexWrap:"wrap" }}>
              {[["piernas","🦵 Piernas"],["push","💪 Push"],["pull","🎯 Pull"]].map(([key,label]) => (
                <button key={key} onClick={() => setCalentamientoGeneral(CALENTAMIENTO_DEFAULTS[key].map(m => ({...m})))}
                  style={{ background:theme.surface, border:`1px solid ${theme.border}`, borderRadius:8, padding:"6px 12px", color:theme.text, fontSize:12, cursor:"pointer" }}>{label}</button>
              ))}
              {calentamientoGeneral.length > 0 && (
                <button onClick={() => setCalentamientoGeneral([])} style={{ background:"transparent", border:`1px solid ${theme.danger}66`, borderRadius:8, padding:"6px 12px", color:theme.danger, fontSize:12, cursor:"pointer" }}>Quitar</button>
              )}
            </div>
            {calentamientoGeneral.map((m, i) => (
              <div key={i} style={{ background:theme.card, borderRadius:8, padding:8, marginBottom:8 }}>
                <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 20px", gap:6, alignItems:"center", marginBottom:6 }}>
                  <input style={inputStyle} placeholder="Nombre" value={m.nombre} onChange={e => { const c=[...calentamientoGeneral]; c[i]={...c[i], nombre:e.target.value}; setCalentamientoGeneral(c); }} />
                  <input style={inputStyle} placeholder="Detalle" value={m.detalle} onChange={e => { const c=[...calentamientoGeneral]; c[i]={...c[i], detalle:e.target.value}; setCalentamientoGeneral(c); }} />
                  <span onClick={() => setCalentamientoGeneral(calentamientoGeneral.filter((_,idx)=>idx!==i))} style={{ cursor:"pointer", color:theme.danger, fontSize:14, textAlign:"center" }}>×</span>
                </div>
                <div style={{ display:"flex", alignItems:"flex-start", gap:10, flexWrap:"wrap" }}>
                  <ImagenReferenciaEjercicio nombre={m.nombre} mapa={mapaImagenes} size={64} />
                  <BotonSubirImagenEjercicio nombre={m.nombre} onSubida={({ normalizado, url }) => setMapaImagenes(prev => ({ ...prev, [normalizado]: { ...(prev[normalizado]||{}), url } }))} />
                  <EditorResenaEjercicio nombre={m.nombre} mapa={mapaImagenes} onGuardado={({ normalizado, resena }) => setMapaImagenes(prev => ({ ...prev, [normalizado]: { ...(prev[normalizado]||{}), resena } }))} />
                </div>
              </div>
            ))}
            <button onClick={() => setCalentamientoGeneral([...calentamientoGeneral, { nombre:"", detalle:"" }])} style={{ background:"transparent", border:`1px dashed ${theme.border}`, borderRadius:6, padding:"4px 10px", color:theme.muted, fontSize:11, cursor:"pointer" }}>+ Movimiento</button>
          </div>

          <div style={{ fontSize:12, fontWeight:800, color:theme.text, marginBottom:10 }}>EJERCICIOS</div>

          {ejercicios.map((ej, ejIdx) => (
            <Fragment key={ejIdx}>
            <div style={{ background:theme.surface, borderRadius:10, padding:12, marginBottom:12, border: ej.grupoSuperserie ? `1px solid ${theme.gold}66` : "1px solid transparent" }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:8, gap:8 }}>
                <div style={{ fontSize:11, fontWeight:700, color:theme.accent }}>
                  Ejercicio {ejIdx + 1}
                  {ej.grupoSuperserie && <span style={{ marginLeft:8, color:theme.gold, background:`${theme.gold}18`, border:`1px solid ${theme.gold}44`, borderRadius:6, padding:"2px 6px", fontSize:10 }}>🔗 Grupo {ej.grupoSuperserie}</span>}
                </div>
                <div style={{ display:"flex", gap:4, alignItems:"center", flexShrink:0 }}>
                  <button onClick={() => moverEjercicio(ejIdx, -1)} disabled={ejIdx === 0}
                    style={{ background:theme.card, border:`1px solid ${theme.border}`, borderRadius:6, width:26, height:26, color: ejIdx === 0 ? theme.muted : theme.text, fontSize:12, cursor: ejIdx === 0 ? "default" : "pointer", opacity: ejIdx === 0 ? 0.4 : 1 }} title="Subir">↑</button>
                  <button onClick={() => moverEjercicio(ejIdx, 1)} disabled={ejIdx === ejercicios.length - 1}
                    style={{ background:theme.card, border:`1px solid ${theme.border}`, borderRadius:6, width:26, height:26, color: ejIdx === ejercicios.length - 1 ? theme.muted : theme.text, fontSize:12, cursor: ejIdx === ejercicios.length - 1 ? "default" : "pointer", opacity: ejIdx === ejercicios.length - 1 ? 0.4 : 1 }} title="Bajar">↓</button>
                  <button onClick={() => eliminarEjercicio(ejIdx)}
                    style={{ background:`${theme.danger}18`, border:`1px solid ${theme.danger}44`, borderRadius:6, padding:"5px 8px", color:theme.danger, fontSize:11, fontWeight:700, cursor:"pointer" }} title="Eliminar ejercicio">× Eliminar</button>
                </div>
              </div>

              <div style={{ marginBottom:8 }}>
                <div style={{ fontSize:10, color:theme.muted, marginBottom:3 }}>Nombre</div>
                <input style={{ ...inputStyle, marginBottom:8 }} placeholder="Ej: Press Banca" value={ej.nombre} onChange={e => updateEj(ejIdx, "nombre", e.target.value)} list="lista-ejercicios" />
                <datalist id="lista-ejercicios">
                  {nombresEjerciciosUsados.map(n => <option key={n} value={n} />)}
                </datalist>
                <div style={{ display:"flex", alignItems:"flex-start", gap:10, flexWrap:"wrap" }}>
                  <ImagenReferenciaEjercicio nombre={ej.nombre} mapa={mapaImagenes} size={72} />
                  <BotonSubirImagenEjercicio nombre={ej.nombre} onSubida={({ normalizado, url }) => setMapaImagenes(prev => ({ ...prev, [normalizado]: { ...(prev[normalizado]||{}), url } }))} />
                  <EditorResenaEjercicio nombre={ej.nombre} mapa={mapaImagenes} onGuardado={({ normalizado, resena }) => setMapaImagenes(prev => ({ ...prev, [normalizado]: { ...(prev[normalizado]||{}), resena } }))} />
                </div>
              </div>

              <div style={{ marginBottom:10 }}>
                <div style={{ fontSize:10, color:theme.muted, marginBottom:3 }}>Descanso entre series (segundos)</div>
                <div style={{ display:"flex", gap:8, alignItems:"center" }}>
                  <input style={{ ...inputStyle, width:80 }} type="number" placeholder="60" value={ej.descansoDesde} onChange={e => updateEj(ejIdx, "descansoDesde", e.target.value)} />
                  <span style={{ color:theme.muted, fontSize:12 }}>a</span>
                  <input style={{ ...inputStyle, width:80 }} type="number" placeholder="90" value={ej.descansoHasta} onChange={e => updateEj(ejIdx, "descansoHasta", e.target.value)} />
                  <span style={{ color:theme.muted, fontSize:11 }}>segundos</span>
                </div>
              </div>

              <div style={{ marginBottom:10 }}>
                <div style={{ fontSize:10, color:theme.muted, marginBottom:3 }}>Tempo (bajada · pausa · subida)</div>
                <div style={{ display:"flex", gap:6, alignItems:"center" }}>
                  <input style={{ ...inputStyle, width:44, textAlign:"center", padding:"8px 2px" }} value={ej.tempoBajada} onChange={e => updateEj(ejIdx, "tempoBajada", e.target.value)} />
                  <span style={{ color:theme.muted, fontSize:12 }}>-</span>
                  <input style={{ ...inputStyle, width:44, textAlign:"center", padding:"8px 2px" }} value={ej.tempoPausa} onChange={e => updateEj(ejIdx, "tempoPausa", e.target.value)} />
                  <span style={{ color:theme.muted, fontSize:12 }}>-</span>
                  <input style={{ ...inputStyle, width:44, textAlign:"center", padding:"8px 2px" }} value={ej.tempoSubida} onChange={e => updateEj(ejIdx, "tempoSubida", e.target.value)} />
                  <span style={{ color:theme.muted, fontSize:11 }}>segundos</span>
                </div>
              </div>

              <div style={{ marginBottom:10 }}>
                <div style={{ fontSize:10, color:theme.muted, marginBottom:3 }}>Grupo (superserie / biserie) — opcional</div>
                <input style={{ ...inputStyle, width:70 }} placeholder="Ej: A" maxLength={3}
                  value={ej.grupoSuperserie || ""} onChange={e => updateEj(ejIdx, "grupoSuperserie", e.target.value.toUpperCase())} />
                <div style={{ fontSize:10, color:theme.muted, marginTop:4, lineHeight:1.4 }}>Ejercicios con la misma letra, uno debajo del otro en la lista, se hacen en superserie/biserie: sin descanso entre ellos, el descanso se aplica recién al cerrar la ronda completa.</div>
              </div>

              {/* Aproximación (reemplaza al antiguo calentamiento específico del
                  ejercicio: acá se trabaja en % del peso de la primera serie
                  efectiva, no en RIR. Colapsada por defecto salvo en el primer
                  ejercicio de la rutina, porque rara vez se usa en los demás. */}
              {(() => {
                const expandidoAprox = aproxExpandida[ejIdx] ?? (ejIdx === 0);
                return (
                  <div style={{ marginBottom:12 }}>
                    <div onClick={() => setAproxExpandida(prev => ({ ...prev, [ejIdx]: !expandidoAprox }))}
                      style={{ display:"flex", alignItems:"center", gap:6, cursor:"pointer", marginBottom: expandidoAprox ? 6 : 0 }}>
                      <span style={{ fontSize:10, fontWeight:700, color:"#B0C4DE" }}>📊 APROXIMACIÓN</span>
                      <span style={{ fontSize:10, color:"#B0C4DE" }}>{expandidoAprox ? "▲" : ej.seriesAproximacion.length > 0 ? `▼ (${ej.seriesAproximacion.length})` : "+"}</span>
                    </div>
                    {expandidoAprox && (
                      <>
                        <div style={{ display:"grid", gridTemplateColumns:"30px 1fr 46px 10px 46px 20px", gap:4, marginBottom:6 }}>
                          {["#","REPS","% DESDE","","% HASTA",""].map((h,i) => <span key={i} style={{ fontSize:9, color:theme.muted, textAlign:"center" }}>{h}</span>)}
                        </div>
                        {ej.seriesAproximacion.map((s, sIdx) => (
                          <div key={sIdx} style={{ display:"grid", gridTemplateColumns:"30px 1fr 46px 10px 46px 20px", gap:4, alignItems:"center", marginBottom:6, background:"#B0C4DE14", border:"1px solid #B0C4DE33", borderRadius:8, padding:"4px 4px" }}>
                            <div style={{ textAlign:"center", fontSize:11, color:"#B0C4DE", fontWeight:700 }}>{sIdx+1}</div>
                            <input style={inputStyle} placeholder="8" value={s.reps} onChange={e => updateSerie(ejIdx, "aproximacion", sIdx, "reps", e.target.value)} />
                            <input style={inputStyle} type="number" placeholder="50" value={s.pctDesde} onChange={e => updateSerie(ejIdx, "aproximacion", sIdx, "pctDesde", e.target.value)} />
                            <span style={{ color:theme.muted, fontSize:10, textAlign:"center" }}>-</span>
                            <input style={inputStyle} type="number" placeholder="60" value={s.pctHasta} onChange={e => updateSerie(ejIdx, "aproximacion", sIdx, "pctHasta", e.target.value)} />
                            <span onClick={() => eliminarSerie(ejIdx, "aproximacion", sIdx)} style={{ cursor:"pointer", color:theme.danger, fontSize:14, textAlign:"center" }}>×</span>
                          </div>
                        ))}
                        <button onClick={() => agregarSerie(ejIdx, "aproximacion")} style={{ background:"transparent", border:"1px dashed #B0C4DE66", borderRadius:6, padding:"4px 10px", color:"#B0C4DE", fontSize:11, cursor:"pointer", marginTop:2 }}>+ Serie de aproximación</button>
                        <div style={{ fontSize:10, color:theme.muted, marginTop:6, lineHeight:1.4 }}>% sobre el peso de la primera serie efectiva. El alumno ve el kg sugerido calculado automáticamente (según su carga previa) y puede corregirlo.</div>
                      </>
                    )}
                  </div>
                );
              })()}

              {/* Efectivas */}
              <div style={{ fontSize:10, fontWeight:700, color:theme.accentLight, marginBottom:6 }}>💪 SERIES EFECTIVAS</div>
              <div style={{ display:"grid", gridTemplateColumns:"30px 1fr 60px 50px 20px", gap:4, marginBottom:6 }}>
                {["#","REPS","RIR","TÉC.",""].map((h,i) => <span key={i} style={{ fontSize:9, color:theme.muted, textAlign:"center" }}>{h}</span>)}
              </div>
              {ej.seriesEfectivas.map((s, sIdx) => (
                <div key={sIdx}>
                <div style={{ display:"grid", gridTemplateColumns:"30px 1fr 60px 50px 20px", gap:4, alignItems:"center", marginBottom:4, background:`${theme.accent}14`, border:`1px solid ${theme.accent}33`, borderRadius:8, padding:"4px 4px" }}>
                  <div style={{ textAlign:"center", fontSize:11, color:theme.accentLight, fontWeight:700 }}>{sIdx+1}</div>
                  <input style={inputStyle} placeholder="10" value={s.reps} onChange={e => updateSerie(ejIdx, "efectiva", sIdx, "reps", e.target.value)} />
                  <select style={{ ...inputStyle, padding:"6px 4px" }} value={s.rir} onChange={e => updateSerie(ejIdx, "efectiva", sIdx, "rir", e.target.value)}>
                    <option value={0}>Fallo</option>
                    <option value={1}>RIR 1</option>
                    <option value={2}>RIR 2</option>
                    <option value={3}>RIR 3</option>
                  </select>
                  <select value={s.tecnica || "normal"} onChange={e => cambiarTecnica(ejIdx, sIdx, e.target.value)}
                    title="Técnica de intensidad" style={{ ...inputStyle, padding:"4px 1px", fontSize:9 }}>
                    <option value="normal">—</option>
                    <option value="dropset">DS</option>
                    <option value="isometrica">ISO</option>
                    <option value="restpause">RP</option>
                  </select>
                  {ej.seriesEfectivas.length > 1 && (
                    <span onClick={() => eliminarSerie(ejIdx, "efectiva", sIdx)} style={{ cursor:"pointer", color:theme.danger, fontSize:14, textAlign:"center" }}>×</span>
                  )}
                </div>
                {s.tecnica === "dropset" && (
                  <div style={{ display:"flex", gap:5, alignItems:"center", marginBottom:6, marginTop:-2, paddingLeft:4, flexWrap:"wrap" }}>
                    <span style={{ fontSize:9, color:COLORES_TECNICA.dropset, fontWeight:800 }}>⚡ DROPSET</span>
                    <input type="number" value={s.dropsetCantidad ?? "2"} onChange={e => updateSerie(ejIdx, "efectiva", sIdx, "dropsetCantidad", e.target.value)}
                      title="Cantidad de drops" style={{ ...inputStyle, width:38, padding:"3px 2px", fontSize:11 }} />
                    <span style={{ fontSize:9, color:theme.muted }}>drops ·</span>
                    <input type="number" value={s.dropsetPct ?? "25"} onChange={e => updateSerie(ejIdx, "efectiva", sIdx, "dropsetPct", e.target.value)}
                      title="% de bajada por drop" style={{ ...inputStyle, width:38, padding:"3px 2px", fontSize:11 }} />
                    <span style={{ fontSize:9, color:theme.muted }}>% c/u ·</span>
                    <div style={{ display:"flex", gap:3 }}>
                      {[["fallo","Fallo"],["fijas","Fijas"]].map(([v,l]) => (
                        <span key={v} onClick={() => updateSerie(ejIdx, "efectiva", sIdx, "dropsetRepsModo", v)}
                          style={{ fontSize:9, fontWeight:700, padding:"3px 6px", borderRadius:5, cursor:"pointer",
                            background: (s.dropsetRepsModo || "fallo") === v ? theme.accent : "transparent",
                            border: `1px solid ${(s.dropsetRepsModo || "fallo") === v ? theme.accentLight : theme.border}`,
                            color: (s.dropsetRepsModo || "fallo") === v ? "#fff" : theme.muted }}>{l}</span>
                      ))}
                    </div>
                  </div>
                )}
                {s.tecnica === "isometrica" && (
                  <div style={{ display:"flex", gap:5, alignItems:"center", marginBottom:6, marginTop:-2, paddingLeft:4, flexWrap:"wrap" }}>
                    <span style={{ fontSize:9, color:COLORES_TECNICA.isometrica, fontWeight:800 }}>⚡ PAUSA ISOMÉTRICA</span>
                    <input type="number" value={s.isoSegundos ?? "4"} onChange={e => updateSerie(ejIdx, "efectiva", sIdx, "isoSegundos", e.target.value)}
                      title="Segundos de pausa abajo" style={{ ...inputStyle, width:38, padding:"3px 2px", fontSize:11 }} />
                    <span style={{ fontSize:9, color:theme.muted }}>seg abajo · subida explosiva</span>
                  </div>
                )}
                {s.tecnica === "restpause" && (
                  <div style={{ display:"flex", gap:5, alignItems:"center", marginBottom:6, marginTop:-2, paddingLeft:4, flexWrap:"wrap" }}>
                    <span style={{ fontSize:9, color:COLORES_TECNICA.restpause, fontWeight:800 }}>⚡ REST-PAUSE</span>
                    <input type="number" value={s.rpCantidad ?? "2"} onChange={e => updateSerie(ejIdx, "efectiva", sIdx, "rpCantidad", e.target.value)}
                      title="Cantidad de pausas" style={{ ...inputStyle, width:38, padding:"3px 2px", fontSize:11 }} />
                    <span style={{ fontSize:9, color:theme.muted }}>pausas ·</span>
                    <input type="number" value={s.rpSegundos ?? "15"} onChange={e => updateSerie(ejIdx, "efectiva", sIdx, "rpSegundos", e.target.value)}
                      title="Segundos por pausa" style={{ ...inputStyle, width:38, padding:"3px 2px", fontSize:11 }} />
                    <span style={{ fontSize:9, color:theme.muted }}>seg c/u</span>
                  </div>
                )}
                </div>
              ))}
              <button onClick={() => agregarSerie(ejIdx, "efectiva")} style={{ background:"transparent", border:`1px dashed ${theme.border}`, borderRadius:6, padding:"4px 10px", color:theme.muted, fontSize:11, cursor:"pointer", marginTop:4 }}>+ Serie efectiva</button>
            </div>
            <button onClick={() => insertarEjercicioDespues(ejIdx)}
              style={{ background:"transparent", border:`1px dashed ${theme.border}`, borderRadius:6, padding:"5px 10px", color:theme.muted, fontSize:11, cursor:"pointer", width:"100%", marginBottom:12 }}>+ Insertar ejercicio aquí</button>
            </Fragment>
          ))}

          <button onClick={agregarEjercicio} style={{ background:"transparent", border:`1px dashed ${theme.accent}`, borderRadius:8, padding:"8px", color:theme.accentLight, fontSize:12, cursor:"pointer", width:"100%", marginBottom:12 }}>+ Agregar Ejercicio</button>

          <div style={{ marginBottom:16 }}>
            <div style={{ fontSize:11, color:theme.muted, marginBottom:6 }}>🏃 Cardio y pasos</div>
            <div style={{ marginBottom:10 }}>
              <div style={{ fontSize:10, color:theme.muted, marginBottom:3 }}>Meta de pasos diaria (opcional)</div>
              <input type="number" style={{ ...inputStyle, maxWidth:140 }} placeholder="Ej: 8000" value={metaPasos} onChange={e => setMetaPasos(e.target.value)} />
            </div>
            {cardio.map((c, i) => (
              <div key={i} style={{ background:theme.card, borderRadius:8, padding:8, marginBottom:8 }}>
                <div style={{ display:"grid", gridTemplateColumns:"1fr 20px", gap:6, alignItems:"center", marginBottom:6 }}>
                  <input style={inputStyle} placeholder="Tipo (ej: Trote, Bicicleta)" value={c.tipo} list="lista-tipos-cardio" onChange={e => { const cc=[...cardio]; cc[i]={...cc[i], tipo:e.target.value}; setCardio(cc); }} />
                  <span onClick={() => setCardio(cardio.filter((_,idx)=>idx!==i))} style={{ cursor:"pointer", color:theme.danger, fontSize:14, textAlign:"center" }}>×</span>
                </div>
                <div style={{ marginBottom:6 }}>
                  <div style={{ fontSize:10, color:theme.muted, marginBottom:2 }}>Duración (min)</div>
                  <input type="number" style={inputStyle} placeholder="20" value={c.duracionMin} onChange={e => { const cc=[...cardio]; cc[i]={...cc[i], duracionMin:e.target.value}; setCardio(cc); }} />
                </div>
                <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:6, marginBottom:6 }}>
                  <div>
                    <div style={{ fontSize:10, color:theme.muted, marginBottom:2 }}>% FC mín (quema grasa)</div>
                    <input type="number" style={inputStyle} placeholder="60" value={c.fcMinPct || ""} onChange={e => { const cc=[...cardio]; cc[i]={...cc[i], fcMinPct:e.target.value}; setCardio(cc); }} />
                  </div>
                  <div>
                    <div style={{ fontSize:10, color:theme.muted, marginBottom:2 }}>% FC máx</div>
                    <input type="number" style={inputStyle} placeholder="70" value={c.fcMaxPct || ""} onChange={e => { const cc=[...cardio]; cc[i]={...cc[i], fcMaxPct:e.target.value}; setCardio(cc); }} />
                  </div>
                </div>
                {(c.fcMinPct || c.fcMaxPct) && (
                  alumno?.edad
                    ? (() => {
                        const fcMaxTeorica = 220 - parseInt(alumno.edad);
                        const lpmMin = c.fcMinPct ? Math.round(fcMaxTeorica * (parseFloat(c.fcMinPct) / 100)) : null;
                        const lpmMax = c.fcMaxPct ? Math.round(fcMaxTeorica * (parseFloat(c.fcMaxPct) / 100)) : null;
                        return (
                          <div style={{ fontSize:10, color:theme.accentLight, marginBottom:6 }}>
                            ≈ {lpmMin || "—"}{lpmMax ? `-${lpmMax}` : ""} lpm (según edad: {alumno.edad} años, FC máx teórica {fcMaxTeorica})
                          </div>
                        );
                      })()
                    : <div style={{ fontSize:10, color:theme.warning, marginBottom:6 }}>⚠️ Este alumno no tiene edad cargada en su ficha — no se puede calcular el rango de lpm.</div>
                )}
                <input style={inputStyle} placeholder="Notas (opcional)" value={c.notas || ""} onChange={e => { const cc=[...cardio]; cc[i]={...cc[i], notas:e.target.value}; setCardio(cc); }} />
              </div>
            ))}
            <datalist id="lista-tipos-cardio">
              {["Trote","Caminata","Bicicleta","Elíptica","Remo","Natación","Escaladora"].map(t => <option key={t} value={t} />)}
            </datalist>
            <button onClick={() => setCardio([...cardio, { tipo:"", duracionMin:"20", fcMinPct:"60", fcMaxPct:"70", notas:"" }])} style={{ background:"transparent", border:`1px dashed ${theme.border}`, borderRadius:6, padding:"4px 10px", color:theme.muted, fontSize:11, cursor:"pointer" }}>+ Cardio</button>
          </div>

          <div style={{ marginBottom:16 }}>
            <div style={{ fontSize:11, color:theme.muted, marginBottom:6 }}>🧘 Vuelta a la calma (estiramientos post-sesión)</div>
            <div style={{ display:"flex", gap:6, marginBottom:10, flexWrap:"wrap" }}>
              {[["piernas","🦵 Piernas"],["push","💪 Push"],["pull","🎯 Pull"]].map(([key,label]) => (
                <button key={key} onClick={() => setVueltaCalma(VUELTA_CALMA_DEFAULTS[key].map(m => ({...m})))}
                  style={{ background:theme.surface, border:`1px solid ${theme.border}`, borderRadius:8, padding:"6px 12px", color:theme.text, fontSize:12, cursor:"pointer" }}>{label}</button>
              ))}
              {vueltaCalma.length > 0 && (
                <button onClick={() => setVueltaCalma([])} style={{ background:"transparent", border:`1px solid ${theme.danger}66`, borderRadius:8, padding:"6px 12px", color:theme.danger, fontSize:12, cursor:"pointer" }}>Quitar</button>
              )}
            </div>
            {vueltaCalma.map((m, i) => (
              <div key={i} style={{ background:theme.card, borderRadius:8, padding:8, marginBottom:8 }}>
                <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 20px", gap:6, alignItems:"center", marginBottom:6 }}>
                  <input style={inputStyle} placeholder="Nombre" value={m.nombre} onChange={e => { const c=[...vueltaCalma]; c[i]={...c[i], nombre:e.target.value}; setVueltaCalma(c); }} />
                  <input style={inputStyle} placeholder="Detalle" value={m.detalle} onChange={e => { const c=[...vueltaCalma]; c[i]={...c[i], detalle:e.target.value}; setVueltaCalma(c); }} />
                  <span onClick={() => setVueltaCalma(vueltaCalma.filter((_,idx)=>idx!==i))} style={{ cursor:"pointer", color:theme.danger, fontSize:14, textAlign:"center" }}>×</span>
                </div>
                <div style={{ display:"flex", alignItems:"flex-start", gap:10, flexWrap:"wrap" }}>
                  <ImagenReferenciaEjercicio nombre={m.nombre} mapa={mapaImagenes} size={64} />
                  <BotonSubirImagenEjercicio nombre={m.nombre} onSubida={({ normalizado, url }) => setMapaImagenes(prev => ({ ...prev, [normalizado]: { ...(prev[normalizado]||{}), url } }))} />
                  <EditorResenaEjercicio nombre={m.nombre} mapa={mapaImagenes} onGuardado={({ normalizado, resena }) => setMapaImagenes(prev => ({ ...prev, [normalizado]: { ...(prev[normalizado]||{}), resena } }))} />
                </div>
              </div>
            ))}
            <button onClick={() => setVueltaCalma([...vueltaCalma, { nombre:"", detalle:"" }])} style={{ background:"transparent", border:`1px dashed ${theme.border}`, borderRadius:6, padding:"4px 10px", color:theme.muted, fontSize:11, cursor:"pointer" }}>+ Estiramiento</button>
          </div>

          {!guardarPlantillaAbierto ? (
            <button onClick={() => { setNombrePlantillaNueva(nombreRutina || ""); setGuardarPlantillaAbierto(true); }}
              style={{ background:"transparent", border:`1px dashed ${theme.border}`, borderRadius:8, padding:"8px", color:theme.muted, fontSize:12, cursor:"pointer", width:"100%", marginBottom:12 }}>💾 Guardar como plantilla</button>
          ) : (
            <div style={{ background:theme.surface, borderRadius:8, padding:10, marginBottom:12 }}>
              <div style={{ fontSize:11, color:theme.muted, marginBottom:6 }}>Nombre de la plantilla (ej: "Cuádriceps Lunes")</div>
              <div style={{ display:"flex", gap:8 }}>
                <input style={inputStyle} value={nombrePlantillaNueva} onChange={e => setNombrePlantillaNueva(e.target.value)} placeholder="Nombre de la plantilla" />
                <button onClick={guardarComoPlantilla} disabled={guardandoPlantilla} style={{ background:theme.accent, border:"none", borderRadius:8, padding:"9px 14px", color:"#fff", fontSize:12, fontWeight:700, cursor:"pointer", whiteSpace:"nowrap" }}>{guardandoPlantilla ? "Guardando..." : "Guardar"}</button>
                <button onClick={() => setGuardarPlantillaAbierto(false)} style={{ background:"transparent", border:`1px solid ${theme.border}`, borderRadius:8, padding:"9px 12px", color:theme.muted, fontSize:12, cursor:"pointer" }}>×</button>
              </div>
            </div>
          )}

          <div style={{ display:"flex", gap:8 }}>
            <Btn onClick={guardarRutina} style={{ background:theme.success }}>{guardando ? "Guardando..." : editandoRutinaId ? "✓ Guardar Cambios" : "✓ Guardar Rutina"}</Btn>
            <Btn variant="ghost" onClick={() => { setCreando(false); setModoDuplicar(false); setModoPlantilla(false); setGuardarPlantillaAbierto(false); setEditandoRutinaId(null); }}>Cancelar</Btn>
          </div>
    </>
  );

  return (
    <div>
      {exito && (
        <Card style={{ textAlign:"center", padding:16, marginBottom:14, background:`${theme.success}18`, border:`1px solid ${theme.success}44` }}>
          <div style={{ fontSize:20, marginBottom:4 }}>✅</div>
          <div style={{ fontSize:13, fontWeight:700, color:theme.success }}>Rutina guardada correctamente</div>
        </Card>
      )}

      <Card style={{ marginBottom:14 }}>
        <div style={{ fontSize:12, color:theme.muted, marginBottom:8 }}>📅 FECHA DE INICIO DEL PLAN</div>
        <div style={{ fontSize:11, color:theme.muted, marginBottom:10 }}>El conteo de las 4 semanas del ciclo arranca desde acá (por ejemplo, siempre un lunes). Si la dejas vacía, arranca automáticamente desde el primer registro del alumno.</div>
        <div style={{ display:"flex", gap:8, alignItems:"center" }}>
          <input type="date" value={fechaInicioPlan} onChange={e => setFechaInicioPlan(e.target.value)}
            style={{ flex:1, background:theme.bg, border:`1px solid ${theme.border}`, borderRadius:8, padding:"9px 11px", color:theme.text, fontSize:13, outline:"none" }} />
          <button onClick={guardarFechaInicioPlan} disabled={guardandoFechaInicio}
            style={{ background:theme.accent, border:"none", borderRadius:8, padding:"9px 14px", color:"#fff", fontSize:12, fontWeight:700, cursor:"pointer" }}>
            {guardandoFechaInicio ? "Guardando..." : "Guardar"}
          </button>
        </div>
      </Card>

      {/* Rutinas existentes */}
      {loading ? (
        <Card style={{ textAlign:"center", padding:20 }}><div style={{ color:theme.muted }}>Cargando...</div></Card>
      ) : rutinas.length > 0 ? (
        <div style={{ marginBottom:14 }}>
          <div style={{ fontSize:12, color:theme.muted, marginBottom:10 }}>RUTINAS ASIGNADAS</div>
          {rutinas.map(r => (
            <Card key={r.id} style={{ marginBottom:8 }}>
              <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:6 }}>
                {r.grupo_muscular && <ImagenGrupoMuscular nombre={r.grupo_muscular} mapa={mapaImagenesGrupoMuscular} size={30} />}
                <div style={{ fontSize:14, fontWeight:800, color:theme.text, textTransform:"uppercase", letterSpacing:0.4, lineHeight:1.3, display:"-webkit-box", WebkitLineClamp:2, WebkitBoxOrient:"vertical", overflow:"hidden" }}>💪 {r.nombre}</div>
              </div>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:8, gap:6, flexWrap:"nowrap" }}>
                <div style={{ display:"flex", alignItems:"center", gap:6, minWidth:0, overflow:"hidden" }}>
                  <Tag>{r.dia || "Sin día"}</Tag>
                  {r.grupo_muscular && <Tag>{r.grupo_muscular}</Tag>}
                  {r.created_at && <span style={{ fontSize:10, color:theme.muted, whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>{new Date(r.created_at).toLocaleDateString("es-CL", { day:"2-digit", month:"short" })}</span>}
                </div>
                <div style={{ display:"flex", gap:4, alignItems:"center", flexShrink:0 }}>
                  <button onClick={() => {
                      if (creando && editandoRutinaId === r.id) {
                        // Ya está abierto en acordeón: se cierra sin guardar --
                        // volver a apretar "Editar" es la forma de salir sin
                        // tener que llegar hasta el botón Guardar/Cancelar.
                        setCreando(false); setModoDuplicar(false); setModoPlantilla(false); setGuardarPlantillaAbierto(false); setEditandoRutinaId(null);
                      } else {
                        cargarParaEditar(r, "editar");
                      }
                    }}
                    style={{ background: creando && editandoRutinaId === r.id ? `${theme.muted}22` : `${theme.success}22`, border:`1px solid ${creando && editandoRutinaId === r.id ? theme.muted : theme.success}44`, borderRadius:6, padding:"4px 7px", color: creando && editandoRutinaId === r.id ? theme.muted : theme.success, fontSize:11, cursor:"pointer", fontWeight:700, whiteSpace:"nowrap" }}>
                    {creando && editandoRutinaId === r.id ? "▲ Cerrar" : "✏️ Editar"}
                  </button>
                  <button onClick={async () => {
                    if (!confirm(`¿Seguro que querés eliminar la rutina "${r.nombre}"? También se borrará el historial de cargas registradas en sus ejercicios.`)) return;
                    const idsEjercicios = (r.ejercicios || []).map(ej => ej.id);
                    if (idsEjercicios.length > 0) {
                      const { error: errReg } = await supabase.from("registros_entreno").delete().in("ejercicio_id", idsEjercicios);
                      if (errReg) { alert("Error borrando cargas registradas: " + errReg.message); return; }
                    }
                    const { error: errEj } = await supabase.from("ejercicios").delete().eq("rutina_id", r.id);
                    if (errEj) { alert("Error borrando ejercicios: " + errEj.message); return; }
                    const { error: errRut } = await supabase.from("rutinas").delete().eq("id", r.id);
                    if (errRut) { alert("Error borrando rutina: " + errRut.message); return; }
                    cargarRutinas();
                  }} title="Eliminar rutina" style={{ background:`${theme.danger}22`, border:`1px solid ${theme.danger}44`, borderRadius:6, padding:"4px 8px", color:theme.danger, fontSize:12, cursor:"pointer", fontWeight:700 }}>×</button>
                </div>
              </div>
              <button onClick={() => setRutinaExpandida(prev => ({ ...prev, [r.id]: !prev[r.id] }))}
                style={{ background:"transparent", border:"none", padding:0, color:theme.accentLight, fontSize:12, cursor:"pointer", display:"flex", alignItems:"center", gap:4 }}>
                {rutinaExpandida[r.id] ? "▲" : "▼"} {r.ejercicios?.length || 0} ejercicios
              </button>
              {rutinaExpandida[r.id] && (r.ejercicios || []).slice().sort((a, b) => (a.orden || 0) - (b.orden || 0)).map((ej, i) => (
                <div key={i} style={{ marginTop: 6 }}>
                  <div style={{ fontSize:12, color:theme.muted, paddingLeft:8 }}>· {ej.nombre}</div>
                  {cargas[ej.id] && (
                    <div style={{ paddingLeft:16, marginTop:4 }}>
                      <button onClick={() => setVerCargas(prev => ({ ...prev, [ej.id]: !prev[ej.id] }))}
                        style={{ background:`${theme.accent}15`, border:`1px solid ${theme.accent}33`, borderRadius:6, padding:"3px 8px", color:theme.accentLight, fontSize:10, cursor:"pointer", marginBottom:4 }}>
                        {verCargas[ej.id] ? "▲ Ocultar cargas" : `▼ Ver cargas (${cargas[ej.id].length} series)`}
                      </button>
                      {verCargas[ej.id] && (
                        <div style={{ display:"grid", gridTemplateColumns:"repeat(4, 1fr)", gap:6 }}>
                          {cargas[ej.id].slice(0, 8).map((c, ci) => (
                            <div key={ci} style={{ minWidth:0, background:theme.surface, border:`1px solid ${theme.border}`, borderRadius:8, padding:"4px 4px", textAlign:"center" }}>
                              <div style={{ fontSize:9, color:theme.muted, whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>S{c.serie} · {c.fecha}</div>
                              <div style={{ fontSize:12, fontWeight:800, color:theme.text, whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>{c.kg}kg</div>
                              <div style={{ fontSize:10, color:theme.muted, whiteSpace:"nowrap" }}>×{c.reps}</div>
                            </div>
                          ))}
                        </div>
                      )}
                    </div>
                  )}
                </div>
              ))}
              {creando && editandoRutinaId === r.id && (
                <div style={{ marginTop:12, borderTop:`1px solid ${theme.border}`, paddingTop:12 }}>
                  {formularioContenido}
                </div>
              )}
            </Card>
          ))}
        </div>
      ) : null}

      {/* Botón crear / usar plantilla */}
      {!creando ? (
        <div style={{ display:"flex", gap:8, flexWrap:"wrap" }}>
          <Btn onClick={() => { setModoDuplicar(false); setModoPlantilla(false); setEditandoRutinaId(null); setCalentamientoGeneral([]); setVueltaCalma([]); setCardio([]); setMetaPasos("10000"); setEjerciciosEliminados([]); setAproxExpandida({}); setCreando(true); }}>+ Crear Nueva Rutina</Btn>
          <Btn variant="ghost" onClick={() => setMostrarPlantillas(!mostrarPlantillas)}>📋 Usar plantilla {mostrarPlantillas ? "▲" : "▼"}</Btn>
        </div>
      ) : null}

      {!creando && mostrarPlantillas && (
        <Card style={{ marginTop:10 }}>
          <div style={{ fontSize:12, color:theme.muted, marginBottom:10 }}>PLANTILLAS GUARDADAS</div>
          {plantillas.length === 0 ? (
            <div style={{ fontSize:13, color:theme.muted }}>Todavía no guardaste ninguna plantilla. Arma una rutina y usa "💾 Guardar como plantilla" para reutilizarla con otros alumnos.</div>
          ) : plantillas.map(p => (
            <div key={p.id} style={{ display:"flex", justifyContent:"space-between", alignItems:"center", padding:"8px 0", borderBottom:`1px solid ${theme.border}` }}>
              <div>
                <div style={{ fontSize:13, fontWeight:700, color:theme.text }}>{p.nombre}</div>
                <div style={{ fontSize:11, color:theme.muted }}>{p.dia || "Sin día"} · {(p.ejercicios || []).length} ejercicios</div>
              </div>
              <div style={{ display:"flex", gap:6 }}>
                <button onClick={() => usarPlantilla(p)} style={{ background:`${theme.accent}22`, border:`1px solid ${theme.accent}44`, borderRadius:6, padding:"4px 8px", color:theme.accentLight, fontSize:11, cursor:"pointer", fontWeight:700 }}>Usar</button>
                <button onClick={() => eliminarPlantilla(p)} style={{ background:`${theme.danger}22`, border:`1px solid ${theme.danger}44`, borderRadius:6, padding:"4px 8px", color:theme.danger, fontSize:11, cursor:"pointer", fontWeight:700 }}>× Eliminar</button>
              </div>
            </div>
          ))}
        </Card>
      )}

      {creando && editandoRutinaId === null && (
        <div ref={formRef}>
        <Card>
          {formularioContenido}
        </Card>
        </div>
      )}
    </div>
  );
}

function MensajesCoach({ alumno }) {
  const [mensajes, setMensajes] = useState([]);
  const [texto, setTexto] = useState("");
  const [loading, setLoading] = useState(true);

  useEffect(() => {
cargarMensajes();  }, [alumno]);

  const cargarMensajes = async () => {
    if (!alumno?.id) return;
    const { data } = await supabase
      .from("mensajes")
      .select("*")
      .eq("usuario_id", alumno.id)
      .order("created_at", { ascending: true });
    if (data) setMensajes(data);
    marcarLeidos();
    setLoading(false);
  };

  const marcarLeidos = async () => {
    if (!alumno?.id) return;
    await supabase.from("mensajes").update({ leido: true }).eq("usuario_id", alumno.id).eq("de", "alumno").eq("leido", false);
  };
  const responder = async () => {
    if (!texto.trim()) return;
    await supabase.from("mensajes").insert({
      usuario_id: alumno.id,
      de: "coach",
      texto: texto.trim(),
    });
    setTexto("");
    cargarMensajes();
  };

  return (
    <div style={{ display: "flex", flexDirection: "column", height: 500 }}>
      <div style={{ flex: 1, overflowY: "auto", marginBottom: 10 }}>
        {loading ? (
          <div style={{ color: theme.muted, textAlign: "center", padding: 20 }}>Cargando...</div>
        ) : mensajes.length === 0 ? (
          <Card style={{ textAlign: "center", padding: 30 }}>
            <div style={{ fontSize: 24, marginBottom: 8 }}>💬</div>
            <div style={{ color: theme.muted, fontSize: 13 }}>Sin mensajes de {alumno?.nombre}</div>
          </Card>
        ) : (
          mensajes.map((m, i) => (
            <div key={i} style={{ display: "flex", justifyContent: m.de === "coach" ? "flex-end" : "flex-start", marginBottom: 10 }}>
              <div style={{
                background: m.de === "coach" ? theme.accent : theme.card,
                border: `1px solid ${m.de === "coach" ? theme.accent : theme.border}`,
                borderRadius: 12, padding: "10px 14px", maxWidth: "75%",
              }}>
                <div style={{ fontSize: 11, color: m.de === "coach" ? "rgba(255,255,255,0.7)" : theme.muted, marginBottom: 3 }}>
                  {m.de === "coach" ? "Tú (coach)" : alumno?.nombre}
                </div>
                <div style={{ fontSize: 13, color: theme.text, lineHeight: 1.5 }}>{m.texto}</div>
                <div style={{ fontSize: 10, color: m.de === "coach" ? "rgba(255,255,255,0.5)" : theme.muted, marginTop: 4 }}>
                  {new Date(m.created_at).toLocaleDateString("es-CL", { day: "numeric", month: "short", hour: "2-digit", minute: "2-digit" })}
                </div>
              </div>
            </div>
          ))
        )}
      </div>
      <div style={{ display: "flex", gap: 8 }}>
        <input
          value={texto}
          onChange={e => setTexto(e.target.value)}
          onKeyDown={e => e.key === "Enter" && responder()}
          placeholder="Responder..."
          style={{ flex: 1, background: theme.surface, border: `1px solid ${theme.border}`, borderRadius: 10, padding: "10px 14px", color: theme.text, fontSize: 13, outline: "none" }}
        />
        <button onClick={responder} style={{ background: theme.accent, border: "none", borderRadius: 10, padding: "10px 16px", color: "#fff", fontWeight: 700, fontSize: 14, cursor: "pointer" }}>→</button>
      </div>
    </div>
  );
}function DiarioCoach({ alumno }) {
  const [ciclos, setCiclos] = useState([]);
  const [loading, setLoading] = useState(true);
  const [entrenosDetalle, setEntrenosDetalle] = useState([]);
  const [dietaRegs, setDietaRegs] = useState([]);
  const [diasPlanificados, setDiasPlanificados] = useState(0);
  const [semanaExpandida, setSemanaExpandida] = useState(null);
  const [diaExpandido, setDiaExpandido] = useState(null);
  const [cicloExpandido, setCicloExpandido] = useState(null);
  const [edicionSerie, setEdicionSerie] = useState(null);
  const [edicionKg, setEdicionKg] = useState("");
  const [edicionReps, setEdicionReps] = useState("");
  const [edicionComida, setEdicionComida] = useState(null);
  const [edicionEstado, setEdicionEstado] = useState("");
  const [edicionDescripcion, setEdicionDescripcion] = useState("");
  const diasNombre = ["Dom","Lun","Mar","Mié","Jue","Vie","Sáb"];
  const SEMANAS_POR_CICLO = 4;
  const COLOR_RPE = "#B0C4DE";
  const COLOR_SUENO = "#39FF88";

  const iniciarEdicionSerie = (s) => { setEdicionSerie(s.id); setEdicionKg(s.kg ?? ""); setEdicionReps(s.reps ?? ""); };
  const cancelarEdicionSerie = () => setEdicionSerie(null);
  const guardarEdicionSerie = async (id) => {
    const kgNum = edicionKg === "" ? null : parseFloat(edicionKg);
    const repsNum = edicionReps === "" ? null : parseInt(edicionReps);
    const { error } = await supabase.from("registros_entreno").update({ kg: kgNum, reps: repsNum }).eq("id", id);
    if (error) { alert("No se pudo actualizar la serie: " + error.message); return; }
    setEntrenosDetalle(prev => prev.map(r => r.id === id ? { ...r, kg: kgNum, reps: repsNum } : r));
    setEdicionSerie(null);
  };
  const iniciarEdicionComida = (r) => { setEdicionComida(r.id); setEdicionEstado(r.estado); setEdicionDescripcion(r.descripcion || ""); };
  const cancelarEdicionComida = () => setEdicionComida(null);
  const guardarEdicionComida = async (id) => {
    const descripcionFinal = edicionEstado === "cambio" ? edicionDescripcion : null;
    const { error } = await supabase.from("dieta_registros").update({ estado: edicionEstado, descripcion: descripcionFinal }).eq("id", id);
    if (error) { alert("No se pudo actualizar la comida: " + error.message); return; }
    setDietaRegs(prev => prev.map(r => r.id === id ? { ...r, estado: edicionEstado, descripcion: descripcionFinal } : r));
    setEdicionComida(null);
  };
  useEffect(() => {
    const cargar = async () => {
      if (!alumno?.id) return;
      // La construcción de ciclos/semanas es compartida con el resumen que ve
      // el propio alumno en Progreso (ver cargarCiclosAlumno a nivel de módulo),
      // así ambas vistas arrancan siempre desde la misma fecha (fecha_inicio_plan
      // si el coach la definió, si no el primer registro del alumno).
      const { ciclos: ciclosArr, entrenosDetalle: entrenos, dietaRegs: dietaR, diasPlanificados: dp } =
        await cargarCiclosAlumno(alumno.id, alumno?.fecha_inicio_plan);
      setDiasPlanificados(dp);
      setEntrenosDetalle(entrenos);
      setDietaRegs(dietaR);
      setCiclos(ciclosArr);
      setLoading(false);
    };
    cargar();
  }, [alumno]);

  if (loading) return <Card style={{ textAlign:"center", padding:20 }}><div style={{ color:theme.muted }}>Cargando...</div></Card>;

  const todosDias = ciclos.flatMap(c => c.semanas.flatMap(s => s.dias));
  const conDatos = todosDias.filter(d => d.energia !== null);
  if (conDatos.length === 0) return (
    <Card style={{ textAlign:"center", padding:30 }}>
      <div style={{ fontSize:24, marginBottom:8 }}>🌙</div>
      <div style={{ color:theme.muted, fontSize:13 }}>{alumno?.nombre || "Este alumno"} aún no registró su diario</div>
    </Card>
  );

  const cicloActivo = ciclos.find(c => c.esActivo);
  const diasCicloActivo = cicloActivo ? cicloActivo.semanas.flatMap(s => s.dias) : [];
  const conDatosActivo = diasCicloActivo.filter(d => d.energia !== null);
  const promedioEnergia = conDatosActivo.length ? (conDatosActivo.reduce((a,b) => a + b.energia, 0) / conDatosActivo.length).toFixed(1) : "—";
  const promedioSueno = conDatosActivo.length ? (conDatosActivo.reduce((a,b) => a + b.sueno, 0) / conDatosActivo.length).toFixed(1) : "—";
  const semanasConDatosActivo = cicloActivo ? cicloActivo.semanas.filter(s => s.dias.some(d => d.energia !== null)).length : 0;

  const iconEstado = (estado) => estado === "completada" ? "✅" : estado === "no_hecha" ? "❌" : estado === "cambio" ? "🔄" : "⬜";

  // Calcula el resumen (RPE, sueño, cargas, adherencia dieta) de una semana
  const resumenSemana = (semana) => {
    const diasConDatos = semana.dias.filter(d => d.energia !== null);
    const fechasSemana = new Set(semana.dias.map(d => d.fechaStr));
    const entrenosSemana = entrenosDetalle.filter(r => fechasSemana.has(r.fecha));
    const dietaSemana = dietaRegs.filter(r => fechasSemana.has(r.fecha));

    const rpeValues = diasConDatos.map(d => d.energia);
    const suenoValues = diasConDatos.map(d => d.sueno);
    const diasEntrenados = semana.dias.filter(d => d.entreno).length;

    const dietaCompletadas = dietaSemana.filter(r => r.estado === "completada").length;
    const adherenciaDieta = dietaSemana.length > 0 ? Math.round((dietaCompletadas / dietaSemana.length) * 100) : null;

    const ejerciciosSemana = {};
    entrenosSemana.forEach(r => {
      const nombre = r.ejercicios?.nombre || "Ejercicio";
      if (!ejerciciosSemana[nombre]) ejerciciosSemana[nombre] = { kgs: [], repsMax: 0 };
      if (r.kg) ejerciciosSemana[nombre].kgs.push(r.kg);
      if (r.reps) ejerciciosSemana[nombre].repsMax = Math.max(ejerciciosSemana[nombre].repsMax, r.reps);
    });

    return {
      rpeProm: rpeValues.length ? (rpeValues.reduce((a,b)=>a+b,0)/rpeValues.length).toFixed(1) : null,
      rpeMin: rpeValues.length ? Math.min(...rpeValues) : null,
      rpeMax: rpeValues.length ? Math.max(...rpeValues) : null,
      suenoProm: suenoValues.length ? (suenoValues.reduce((a,b)=>a+b,0)/suenoValues.length).toFixed(1) : null,
      diasEntrenados,
      adherenciaDieta,
      ejerciciosSemana,
    };
  };

  const ctx = {
    resumenSemana, semanaExpandida, setSemanaExpandida, diaExpandido, setDiaExpandido,
    diasPlanificados, entrenosDetalle, dietaRegs,
    edicionSerie, edicionKg, setEdicionKg, edicionReps, setEdicionReps,
    guardarEdicionSerie, cancelarEdicionSerie, iniciarEdicionSerie,
    edicionComida, edicionEstado, setEdicionEstado, edicionDescripcion, setEdicionDescripcion,
    guardarEdicionComida, cancelarEdicionComida, iniciarEdicionComida,
    COLOR_RPE, COLOR_SUENO, iconEstado,
  };


  const ciclosOrdenados = [...ciclos].reverse(); // el ciclo activo (más reciente) primero

  return (
    <div>
      <div style={{ fontSize:11, color:theme.muted, marginBottom:10 }}>El ciclo actual (4 semanas) queda siempre arriba. Toca una semana para ver su resumen, y un día puntual para el detalle completo. Los ciclos anteriores quedan guardados abajo, colapsados.</div>
      <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:10, marginBottom:14 }}>
        <Card style={{ padding:12, textAlign:"center" }}>
          <div style={{ fontSize:16 }}>⚡</div>
          <div style={{ fontSize:20, fontWeight:900, color:COLOR_RPE, marginTop:4 }}>{promedioEnergia}/10</div>
          <div style={{ fontSize:9, color:theme.muted }}>Intensidad prom. (ciclo actual{semanasConDatosActivo ? ` · ${semanasConDatosActivo}/${SEMANAS_POR_CICLO} sem.` : ""})</div>
        </Card>
        <Card style={{ padding:12, textAlign:"center" }}>
          <div style={{ fontSize:16 }}>😴</div>
          <div style={{ fontSize:20, fontWeight:900, color:COLOR_SUENO, marginTop:4 }}>{promedioSueno}/10</div>
          <div style={{ fontSize:9, color:theme.muted }}>Sueño prom. (ciclo actual{semanasConDatosActivo ? ` · ${semanasConDatosActivo}/${SEMANAS_POR_CICLO} sem.` : ""})</div>
        </Card>
      </div>

      {ciclosOrdenados.map((ciclo) => {
        if (ciclo.esActivo) {
          // El ciclo activo se muestra siempre desplegado, semana actual arriba
          const semanasOrden = [...ciclo.semanas].reverse();
          return (
            <div key={ciclo.key} style={{ marginBottom:16 }}>
              <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:8 }}>
                <div style={{ fontSize:12, fontWeight:800, color:theme.accentLight, letterSpacing:0.5 }}>🔵 CICLO ACTUAL</div>
                <div style={{ fontSize:11, color:theme.muted }}>{ciclo.rango}</div>
              </div>
              {semanasOrden.map(semana => <SemanaCard key={semana.key} semana={semana} ctx={ctx} />)}
            </div>
          );
        }

        // Ciclos anteriores: colapsados, se agrupan y no se pierden
        const cicloExp = cicloExpandido === ciclo.key;
        const semanasOrden = [...ciclo.semanas].reverse();
        return (
          <Card key={ciclo.key} style={{ marginBottom:10, padding:0, overflow:"hidden", border:`1px solid ${theme.border}` }}>
            <div onClick={() => setCicloExpandido(cicloExp ? null : ciclo.key)}
              style={{ padding:14, cursor:"pointer", display:"flex", justifyContent:"space-between", alignItems:"center" }}>
              <div>
                <div style={{ fontSize:12, fontWeight:800, color:theme.muted }}>Ciclo {ciclo.numeroCiclo}</div>
                <div style={{ fontSize:11, color:theme.muted, marginTop:2 }}>{ciclo.rango}</div>
              </div>
              <span style={{ fontSize:11, color:theme.accentLight }}>{cicloExp ? "▲ ocultar" : "▼ ver detalle"}</span>
            </div>
            {cicloExp && (
              <div style={{ padding:"0 14px 14px" }}>
                {semanasOrden.map(semana => <SemanaCard key={semana.key} semana={semana} ctx={ctx} />)}
              </div>
            )}
          </Card>
        );
      })}
    </div>
  );
}function CheckinsCoach({ alumno }) {
  const [checkins, setCheckins] = useState([]);
  const [loading, setLoading] = useState(true);
  const [lightbox, setLightbox] = useState(null);

  useEffect(() => {
    const cargar = async () => {
      if (!alumno?.id) return;
      const { data } = await supabase
        .from("checkins")
        .select("*")
        .eq("usuario_id", alumno.id)
        .order("fecha", { ascending: false });
      if (data) setCheckins(data);
      setLoading(false);
    };
    cargar();
  }, [alumno]);

  if (loading) return <Card style={{ textAlign:"center", padding:20 }}><div style={{ color:theme.muted }}>Cargando...</div></Card>;

  if (checkins.length === 0) return (
    <Card style={{ textAlign:"center", padding:30 }}>
      <div style={{ fontSize:24, marginBottom:8 }}>📊</div>
      <div style={{ color:theme.muted, fontSize:13 }}>Aún no hay check-ins de {alumno?.nombre || "este alumno"}</div>
    </Card>
  );

  return (
    <div>
      {checkins.map((c, i) => (
        <Card key={i} style={{ marginBottom:12 }}>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:10 }}>
            <div style={{ fontSize:14, fontWeight:700, color:theme.text }}>📅 {c.fecha}</div>
            <div style={{ textAlign:"right" }}>
              <div style={{ fontSize:20, fontWeight:900, color:theme.accent }}>{c.peso} kg</div>
              {c.porc_grasa && <div style={{ fontSize:12, color:"#B0C4DE", fontWeight:700 }}>{c.porc_grasa}% grasa</div>}
            </div>
          </div>
          <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr 1fr 1fr", gap:8, marginBottom:8 }}>
            {[["Cintura", c.cintura], ["Cadera", c.cadera], ["Brazo", c.brazo], ["Pecho", c.pecho], ["Pierna", c.pierna]].map(([label, val]) => (
              <div key={label} style={{ background:theme.surface, borderRadius:8, padding:"6px 8px", textAlign:"center" }}>
                <div style={{ fontSize:10, color:theme.muted }}>{label}</div>
                <div style={{ fontSize:13, fontWeight:700, color:theme.text }}>{val || "—"} cm</div>
              </div>
            ))}
          </div>
          {c.comentarios && (
            <div style={{ fontSize:12, color:theme.muted, fontStyle:"italic", borderTop:`1px solid ${theme.border}`, paddingTop:8 }}>
              "{c.comentarios}"
            </div>
          )}
          {(c.foto_frente || c.foto_espalda || c.foto_perf_der || c.foto_perf_izq) && (
            <div style={{ marginTop:10 }}>
              <div style={{ fontSize:11, color:theme.muted, marginBottom:6 }}>📸 FOTOS</div>
              <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr 1fr", gap:6 }}>
                {[["Frente", c.foto_frente], ["Espalda", c.foto_espalda], ["P. Der", c.foto_perf_der], ["P. Izq", c.foto_perf_izq]].map(([label, url]) => url && (
                  <div key={label} style={{ borderRadius:8, overflow:"hidden", border:`1px solid ${theme.border}` }}>
                    <img src={url} alt={label} onClick={() => setLightbox(url)} style={{ width:"100%", height:80, objectFit:"cover", cursor:"pointer" }} />
                    <div style={{ fontSize:9, color:theme.muted, textAlign:"center", padding:3 }}>{label}</div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </Card>
      ))}
      <ImageLightbox src={lightbox} onClose={() => setLightbox(null)} />
    </div>
  );
}

// Campos de la anamnesis que el coach puede corregir desde el perfil del
// alumno (todo salvo el email, que va ligado a la cuenta de autenticación,
// y las fotos iniciales, que se suben aparte).
const CAMPOS_EDITABLES_ANAMNESIS = [
  "nombre", "edad", "sexo", "estatura", "peso_actual", "porc_grasa",
  "whatsapp", "instagram", "ocupacion", "actividad_laboral",
  "objetivo", "ha_entrenado", "que_entrenamiento", "dias_semana", "horario_entreno", "horario_entreno_hasta",
  "enfermedad_lesion", "cual_enfermedad", "medicamento", "cual_medicamento",
  "sustancia_farmacologica", "sustancia_cuales", "sustancia_tiempo", "sustancia_hace_cuanto",
  "consume_suplemento", "cual_suplemento",
  "alimentacion_diferente", "alergia", "cual_alergia", "no_le_gustan", "favoritos",
  "hora_levanta", "hora_duerme", "comidas_dia",
  "resumen_desayuno", "resumen_snack", "resumen_almuerzo", "resumen_once", "resumen_cena",
  "fecha_inicio_plan",
];

function CoachAlumno({ onNav, alumno }) {
  const tabs=["Datos","Rutina","Dieta","Check-ins","Diario","Pagos","Progreso","Mensajes"];
  const [tab,setTab]=useState(alumno?.tabInicial || "Datos");
  const [datosCompletos, setDatosCompletos] = useState(null);
  const [lightbox, setLightbox] = useState(null);
  const [editandoDatos, setEditandoDatos] = useState(false);
  const [formDatos, setFormDatos] = useState(null);
  const [guardandoDatos, setGuardandoDatos] = useState(false);

  const cargarDatos = async () => {
    if (!alumno?.id) return;
    const { data } = await supabase
      .from("usuarios")
      .select("*")
      .eq("id", alumno.id)
      .single();
    if (data) setDatosCompletos(data);
  };

  useEffect(() => { cargarDatos(); }, [alumno]);

  const iniciarEdicion = () => {
    const inicial = {};
    CAMPOS_EDITABLES_ANAMNESIS.forEach(k => { inicial[k] = datosCompletos?.[k] ?? ""; });
    setFormDatos(inicial);
    setEditandoDatos(true);
  };

  const cancelarEdicion = () => {
    setEditandoDatos(false);
    setFormDatos(null);
  };

  const guardarDatos = async () => {
    if (!alumno?.id || !formDatos) return;
    setGuardandoDatos(true);
    const cambios = {};
    CAMPOS_EDITABLES_ANAMNESIS.forEach(k => {
      let v = formDatos[k];
      if (["edad", "estatura", "peso_actual", "porc_grasa"].includes(k)) {
        v = v === "" || v === null || v === undefined ? null : parseFloat(v);
      } else if (v === "") {
        v = null;
      }
      cambios[k] = v;
    });
    const { error } = await supabase.from("usuarios").update(cambios).eq("id", alumno.id);
    setGuardandoDatos(false);
    if (error) {
      alert("Error al guardar: " + error.message);
      return;
    }
    await cargarDatos();
    setEditandoDatos(false);
    setFormDatos(null);
  };

  const setCampo = (k, v) => setFormDatos(prev => ({ ...prev, [k]: v }));

  return (
    <div style={{ height:"100%",display:"flex",flexDirection:"column" }}>
      <div style={{ padding:"16px 16px 0",background:theme.surface,borderBottom:`1px solid ${theme.border}` }}>
        <div style={{ display:"flex",alignItems:"center",gap:12,marginBottom:14 }}>
          <span onClick={()=>onNav("coach_panel")} style={{ color:theme.accent,cursor:"pointer",fontSize:20 }}>←</span>
          <div style={{ flex:1 }}>
            <div style={{ fontSize:18,fontWeight:800,color:theme.text }}>{alumno?.nombre || "Sin nombre"}</div>
            <div style={{ fontSize:12,color:theme.muted }}>{alumno?.objetivo || "Sin objetivo"} · {alumno?.peso_actual ? alumno.peso_actual + " kg" : "Sin peso"}</div>
          </div>
          <Tag color={theme.success}>✓ Activo</Tag>
        </div>
        <div style={{ display:"flex",gap:4,overflowX:"auto",paddingBottom:12 }}>
          {tabs.map(t=>(<button key={t} onClick={()=>setTab(t)} style={{ background:tab===t?theme.accent:"transparent",border:`1px solid ${tab===t?theme.accent:theme.border}`,borderRadius:8,padding:"6px 12px",color:tab===t?"#fff":theme.muted,fontSize:12,fontWeight:600,cursor:"pointer",whiteSpace:"nowrap" }}>{t}</button>))}
        </div>
      </div>
      <div style={{ flex:1,overflowY:"auto",padding:16 }}>
        {tab==="Datos"&&(<div style={{ display:"flex",flexDirection:"column",gap:10 }}>
          <div style={{ display:"flex", justifyContent:"flex-end", gap:8 }}>
            {!editandoDatos ? (
              <button onClick={iniciarEdicion} style={{ background:theme.accent, border:"none", borderRadius:8, padding:"8px 14px", color:"#fff", fontSize:12, fontWeight:700, cursor:"pointer" }}>✏️ Editar datos</button>
            ) : (
              <>
                <button onClick={cancelarEdicion} disabled={guardandoDatos} style={{ background:"transparent", border:`1px solid ${theme.border}`, borderRadius:8, padding:"8px 14px", color:theme.muted, fontSize:12, fontWeight:700, cursor:"pointer" }}>Cancelar</button>
                <button onClick={guardarDatos} disabled={guardandoDatos} style={{ background:theme.success, border:"none", borderRadius:8, padding:"8px 14px", color:"#fff", fontSize:12, fontWeight:700, cursor:"pointer" }}>{guardandoDatos ? "Guardando..." : "✓ Guardar cambios"}</button>
              </>
            )}
          </div>

          {!editandoDatos ? (
            <>
              <Card>
                <div style={{ fontSize:12,color:theme.muted,marginBottom:10 }}>DATOS PERSONALES</div>
                {[
                  ["Nombre", datosCompletos?.nombre],
                  ["Email", datosCompletos?.email],
                  ["Edad", datosCompletos?.edad ? datosCompletos.edad + " años" : null],
                  ["Sexo", datosCompletos?.sexo],
                  ["Estatura", datosCompletos?.estatura ? datosCompletos.estatura + " cm" : null],
                  ["Peso actual", datosCompletos?.peso_actual ? datosCompletos.peso_actual + " kg" : null],
                  ["% grasa estimado", datosCompletos?.porc_grasa ? datosCompletos.porc_grasa + " %" : null],
                  ["WhatsApp", datosCompletos?.whatsapp],
                  ["Instagram", datosCompletos?.instagram],
                  ["Ocupación", datosCompletos?.ocupacion],
                  ["Actividad laboral", datosCompletos?.actividad_laboral],
                ].filter(([,v]) => v).map(([k,v])=>(
                  <div key={k} style={{ display:"flex",justifyContent:"space-between",marginBottom:8,flexWrap:"wrap",gap:4 }}>
                    <span style={{ color:theme.muted,fontSize:13 }}>{k}</span>
                    <span style={{ color:theme.text,fontSize:13,fontWeight:600,textAlign:"right",maxWidth:"60%" }}>{v}</span>
                  </div>
                ))}
              </Card>
              <Card>
                <div style={{ fontSize:12,color:theme.muted,marginBottom:10 }}>ANAMNESIS</div>
                {[
                  ["Objetivo", datosCompletos?.objetivo],
                  ["Ha entrenado", datosCompletos?.ha_entrenado],
                  ["Entrenamiento previo", datosCompletos?.que_entrenamiento],
                  ["Días/semana", datosCompletos?.dias_semana],
                  ["Horario entreno", datosCompletos?.horario_entreno_hasta ? `${datosCompletos?.horario_entreno || "?"} y ${datosCompletos.horario_entreno_hasta}` : datosCompletos?.horario_entreno],
                  ["Enfermedad/Lesión", datosCompletos?.enfermedad_lesion === "Sí" ? datosCompletos?.cual_enfermedad : "No"],
                  ["Medicamento", datosCompletos?.medicamento === "Sí" ? datosCompletos?.cual_medicamento : "No"],
                  ["Sustancias farmacológicas", datosCompletos?.sustancia_farmacologica === "Sí" ? [datosCompletos?.sustancia_cuales, datosCompletos?.sustancia_tiempo && `por ${datosCompletos.sustancia_tiempo}`, datosCompletos?.sustancia_hace_cuanto && `(${datosCompletos.sustancia_hace_cuanto})`].filter(Boolean).join(" · ") || "Sí" : datosCompletos?.sustancia_farmacologica],
                  ["Suplemento actual", datosCompletos?.consume_suplemento === "Sí" ? (datosCompletos?.cual_suplemento || "Sí") : datosCompletos?.consume_suplemento],
                  ["Fecha inicio plan", datosCompletos?.fecha_inicio_plan],
                ].filter(([,v]) => v).map(([k,v])=>(
                  <div key={k} style={{ display:"flex",justifyContent:"space-between",marginBottom:8,flexWrap:"wrap",gap:4 }}>
                    <span style={{ color:theme.muted,fontSize:13 }}>{k}</span>
                    <span style={{ color:theme.text,fontSize:13,fontWeight:600,textAlign:"right",maxWidth:"60%" }}>{v}</span>
                  </div>
                ))}
              </Card>
              {(datosCompletos?.foto_frente || datosCompletos?.foto_espalda || datosCompletos?.foto_perf_der || datosCompletos?.foto_perf_izq) && (
                <Card>
                  <div style={{ fontSize:12,color:theme.muted,marginBottom:10 }}>📸 FOTOS INICIALES (ANAMNESIS)</div>
                  <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr 1fr", gap:6 }}>
                    {[["Frente", datosCompletos.foto_frente], ["Espalda", datosCompletos.foto_espalda], ["P. Der", datosCompletos.foto_perf_der], ["P. Izq", datosCompletos.foto_perf_izq]].map(([label, url]) => url && (
                      <div key={label} style={{ borderRadius:8, overflow:"hidden", border:`1px solid ${theme.border}` }}>
                        <img src={url} alt={label} onClick={() => setLightbox(url)} style={{ width:"100%", height:80, objectFit:"cover", cursor:"pointer" }} />
                        <div style={{ fontSize:9, color:theme.muted, textAlign:"center", padding:3 }}>{label}</div>
                      </div>
                    ))}
                  </div>
                </Card>
              )}
              <Card>
                <div style={{ fontSize:12,color:theme.muted,marginBottom:10 }}>ALIMENTACIÓN</div>
                {[
                  ["Alergias", datosCompletos?.alergia === "Sí" ? datosCompletos?.cual_alergia : "No"],
                  ["No le gustan", datosCompletos?.no_le_gustan],
                  ["Favoritos", datosCompletos?.favoritos],
                  ["Dieta especial", datosCompletos?.alimentacion_diferente],
                  ["Hora levantarse", datosCompletos?.hora_levanta],
                  ["Hora dormir", datosCompletos?.hora_duerme],
                  ["Comidas al día", datosCompletos?.comidas_dia],
                ].filter(([,v]) => v).map(([k,v])=>(
                  <div key={k} style={{ display:"flex",justifyContent:"space-between",marginBottom:8,flexWrap:"wrap",gap:4 }}>
                    <span style={{ color:theme.muted,fontSize:13 }}>{k}</span>
                    <span style={{ color:theme.text,fontSize:13,fontWeight:600,textAlign:"right",maxWidth:"60%" }}>{v}</span>
                  </div>
                ))}
                {datosCompletos?.resumen_desayuno && (
                  <div style={{ marginTop:10 }}>
                    <div style={{ fontSize:11,color:theme.muted,marginBottom:8,fontWeight:700 }}>RESUMEN DIETA TÍPICA</div>
                    {[
                      ["🌅 Desayuno", datosCompletos?.resumen_desayuno],
                      ["🍎 Snack", datosCompletos?.resumen_snack],
                      ["🍽️ Almuerzo", datosCompletos?.resumen_almuerzo],
                      ["☕ Once", datosCompletos?.resumen_once],
                      ["🌙 Cena", datosCompletos?.resumen_cena],
                    ].filter(([,v]) => v).map(([k,v])=>(
                      <div key={k} style={{ marginBottom:8, background:theme.surface, borderRadius:8, padding:"8px 10px" }}>
                        <div style={{ fontSize:11,color:theme.muted,marginBottom:2 }}>{k}</div>
                        <div style={{ fontSize:13,color:theme.text }}>{v}</div>
                      </div>
                    ))}
                  </div>
                )}
              </Card>
            </>
          ) : (
            <>
              <Card>
                <div style={{ fontSize:12,color:theme.muted,marginBottom:10 }}>DATOS PERSONALES</div>
                <CampoEditable campo="nombre" label="Nombre completo" formDatos={formDatos} setCampo={setCampo} />
                <CampoEditable campo="edad" label="Edad" tipo="number" formDatos={formDatos} setCampo={setCampo} />
                <CampoEditable campo="sexo" label="Sexo" tipo="select" opciones={["Masculino","Femenino","Otro"]} formDatos={formDatos} setCampo={setCampo} />
                <CampoEditable campo="estatura" label="Estatura (cm)" tipo="number" formDatos={formDatos} setCampo={setCampo} />
                <CampoEditable campo="peso_actual" label="Peso actual (kg)" tipo="number" formDatos={formDatos} setCampo={setCampo} />
                <CampoEditable campo="porc_grasa" label="% grasa estimado" tipo="number" formDatos={formDatos} setCampo={setCampo} />
                <CampoEditable campo="whatsapp" label="WhatsApp" formDatos={formDatos} setCampo={setCampo} />
                <CampoEditable campo="instagram" label="Instagram" formDatos={formDatos} setCampo={setCampo} />
                <CampoEditable campo="ocupacion" label="Ocupación" formDatos={formDatos} setCampo={setCampo} />
                <CampoEditable campo="actividad_laboral" label="Actividad laboral diaria" tipo="textarea" formDatos={formDatos} setCampo={setCampo} />
                <CampoEditable campo="fecha_inicio_plan" label="Fecha de inicio del plan (opcional)" tipo="date" formDatos={formDatos} setCampo={setCampo} />
              </Card>
              <Card>
                <div style={{ fontSize:12,color:theme.muted,marginBottom:10 }}>ANAMNESIS</div>
                <CampoEditable campo="objetivo" label="Objetivo principal" tipo="select" opciones={["Bajar grasa","Ganar masa muscular","Recomposición corporal","Mejorar rendimiento deportivo","Mantener peso y mejorar salud"]} formDatos={formDatos} setCampo={setCampo} />
                <CampoEditable campo="ha_entrenado" label="Ha entrenado antes" tipo="select" opciones={["Sí","No"]} formDatos={formDatos} setCampo={setCampo} />
                {formDatos?.ha_entrenado === "Sí" && <CampoEditable campo="que_entrenamiento" label="Qué entrenamiento o deporte" formDatos={formDatos} setCampo={setCampo} />}
                <CampoEditable campo="dias_semana" label="Días de entreno a la semana" tipo="select" opciones={["1 día","2 días","3 días","4 días","5 días","6 días"]} formDatos={formDatos} setCampo={setCampo} />
                <span style={editLabelStyle}>Horario de entreno</span>
                <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:10 }}>
                  <input style={{ ...editInputStyle, flex:1 }} type="time" value={formDatos?.horario_entreno ?? ""} onChange={e => setCampo("horario_entreno", e.target.value)} />
                  <span style={{ color:theme.muted, fontSize:12 }}>y</span>
                  <input style={{ ...editInputStyle, flex:1 }} type="time" value={formDatos?.horario_entreno_hasta ?? ""} onChange={e => setCampo("horario_entreno_hasta", e.target.value)} />
                </div>
                <CampoEditable campo="enfermedad_lesion" label="¿Enfermedad o lesión?" tipo="select" opciones={["Sí","No"]} formDatos={formDatos} setCampo={setCampo} />
                {formDatos?.enfermedad_lesion === "Sí" && <CampoEditable campo="cual_enfermedad" label="Cuál enfermedad o lesión" formDatos={formDatos} setCampo={setCampo} />}
                <CampoEditable campo="medicamento" label="¿Toma algún medicamento?" tipo="select" opciones={["Sí","No"]} formDatos={formDatos} setCampo={setCampo} />
                {formDatos?.medicamento === "Sí" && <CampoEditable campo="cual_medicamento" label="Cuál medicamento" formDatos={formDatos} setCampo={setCampo} />}
                <CampoEditable campo="sustancia_farmacologica" label="Sustancias farmacológicas" tipo="select" opciones={["Sí","No","Prefiero no responder"]} formDatos={formDatos} setCampo={setCampo} />
                {formDatos?.sustancia_farmacologica === "Sí" && (<>
                  <CampoEditable campo="sustancia_cuales" label="Cuáles sustancias" formDatos={formDatos} setCampo={setCampo} />
                  <CampoEditable campo="sustancia_tiempo" label="Por cuánto tiempo" formDatos={formDatos} setCampo={setCampo} />
                  <CampoEditable campo="sustancia_hace_cuanto" label="Hace cuánto tiempo" formDatos={formDatos} setCampo={setCampo} />
                </>)}
                <CampoEditable campo="consume_suplemento" label="¿Consume algún suplemento actualmente?" tipo="select" opciones={["Sí","No"]} formDatos={formDatos} setCampo={setCampo} />
                {formDatos?.consume_suplemento === "Sí" && <CampoEditable campo="cual_suplemento" label="Cuál suplemento" formDatos={formDatos} setCampo={setCampo} />}
              </Card>
              <Card>
                <div style={{ fontSize:12,color:theme.muted,marginBottom:10 }}>ALIMENTACIÓN</div>
                <CampoEditable campo="alimentacion_diferente" label="Alimentación especial" formDatos={formDatos} setCampo={setCampo} />
                <CampoEditable campo="alergia" label="¿Alergia a algún alimento/medicamento?" tipo="select" opciones={["Sí","No"]} formDatos={formDatos} setCampo={setCampo} />
                {formDatos?.alergia === "Sí" && <CampoEditable campo="cual_alergia" label="Cuál alergia" formDatos={formDatos} setCampo={setCampo} />}
                <CampoEditable campo="no_le_gustan" label="Alimentos que no le gustan" formDatos={formDatos} setCampo={setCampo} />
                <CampoEditable campo="favoritos" label="Alimentos favoritos" formDatos={formDatos} setCampo={setCampo} />
                <CampoEditable campo="hora_levanta" label="Hora de levantarse" tipo="time" formDatos={formDatos} setCampo={setCampo} />
                <CampoEditable campo="hora_duerme" label="Hora de dormir" tipo="time" formDatos={formDatos} setCampo={setCampo} />
                <CampoEditable campo="comidas_dia" label="Comidas al día" tipo="select" opciones={["1","2","3","4","5","6","Más de 6"]} formDatos={formDatos} setCampo={setCampo} />
                <CampoEditable campo="resumen_desayuno" label="🌅 Desayuno típico" formDatos={formDatos} setCampo={setCampo} />
                <CampoEditable campo="resumen_snack" label="🍎 Snack típico" formDatos={formDatos} setCampo={setCampo} />
                <CampoEditable campo="resumen_almuerzo" label="🍽️ Almuerzo típico" formDatos={formDatos} setCampo={setCampo} />
                <CampoEditable campo="resumen_once" label="☕ Once típica" formDatos={formDatos} setCampo={setCampo} />
                <CampoEditable campo="resumen_cena" label="🌙 Cena típica" formDatos={formDatos} setCampo={setCampo} />
              </Card>
              <Card>
                <div style={{ fontSize:12,color:theme.muted,marginBottom:10 }}>📸 FOTOS INICIALES (ANAMNESIS)</div>
                <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr 1fr", gap:6 }}>
                  {[
                    ["frente","Frente","foto_frente"],
                    ["espalda","Espalda","foto_espalda"],
                    ["perfDer","P. Der","foto_perf_der"],
                    ["perfIzq","P. Izq","foto_perf_izq"],
                  ].map(([key,label,dbCol]) => (
                    <FotoEditable
                      key={key}
                      userId={alumno?.id}
                      campoKey={key}
                      label={label}
                      urlActual={datosCompletos?.[dbCol]}
                      onSubida={(url) => setDatosCompletos(prev => ({ ...prev, [dbCol]: url }))}
                    />
                  ))}
                </div>
              </Card>
            </>
          )}
        </div>)}
        {tab==="Check-ins"&&(<CheckinsCoach alumno={alumno}/>)}
        {tab==="Diario"&&(<DiarioCoach alumno={{ ...alumno, ...(datosCompletos||{}) }}/>)}
{tab==="Mensajes"&&(<MensajesCoach alumno={alumno}/>)}
        {tab==="Rutina"&&(<RutinaCoach alumno={{ ...alumno, ...(datosCompletos||{}) }}/>)}
        {tab==="Dieta"&&(<DietaCoach alumno={alumno}/>)}
        {tab==="Pagos"&&(<PagosCoach alumno={alumno}/>)}
        {tab==="Progreso"&&(
          <Card style={{ textAlign:"center",padding:40 }}>
            <div style={{ fontSize:32,marginBottom:10 }}>📈</div>
            <div style={{ fontSize:15,fontWeight:700,color:theme.text,marginBottom:6 }}>Progreso de {alumno?.nombre || "alumno"}</div>
            <div style={{ fontSize:13,color:theme.muted,marginBottom:16 }}>Próximamente</div>
          </Card>
        )}
      </div>
      <ImageLightbox src={lightbox} onClose={() => setLightbox(null)} />
    </div>
  );
}

const COACH_EMAIL = "coach.claudiomiquel@gmail.com";

// Un alumno ya completó la anamnesis si su fila en "usuarios" tiene nombre
// guardado — esa fila solo se crea/actualiza al final del formulario de
// anamnesis (ver AnamnesisScreen), así que sirve como bandera confiable.
async function anamnesisCompleta(userId) {
  const { data } = await supabase.from("usuarios").select("nombre").eq("id", userId).maybeSingle();
  return !!data?.nombre;
}

export default function App() {
  const [screen, setScreen] = useState("login");
  const [alumnoSeleccionado, setAlumnoSeleccionado] = useState(null);
  const [emailPendiente, setEmailPendiente] = useState("");
  const navCoachAlumno = (alumno) => {
    setAlumnoSeleccionado(alumno);
    setScreen("coach_alumno");
  };

  // Guía para agregar la app a la pantalla de inicio: se muestra el mismo
  // tipo de mensaje explicando los pasos a mano tanto en iPhone como en
  // Android (a propósito no se usa el botón nativo de "instalar" que ofrece
  // Chrome en Android, para que los alumnos de ambas plataformas tengan la
  // misma experiencia). Se muestra una sola vez -- si la persona la cierra,
  // no se le vuelve a mostrar en ese celular -- y no aparece si ya está
  // corriendo instalada desde el ícono.
  const [mostrarGuiaInstalar, setMostrarGuiaInstalar] = useState(false);
  const [guiaInstalarTexto, setGuiaInstalarTexto] = useState(null);
  useEffect(() => {
    const ua = navigator.userAgent;
    const esIOS = /iPad|iPhone|iPod/.test(ua) && !window.MSStream;
    const esAndroid = /Android/.test(ua);
    const yaInstalada = window.navigator.standalone === true || window.matchMedia("(display-mode: standalone)").matches;
    let yaDescartada = false;
    try { yaDescartada = localStorage.getItem("guiaInstalarDescartada") === "1"; } catch (e) {}
    if (yaInstalada || yaDescartada) return;
    if (esIOS) {
      setGuiaInstalarTexto(<>Toca el botón <b style={{ color:theme.text }}>Compartir</b> ⬆️ en la barra de abajo del navegador, y luego elige <b style={{ color:theme.text }}>"Agregar a inicio"</b>.</>);
      setMostrarGuiaInstalar(true);
    } else if (esAndroid) {
      setGuiaInstalarTexto(<>Toca el menú <b style={{ color:theme.text }}>⋮</b> (los tres puntos, arriba a la derecha de Chrome), y luego elige <b style={{ color:theme.text }}>"Instalar aplicación"</b> o <b style={{ color:theme.text }}>"Agregar a pantalla de inicio"</b>.</>);
      setMostrarGuiaInstalar(true);
    }
  }, []);
  const cerrarGuiaInstalar = () => {
    setMostrarGuiaInstalar(false);
    try { localStorage.setItem("guiaInstalarDescartada", "1"); } catch (e) {}
  };

  // Detecta cuándo hay una sesión activa (al cargar la app si ya había una
  // guardada, o justo después de que el alumno confirma su correo — Supabase
  // procesa el enlace del correo, guarda la sesión y dispara "SIGNED_IN")
  // y enruta según corresponda, en vez de dejarlo tirado en la pantalla de
  // "revisa tu correo" o en el login.
  useEffect(() => {
    let activo = true;
    // Solo se auto-enruta UNA vez por carga de la app (al restaurar sesión al
    // abrir, o al confirmar el correo). Sin esto, cada vez que el celular
    // vuelve del segundo plano (cambiás de app y volvés), Supabase revalida
    // el token y puede volver a emitir "SIGNED_IN" — y sin esta bandera eso
    // mandaba a la persona de vuelta al Inicio aunque estuviera navegando
    // en otra pantalla. El login manual y el botón "Salir" ya navegan por
    // su cuenta (ver LoginScreen y el botón Salir del coach), así que no
    // dependen de este listener y no se ven afectados por la bandera.
    let yaEnrutado = false;
    const enrutarSesion = async (session) => {
      if (!session?.user || !activo || yaEnrutado) return;
      yaEnrutado = true;
      if (session.user.email === COACH_EMAIL) {
        setScreen("coach_panel");
        return;
      }
      const completa = await anamnesisCompleta(session.user.id);
      if (!activo) return;
      setScreen(completa ? "alumno_home" : "anamnesis");
    };

    supabase.auth.getSession().then(({ data }) => {
      if (data?.session) enrutarSesion(data.session);
    });

    const { data: listener } = supabase.auth.onAuthStateChange((event, session) => {
      if (event === "SIGNED_IN") enrutarSesion(session);
    });

    return () => { activo = false; listener?.subscription?.unsubscribe(); };
  }, []);

  const renderScreen = () => {
    switch(screen) {
      case "login": return <LoginScreen onNav={setScreen}/>;
      case "registro": return <RegistroScreen onNav={setScreen} onRegistroExitoso={setEmailPendiente}/>;
      case "confirmar_correo": return <ConfirmarCorreoScreen onNav={setScreen} email={emailPendiente}/>;
      case "anamnesis": return <AnamnesisScreen onNav={setScreen}/>;
      case "alumno_home": return <AlumnoHome onNav={setScreen}/>;
      case "rutina": return <RutinaScreen onNav={setScreen}/>;
      case "nutricion": return <NutricionScreen onNav={setScreen}/>;
      case "diario": return <DiarioScreen onNav={setScreen}/>;
      case "checkin": return <CheckinScreen onNav={setScreen}/>;
      case "mensajes": return <MensajesScreen onNav={setScreen}/>;
      case "progreso": return <ProgresoScreen onNav={setScreen}/>;
      case "pagos_alumno": return <PagosAlumnoScreen onNav={setScreen}/>;
      case "coach_panel": return <CoachPanel onNav={setScreen} onVerAlumno={navCoachAlumno}/>;
      case "coach_alumno": return <CoachAlumno onNav={setScreen} alumno={alumnoSeleccionado}/>;
      default: return <LoginScreen onNav={setScreen}/>;
    }
  };

  return (
    <div style={{ background:"#0d0d1a",minHeight:"100vh",display:"flex",alignItems:"center",justifyContent:"center",fontFamily:"'Inter',-apple-system,sans-serif",padding:16 }}>
      <div style={{ textAlign:"center" }}>
        <div style={{ fontSize:11,color:"#444",marginBottom:10,letterSpacing:2 }}>MIQUEL COACH PERFORMANCE · PROTOTIPO</div>
        <div style={{ position:"relative",width:375,height:720,margin:"0 auto" }}>
          <div style={{ position:"absolute",inset:-12,border:"12px solid #1e1e2e",borderRadius:48,boxShadow:"0 0 0 2px #2e2e3e, 0 32px 80px rgba(0,0,0,0.9)",pointerEvents:"none",zIndex:10 }}/>
          <div style={{ position:"absolute",top:-18,left:"50%",transform:"translateX(-50%)",width:90,height:7,background:"#1e1e2e",borderRadius:4,zIndex:11 }}/>
          <div style={{ width:375,height:720,background:theme.bg,borderRadius:36,overflow:"auto",position:"relative" }}>
            {renderScreen()}
            {mostrarGuiaInstalar && (
              <div style={{ position:"absolute", top:12, left:12, right:12, zIndex:3000, background:theme.card, border:`1px solid ${theme.accentLight}66`, borderRadius:12, padding:"12px 14px", boxShadow:`0 4px 20px rgba(0,0,0,0.5), 0 0 18px ${theme.accent}44` }}>
                <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", gap:8 }}>
                  <div style={{ fontSize:12, fontWeight:800, color:theme.text }}>📲 Instala esta app en tu celular</div>
                  <span onClick={cerrarGuiaInstalar} style={{ cursor:"pointer", color:theme.muted, fontSize:14, lineHeight:1, flexShrink:0 }}>✕</span>
                </div>
                <div style={{ fontSize:11, color:theme.muted, marginTop:6, lineHeight:1.5 }}>
                  {guiaInstalarTexto} Así te queda como una app normal, sin tener que entrar por el navegador cada vez.
                </div>
              </div>
            )}
          </div>
        </div>
        <div style={{ marginTop:20,display:"flex",gap:8,flexWrap:"wrap",justifyContent:"center",maxWidth:420 }}>
          {[["login","Login"],["registro","Registro"],["confirmar_correo","Confirmar correo"],["anamnesis","Anamnesis"],["alumno_home","Inicio"],["rutina","Rutina"],["nutricion","Dieta"],["checkin","Check-in"],["progreso","Progreso"],["coach_panel","Coach Panel"],["coach_alumno","Perfil Alumno"]].map(([id,label])=>(<button key={id} onClick={()=>setScreen(id)} style={{ background:screen===id?"#2563EB":"#13131a",border:`1px solid ${screen===id?"#2563EB":"#2a2a38"}`,color:screen===id?"#fff":"#666",borderRadius:8,padding:"6px 12px",fontSize:11,cursor:"pointer",fontWeight:600 }}>{label}</button>))}
        </div>
      </div>
    </div>
  );
}
